INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('198a78c5-1f7c-506f-ae0d-2efdeb04ae1a', '9fb16ed5-5cbc-586e-ae42-66930956fc90', NULL, 11, 11, 'They gave the money that was weighed out into the hands of those who did the work, who had the oversight of the house of Yahweh: and they paid it out to the carpenters and the builders, who worked on the house of Yahweh,'),
  ('c08e7510-3cb4-5739-a492-e59fc2f10dd7', '9fb16ed5-5cbc-586e-ae42-66930956fc90', NULL, 12, 12, 'and to the masons and the stone cutters, and for buying timber and cut stone to repair the breaches of the house of Yahweh, and for all that was laid out for the house to repair it.'),
  ('39df5712-54d5-5e85-a050-e6610e6c73b1', '9fb16ed5-5cbc-586e-ae42-66930956fc90', NULL, 13, 13, 'But there were not made for the house of Yahweh cups of silver, snuffers, basins, trumpets, any vessels of gold, or vessels of silver, of the money that was brought into the house of Yahweh;'),
  ('fe658621-2829-5e31-a593-8f560ea15838', '9fb16ed5-5cbc-586e-ae42-66930956fc90', NULL, 14, 14, 'for they gave that to those who did the work, and repaired therewith the house of Yahweh.'),
  ('3e08c6c8-7bad-5445-a22e-aadb1701fb8a', '9fb16ed5-5cbc-586e-ae42-66930956fc90', NULL, 15, 15, 'Moreover they didn''t demand an accounting from the men into whose hand they delivered the money to give to those who did the work; for they dealt faithfully.'),
  ('4e3602f3-0e8b-532d-a68f-36cfa60ab0e5', '9fb16ed5-5cbc-586e-ae42-66930956fc90', NULL, 16, 16, 'The money for the trespass offerings, and the money for the sin offerings, was not brought into the house of Yahweh: it was the priests''.'),
  ('4e36a8f0-7935-5963-ae82-b102153fa948', '9fb16ed5-5cbc-586e-ae42-66930956fc90', NULL, 17, 17, 'Then Hazael king of Syria went up, and fought against Gath, and took it; and Hazael set his face to go up to Jerusalem.'),
  ('3fff90bf-9c13-5396-a928-ab803ba692ab', '9fb16ed5-5cbc-586e-ae42-66930956fc90', NULL, 18, 18, 'Jehoash king of Judah took all the holy things that Jehoshaphat and Jehoram and Ahaziah, his fathers, kings of Judah, had dedicated, and his own holy things, and all the gold that was found in the treasures of the house of Yahweh, and of the king''s house, and sent it to Hazael king of Syria: and he went away from Jerusalem.'),
  ('d511d152-413b-517a-a42c-086b653eb7e0', '9fb16ed5-5cbc-586e-ae42-66930956fc90', NULL, 19, 19, 'Now the rest of the acts of Joash, and all that he did, aren''t they written in the book of the chronicles of the kings of Judah?'),
  ('5d08aadd-bde2-56bc-a436-af7afb3e5c73', '9fb16ed5-5cbc-586e-ae42-66930956fc90', NULL, 20, 20, 'His servants arose, and made a conspiracy, and struck Joash at the house of Millo, [on the way] that goes down to Silla.'),
  ('bb5a224f-504f-58ae-afb1-6e8b9e6412d1', '9fb16ed5-5cbc-586e-ae42-66930956fc90', NULL, 21, 21, 'For Jozacar the son of Shimeath, and Jehozabad the son of Shomer, his servants, struck him, and he died; and they buried him with his fathers in the city of David: and Amaziah his son reigned in his place.'),
  ('af77329a-d6c3-53b8-a170-af67d82df14a', '99f14474-f944-54f5-a443-b959d027959f', NULL, 1, 1, 'In the three and twentieth year of Joash the son of Ahaziah, king of Judah, Jehoahaz the son of Jehu began to reign over Israel in Samaria, [and reigned] seventeen years.'),
  ('51a5b0ed-6b32-5c7c-ae8b-d3d8738d1676', '99f14474-f944-54f5-a443-b959d027959f', NULL, 2, 2, 'He did that which was evil in the sight of Yahweh, and followed the sins of Jeroboam the son of Nebat, with which he made Israel to sin; he didn''t depart from it.'),
  ('eb225247-c66b-50d9-a78e-92761d90b77d', '99f14474-f944-54f5-a443-b959d027959f', NULL, 3, 3, 'The anger of Yahweh was kindled against Israel, and he delivered them into the hand of Hazael king of Syria, and into the hand of Benhadad the son of Hazael, continually.'),
  ('231f3f77-9de5-5ee5-a0b8-16709c553628', '99f14474-f944-54f5-a443-b959d027959f', NULL, 4, 4, 'Jehoahaz begged Yahweh, and Yahweh listened to him; for he saw the oppression of Israel, how that the king of Syria oppressed them.'),
  ('7f086f15-80fa-5660-a3b2-365f92dbbf63', '99f14474-f944-54f5-a443-b959d027959f', NULL, 5, 5, '(Yahweh gave Israel a savior, so that they went out from under the hand of the Syrians; and the children of Israel lived in their tents as before.'),
  ('9717dd90-bf0d-56ea-a2f7-20015fc203a8', '99f14474-f944-54f5-a443-b959d027959f', NULL, 6, 6, 'Nevertheless they didn''t depart from the sins of the house of Jeroboam, with which he made Israel to sin, but walked therein: and there remained the Asherah also in Samaria.)'),
  ('729b689f-1163-5dbc-aa99-3cdcc098adcf', '99f14474-f944-54f5-a443-b959d027959f', NULL, 7, 7, 'For he didn''t leave to Jehoahaz of the people any more than fifty horsemen, and ten chariots, and ten thousand footmen; for the king of Syria destroyed them, and made them like the dust in threshing.'),
  ('b569a0d4-8630-5926-a95d-43aa815602a1', '99f14474-f944-54f5-a443-b959d027959f', NULL, 8, 8, 'Now the rest of the acts of Jehoahaz, and all that he did, and his might, aren''t they written in the book of the chronicles of the kings of Israel?'),
  ('0c836a10-c393-50f6-ac9d-3c876257507f', '99f14474-f944-54f5-a443-b959d027959f', NULL, 9, 9, 'Jehoahaz slept with his fathers; and they buried him in Samaria: and Joash his son reigned in his place.'),
  ('dbe1fdf6-f2b3-5b36-a18a-5c5222c8dea7', '99f14474-f944-54f5-a443-b959d027959f', NULL, 10, 10, 'In the thirty-seventh year of Joash king of Judah began Jehoash the son of Jehoahaz to reign over Israel in Samaria, [and reigned] sixteen years.'),
  ('dba30361-2e86-584f-a758-fb3ef6fe11c2', '99f14474-f944-54f5-a443-b959d027959f', NULL, 11, 11, 'He did that which was evil in the sight of Yahweh; he didn''t depart from all the sins of Jeroboam the son of Nebat, with which he made Israel to sin; but he walked therein.'),
  ('0ba21691-d421-5459-a4e0-517182e1edbc', '99f14474-f944-54f5-a443-b959d027959f', NULL, 12, 12, 'Now the rest of the acts of Joash, and all that he did, and his might with which he fought against Amaziah king of Judah, aren''t they written in the book of the chronicles of the kings of Israel?'),
  ('ec1104ef-b515-5be6-a087-aa9f5bfa576e', '99f14474-f944-54f5-a443-b959d027959f', NULL, 13, 13, 'Joash slept with his fathers; and Jeroboam sat on his throne: and Joash was buried in Samaria with the kings of Israel.'),
  ('6509842b-4b15-5c08-a47a-636907171dbc', '99f14474-f944-54f5-a443-b959d027959f', NULL, 14, 14, 'Now Elisha was fallen sick of his sickness of which he died: and Joash the king of Israel came down to him, and wept over him, and said, "My father, my father, the chariots of Israel and its horsemen!"'),
  ('1aa98493-33fa-5a46-a1ac-a4b7820d5458', '99f14474-f944-54f5-a443-b959d027959f', NULL, 15, 15, 'Elisha said to him, "Take bow and arrows;" and he took to him bow and arrows.'),
  ('14372ef7-b4e6-5edc-ac1d-69cf1d77c8c8', '99f14474-f944-54f5-a443-b959d027959f', NULL, 16, 16, 'He said to the king of Israel, "Put your hand on the bow;" and he put his hand [on it]. Elisha laid his hands on the king''s hands.'),
  ('c97be0f5-f8f9-56ba-a1a6-ec44c3f7c86a', '99f14474-f944-54f5-a443-b959d027959f', NULL, 17, 17, 'He said, "Open the window eastward;" and he opened it. Then Elisha said, "Shoot!" and he shot. He said, "Yahweh''s arrow of victory, even the arrow of victory over Syria; for you shall strike the Syrians in Aphek, until you have consumed them."'),
  ('8bdd2846-92ff-5be4-a787-072462c61294', '99f14474-f944-54f5-a443-b959d027959f', NULL, 18, 18, 'He said, "Take the arrows;" and he took them. He said to the king of Israel, "Strike the ground;" and he struck three times, and stopped.'),
  ('1fb202f3-d3f3-54c0-a619-188e0438556c', '99f14474-f944-54f5-a443-b959d027959f', NULL, 19, 19, 'The man of God was angry with him, and said, "You should have struck five or six times. Then you would have struck Syria until you had consumed it, whereas now you shall strike Syria just three times."'),
  ('8f7f83c2-5248-5066-a987-74e69e344e77', '99f14474-f944-54f5-a443-b959d027959f', NULL, 20, 20, 'Elisha died, and they buried him. Now the bands of the Moabites invaded the land at the coming in of the year.'),
  ('eb4d1b3f-2140-5d08-a726-462858c9544f', '99f14474-f944-54f5-a443-b959d027959f', NULL, 21, 21, 'It happened, as they were burying a man, that behold, they spied a band; and they cast the man into the tomb of Elisha: and as soon as the man touched the bones of Elisha, he revived, and stood up on his feet.'),
  ('b754ef5c-a55b-5d1a-a976-593b35262a1c', '99f14474-f944-54f5-a443-b959d027959f', NULL, 22, 22, 'Hazael king of Syria oppressed Israel all the days of Jehoahaz.'),
  ('99b5237e-b32b-5e07-aa72-71bbb1d23373', '99f14474-f944-54f5-a443-b959d027959f', NULL, 23, 23, 'But Yahweh was gracious to them, and had compassion on them, and had respect to them, because of his covenant with Abraham, Isaac, and Jacob, and would not destroy them, neither cast he them from his presence as yet.'),
  ('93b4c578-6cba-5089-af05-6844c3bc84e1', '99f14474-f944-54f5-a443-b959d027959f', NULL, 24, 24, 'Hazael king of Syria died; and Benhadad his son reigned in his place.'),
  ('d8a2c277-e780-5cc8-a807-d564ccb5717d', '99f14474-f944-54f5-a443-b959d027959f', NULL, 25, 25, 'Jehoash the son of Jehoahaz took again out of the hand of Benhadad the son of Hazael the cities which he had taken out of the hand of Jehoahaz his father by war. Three times did Joash strike him, and recovered the cities of Israel.'),
  ('4ced9e4f-2d9b-5233-a7e3-5ebba9047e75', 'cdc39355-1c5e-5db3-af71-9153ca352be5', NULL, 1, 1, 'In the second year of Joash son of Joahaz king of Israel began Amaziah the son of Joash king of Judah to reign.'),
  ('dd1ab0eb-f346-5161-a76d-754208e41507', 'cdc39355-1c5e-5db3-af71-9153ca352be5', NULL, 2, 2, 'He was twenty-five years old when he began to reign; and he reigned twenty-nine years in Jerusalem: and his mother''s name was Jehoaddin of Jerusalem.'),
  ('ccd82cb1-af1a-510f-a45d-10fae013a6df', 'cdc39355-1c5e-5db3-af71-9153ca352be5', NULL, 3, 3, 'He did that which was right in the eyes of Yahweh, yet not like David his father: he did according to all that Joash his father had done.'),
  ('7fdf3828-48f3-5345-abc5-6e421b98a51f', 'cdc39355-1c5e-5db3-af71-9153ca352be5', NULL, 4, 4, 'However the high places were not taken away: the people still sacrificed and burnt incense in the high places.'),
  ('b30e53e4-a399-5c12-a264-88af35d29077', 'cdc39355-1c5e-5db3-af71-9153ca352be5', NULL, 5, 5, 'It happened, as soon as the kingdom was established in his hand, that he killed his servants who had slain the king his father:'),
  ('95bf8126-dbdb-51c7-a476-bf0cc40943da', 'cdc39355-1c5e-5db3-af71-9153ca352be5', NULL, 6, 6, 'but the children of the murderers he didn''t put to death; according to that which is written in the book of the law of Moses, as Yahweh commanded, saying, "The fathers shall not be put to death for the children, nor the children be put to death for the fathers; but every man shall die for his own sin."'),
  ('121d065b-9c01-565e-a737-b375622b8990', 'cdc39355-1c5e-5db3-af71-9153ca352be5', NULL, 7, 7, 'He killed of Edom in the Valley of Salt ten thousand, and took Sela by war, and called its name Joktheel, to this day.'),
  ('705be51c-445e-545f-aca6-936cebd3f4f3', 'cdc39355-1c5e-5db3-af71-9153ca352be5', NULL, 8, 8, 'Then Amaziah sent messengers to Jehoash, the son of Jehoahaz son of Jehu, king of Israel, saying, "Come, let us look one another in the face."'),
  ('75d6244f-6007-502c-a25a-048730c442b1', 'cdc39355-1c5e-5db3-af71-9153ca352be5', NULL, 9, 9, 'Jehoash the king of Israel sent to Amaziah king of Judah, saying, "The thistle that was in Lebanon sent to the cedar that was in Lebanon, saying, ''Give your daughter to my son as wife. Then a wild animal that was in Lebanon passed by, and trampled down the thistle.'),
  ('1dfc69e4-d380-5a84-afd4-d3b124330f9e', 'cdc39355-1c5e-5db3-af71-9153ca352be5', NULL, 10, 10, 'You have indeed struck Edom, and your heart has lifted you up. Enjoy the glory of it, and stay at home; for why should you meddle to your harm, that you should fall, even you, and Judah with you?''"'),
  ('ebb90d15-85ca-539b-af2f-de1ba3900505', 'cdc39355-1c5e-5db3-af71-9153ca352be5', NULL, 11, 11, 'But Amaziah would not listen. So Jehoash king of Israel went up; and he and Amaziah king of Judah looked one another in the face at Beth Shemesh, which belongs to Judah.'),
  ('cf2eb95a-abfc-503d-abbe-1c5750ae2c99', 'cdc39355-1c5e-5db3-af71-9153ca352be5', NULL, 12, 12, 'Judah was defeated by Israel; and they fled every man to his tent.'),
  ('f0d17316-5b86-588a-a8e4-e03caa260c13', 'cdc39355-1c5e-5db3-af71-9153ca352be5', NULL, 13, 13, 'Jehoash king of Israel took Amaziah king of Judah, the son of Jehoash the son of Ahaziah, at Beth Shemesh, and came to Jerusalem, and broke down the wall of Jerusalem from the gate of Ephraim to the corner gate, four hundred cubits.'),
  ('8155434d-9ea8-58b5-a806-2ede18eaf62b', 'cdc39355-1c5e-5db3-af71-9153ca352be5', NULL, 14, 14, 'He took all the gold and silver, and all the vessels that were found in the house of Yahweh, and in the treasures of the king''s house, the hostages also, and returned to Samaria.'),
  ('83a417cc-e43a-5d3b-a61f-00c8c2af199d', 'cdc39355-1c5e-5db3-af71-9153ca352be5', NULL, 15, 15, 'Now the rest of the acts of Jehoash which he did, and his might, and how he fought with Amaziah king of Judah, aren''t they written in the book of the chronicles of the kings of Israel?'),
  ('dbc3a35f-c114-5684-a545-603cd87d831f', 'cdc39355-1c5e-5db3-af71-9153ca352be5', NULL, 16, 16, 'Jehoash slept with his fathers, and was buried in Samaria with the kings of Israel; and Jeroboam his son reigned in his place.'),
  ('ae084dbb-52c3-594d-a924-80b42d630052', 'cdc39355-1c5e-5db3-af71-9153ca352be5', NULL, 17, 17, 'Amaziah the son of Joash king of Judah lived after the death of Jehoash son of Jehoahaz king of Israel fifteen years.'),
  ('7263882e-8cc5-5edf-aeb6-bc537d7de615', 'cdc39355-1c5e-5db3-af71-9153ca352be5', NULL, 18, 18, 'Now the rest of the acts of Amaziah, aren''t they written in the book of the chronicles of the kings of Judah?'),
  ('23844e0a-113b-59de-a0bd-971a80f32f94', 'cdc39355-1c5e-5db3-af71-9153ca352be5', NULL, 19, 19, 'They made a conspiracy against him in Jerusalem; and he fled to Lachish: but they sent after him to Lachish, and killed him there.'),
  ('99552ddd-3a00-53cb-a57d-6163fcefa01f', 'cdc39355-1c5e-5db3-af71-9153ca352be5', NULL, 20, 20, 'They brought him on horses; and he was buried at Jerusalem with his fathers in the city of David.'),
  ('460589b4-a54e-5943-a7a6-d7bd8790624b', 'cdc39355-1c5e-5db3-af71-9153ca352be5', NULL, 21, 21, 'All the people of Judah took Azariah, who was sixteen years old, and made him king in the place of his father Amaziah.'),
  ('12caae2f-fe11-5264-a79b-f112e483d003', 'cdc39355-1c5e-5db3-af71-9153ca352be5', NULL, 22, 22, 'He built Elath, and restored it to Judah, after that the king slept with his fathers.'),
  ('9543dd10-5abc-573b-a168-db021d57e3fa', 'cdc39355-1c5e-5db3-af71-9153ca352be5', NULL, 23, 23, 'In the fifteenth year of Amaziah the son of Joash king of Judah Jeroboam the son of Joash king of Israel began to reign in Samaria, [and reigned] forty-one years.'),
  ('efc492b8-f3c6-52d8-a486-abafdeae01ce', 'cdc39355-1c5e-5db3-af71-9153ca352be5', NULL, 24, 24, 'He did that which was evil in the sight of Yahweh: he didn''t depart from all the sins of Jeroboam the son of Nebat, with which he made Israel to sin.'),
  ('8f11d455-473e-5844-a27e-601d09dd4d18', 'cdc39355-1c5e-5db3-af71-9153ca352be5', NULL, 25, 25, 'He restored the border of Israel from the entrance of Hamath to the sea of the Arabah, according to the word of Yahweh, the God of Israel, which he spoke by his servant Jonah the son of Amittai, the prophet, who was of Gath Hepher.'),
  ('ee822937-e586-5a5a-a15b-c2108fb0e559', 'cdc39355-1c5e-5db3-af71-9153ca352be5', NULL, 26, 26, 'For Yahweh saw the affliction of Israel, that it was very bitter; for there was none shut up nor left at large, neither was there any helper for Israel.'),
  ('72369c68-f808-5ff4-a6f4-efaefc3a3efb', 'cdc39355-1c5e-5db3-af71-9153ca352be5', NULL, 27, 27, 'Yahweh didn''t say that he would blot out the name of Israel from under the sky; but he saved them by the hand of Jeroboam the son of Joash.'),
  ('91bb55fa-dd80-542d-a11c-beb8577b9fec', 'cdc39355-1c5e-5db3-af71-9153ca352be5', NULL, 28, 28, 'Now the rest of the acts of Jeroboam, and all that he did, and his might, how he warred, and how he recovered Damascus, and Hamath, [which had belonged] to Judah, for Israel, aren''t they written in the book of the chronicles of the kings of Israel?'),
  ('fc4b0a55-1bf7-5124-a40c-cb91c857ae57', 'cdc39355-1c5e-5db3-af71-9153ca352be5', NULL, 29, 29, 'Jeroboam slept with his fathers, even with the kings of Israel; and Zechariah his son reigned in his place.'),
  ('5f2432cc-f6b1-5a5b-a60c-6910341c1a6f', '79ec464a-853f-533e-a10e-8039f9c04a83', NULL, 1, 1, 'In the twenty-seventh year of Jeroboam king of Israel began Azariah son of Amaziah king of Judah to reign.'),
  ('fb4698ec-4de7-57e6-abfc-2ff4eb6e0c1b', '79ec464a-853f-533e-a10e-8039f9c04a83', NULL, 2, 2, 'Sixteen years old was he when he began to reign; and he reigned fifty-two years in Jerusalem: and his mother''s name was Jecoliah of Jerusalem.'),
  ('396e2a5c-784f-5442-ab2e-da5919420cef', '79ec464a-853f-533e-a10e-8039f9c04a83', NULL, 3, 3, 'He did that which was right in the eyes of Yahweh, according to all that his father Amaziah had done.'),
  ('f0f02cd3-ed20-5978-a379-7e8ef7834217', '79ec464a-853f-533e-a10e-8039f9c04a83', NULL, 4, 4, 'However the high places were not taken away: the people still sacrificed and burnt incense in the high places.'),
  ('a48fc61e-4f26-5f67-af62-a77ca1faa0f8', '79ec464a-853f-533e-a10e-8039f9c04a83', NULL, 5, 5, 'Yahweh struck the king, so that he was a leper to the day of his death, and lived in a separate house. Jotham the king''s son was over the household, judging the people of the land.'),
  ('6989b38e-f6e2-566c-a9fa-63613498acc1', '79ec464a-853f-533e-a10e-8039f9c04a83', NULL, 6, 6, 'Now the rest of the acts of Azariah, and all that he did, aren''t they written in the book of the chronicles of the kings of Judah?'),
  ('852ea731-29d2-5a43-a89b-14cab7130204', '79ec464a-853f-533e-a10e-8039f9c04a83', NULL, 7, 7, 'Azariah slept with his fathers; and they buried him with his fathers in the city of David: and Jotham his son reigned in his place.'),
  ('d717c34e-43e6-5be9-afee-618369e0da64', '79ec464a-853f-533e-a10e-8039f9c04a83', NULL, 8, 8, 'In the thirty-eighth year of Azariah king of Judah did Zechariah the son of Jeroboam reign over Israel in Samaria six months.'),
  ('67408c0f-1409-5558-a6bc-5067649c4443', '79ec464a-853f-533e-a10e-8039f9c04a83', NULL, 9, 9, 'He did that which was evil in the sight of Yahweh, as his fathers had done: he didn''t depart from the sins of Jeroboam the son of Nebat, with which he made Israel to sin.'),
  ('22312d3f-93e8-5df4-abef-c1d27f300491', '79ec464a-853f-533e-a10e-8039f9c04a83', NULL, 10, 10, 'Shallum the son of Jabesh conspired against him, and struck him before the people, and killed him, and reigned in his place.'),
  ('4929a753-16eb-50b9-a61d-f6b205279f8e', '79ec464a-853f-533e-a10e-8039f9c04a83', NULL, 11, 11, 'Now the rest of the acts of Zechariah, behold, they are written in the book of the chronicles of the kings of Israel.'),
  ('8805d5f2-2d26-583f-a024-d3f70de66c7b', '79ec464a-853f-533e-a10e-8039f9c04a83', NULL, 12, 12, 'This was the word of Yahweh which he spoke to Jehu, saying, "Your sons to the fourth generation shall sit on the throne of Israel." So it came to pass.'),
  ('7522b51c-decf-5630-a642-86f65a2470ed', '79ec464a-853f-533e-a10e-8039f9c04a83', NULL, 13, 13, 'Shallum the son of Jabesh began to reign in the thirty-ninth year of Uzziah king of Judah; and he reigned for a month in Samaria.'),
  ('a666f5aa-2baf-5a11-a439-5261e19dd4b7', '79ec464a-853f-533e-a10e-8039f9c04a83', NULL, 14, 14, 'Menahem the son of Gadi went up from Tirzah, and came to Samaria, and struck Shallum the son of Jabesh in Samaria, and killed him, and reigned in his place.'),
  ('3e1da32d-335f-58d8-a21f-3d619b6791b6', '79ec464a-853f-533e-a10e-8039f9c04a83', NULL, 15, 15, 'Now the rest of the acts of Shallum, and his conspiracy which he made, behold, they are written in the book of the chronicles of the kings of Israel.'),
  ('72423671-4db6-56c0-a262-f38a0af63b9a', '79ec464a-853f-533e-a10e-8039f9c04a83', NULL, 16, 16, 'Then Menahem struck Tiphsah, and all who were therein, and its borders, from Tirzah: because they didn''t open to him, therefore he struck it; and all the women therein who were with child he ripped up.'),
  ('a90ceeb5-a7d0-50e7-a526-3f1c8934c6d7', '79ec464a-853f-533e-a10e-8039f9c04a83', NULL, 17, 17, 'In the nine and thirtieth year of Azariah king of Judah began Menahem the son of Gadi to reign over Israel, [and reigned] ten years in Samaria.'),
  ('15f86236-e800-54aa-a392-f46eaed44bc0', '79ec464a-853f-533e-a10e-8039f9c04a83', NULL, 18, 18, 'He did that which was evil in the sight of Yahweh: he didn''t depart all his days from the sins of Jeroboam the son of Nebat, with which he made Israel to sin.'),
  ('8e9cfc93-aee4-55b8-a75f-36ac023c2b0f', '79ec464a-853f-533e-a10e-8039f9c04a83', NULL, 19, 19, 'There came against the land Pul the king of Assyria; and Menahem gave Pul one thousand talents of silver, that his hand might be with him to confirm the kingdom in his hand.'),
  ('f110c035-cd07-55bc-a865-2bc59f2fbd13', '79ec464a-853f-533e-a10e-8039f9c04a83', NULL, 20, 20, 'Menahem exacted the money of Israel, even of all the mighty men of wealth, of each man fifty shekels of silver, to give to the king of Assyria. So the king of Assyria turned back, and didn''t stay there in the land.'),
  ('4a959843-1b8b-5d03-aad7-38b25adbd82a', '79ec464a-853f-533e-a10e-8039f9c04a83', NULL, 21, 21, 'Now the rest of the acts of Menahem, and all that he did, aren''t they written in the book of the chronicles of the kings of Israel?'),
  ('03eb844f-fcc0-5587-a49f-c304912e3c85', '79ec464a-853f-533e-a10e-8039f9c04a83', NULL, 22, 22, 'Menahem slept with his fathers; and Pekahiah his son reigned in his place.'),
  ('291e2b68-8b78-5e41-ae70-f4a5075a090c', '79ec464a-853f-533e-a10e-8039f9c04a83', NULL, 23, 23, 'In the fiftieth year of Azariah king of Judah Pekahiah the son of Menahem began to reign over Israel in Samaria, [and reigned] two years.'),
  ('2a98e3a3-04e7-5d62-a481-adf73ea406f0', '79ec464a-853f-533e-a10e-8039f9c04a83', NULL, 24, 24, 'He did that which was evil in the sight of Yahweh: he didn''t depart from the sins of Jeroboam the son of Nebat, with which he made Israel to sin.'),
  ('abab0d55-baf3-5b03-a832-382a6048fa9a', '79ec464a-853f-533e-a10e-8039f9c04a83', NULL, 25, 25, 'Pekah the son of Remaliah, his captain, conspired against him, and struck him in Samaria, in the castle of the king''s house, with Argob and Arieh; and with him were fifty men of the Gileadites: and he killed him, and reigned in his place.'),
  ('dc14cef5-ad42-566f-a351-cd9b0fbc520f', '79ec464a-853f-533e-a10e-8039f9c04a83', NULL, 26, 26, 'Now the rest of the acts of Pekahiah, and all that he did, behold, they are written in the book of the chronicles of the kings of Israel.'),
  ('8f27090b-bfaa-5f2b-a58e-c795bd3d183a', '79ec464a-853f-533e-a10e-8039f9c04a83', NULL, 27, 27, 'In the two and fiftieth year of Azariah king of Judah Pekah the son of Remaliah began to reign over Israel in Samaria, [and reigned] twenty years.'),
  ('4dc6b220-8d3a-5b9f-a1f9-c5b1459d7877', '79ec464a-853f-533e-a10e-8039f9c04a83', NULL, 28, 28, 'He did that which was evil in the sight of Yahweh: he didn''t depart from the sins of Jeroboam the son of Nebat, with which he made Israel to sin.'),
  ('7af55bc9-c01d-57a7-ad33-9a8fb470f191', '79ec464a-853f-533e-a10e-8039f9c04a83', NULL, 29, 29, 'In the days of Pekah king of Israel came Tiglath Pileser king of Assyria, and took Ijon, and Abel Beth Maacah, and Janoah, and Kedesh, and Hazor, and Gilead, and Galilee, all the land of Naphtali; and he carried them captive to Assyria.'),
  ('d723a247-255d-5f32-a25f-27164e076975', '79ec464a-853f-533e-a10e-8039f9c04a83', NULL, 30, 30, 'Hoshea the son of Elah made a conspiracy against Pekah the son of Remaliah, and struck him, and killed him, and reigned in his place, in the twentieth year of Jotham the son of Uzziah.'),
  ('566c23bd-750a-5b67-afd8-0c69705635cb', '79ec464a-853f-533e-a10e-8039f9c04a83', NULL, 31, 31, 'Now the rest of the acts of Pekah, and all that he did, behold, they are written in the book of the chronicles of the kings of Israel.'),
  ('29533e55-cb0a-52a8-a5d1-fa357137fc21', '79ec464a-853f-533e-a10e-8039f9c04a83', NULL, 32, 32, 'In the second year of Pekah the son of Remaliah king of Israel began Jotham the son of Uzziah king of Judah to reign.'),
  ('52f7f538-4ad5-5aa1-aaf3-a88e7482387f', '79ec464a-853f-533e-a10e-8039f9c04a83', NULL, 33, 33, 'He was twenty-five years old when he began to reign; and he reigned sixteen years in Jerusalem: and his mother''s name was Jerusha the daughter of Zadok.'),
  ('700b5a60-a9b6-50bb-aa7e-c8424d7b29f8', '79ec464a-853f-533e-a10e-8039f9c04a83', NULL, 34, 34, 'He did that which was right in the eyes of Yahweh; he did according to all that his father Uzziah had done.'),
  ('5ecba744-421a-56b2-aca4-f0b23e4178a9', '79ec464a-853f-533e-a10e-8039f9c04a83', NULL, 35, 35, 'However the high places were not taken away: the people still sacrificed and burned incense in the high places. He built the upper gate of the house of Yahweh.'),
  ('39036d6e-51f5-5462-a5c8-bc62d5966597', '79ec464a-853f-533e-a10e-8039f9c04a83', NULL, 36, 36, 'Now the rest of the acts of Jotham, and all that he did, aren''t they written in the book of the chronicles of the kings of Judah?'),
  ('d993a83a-3b84-597f-a9c7-388db4e4d81b', '79ec464a-853f-533e-a10e-8039f9c04a83', NULL, 37, 37, 'In those days Yahweh began to send against Judah Rezin the king of Syria, and Pekah the son of Remaliah.'),
  ('50104aad-03c1-58fc-a7ad-9780f443b45f', '79ec464a-853f-533e-a10e-8039f9c04a83', NULL, 38, 38, 'Jotham slept with his fathers, and was buried with his fathers in the city of David his father: and Ahaz his son reigned in his place.'),
  ('052f71cd-0e77-5164-aaa8-ed1f38106d45', 'dab74b3f-c6f3-5d5d-a880-32a4c139e7f7', NULL, 1, 1, 'In the seventeenth year of Pekah the son of Remaliah Ahaz the son of Jotham king of Judah began to reign.'),
  ('ce83c2ec-64d2-51e9-a0e9-398d57b65dd1', 'dab74b3f-c6f3-5d5d-a880-32a4c139e7f7', NULL, 2, 2, 'Twenty years old was Ahaz when he began to reign; and he reigned sixteen years in Jerusalem: and he didn''t do that which was right in the eyes of Yahweh his God, like David his father.'),
  ('06035462-35ac-5bd3-ad9e-33e046bda6e9', 'dab74b3f-c6f3-5d5d-a880-32a4c139e7f7', NULL, 3, 3, 'But he walked in the way of the kings of Israel, yes, and made his son to pass through the fire, according to the abominations of the nations, whom Yahweh cast out from before the children of Israel.'),
  ('6afe2ea9-e5d8-5158-a724-3751fd11443f', 'dab74b3f-c6f3-5d5d-a880-32a4c139e7f7', NULL, 4, 4, 'He sacrificed and burnt incense in the high places, and on the hills, and under every green tree.'),
  ('bd059987-e48a-5222-ac15-81ceada2fbdb', 'dab74b3f-c6f3-5d5d-a880-32a4c139e7f7', NULL, 5, 5, 'Then Rezin king of Syria and Pekah son of Remaliah king of Israel came up to Jerusalem to war: and they besieged Ahaz, but could not overcome him.'),
  ('b82dd01f-8c99-5794-acc7-0647b2e35f56', 'dab74b3f-c6f3-5d5d-a880-32a4c139e7f7', NULL, 6, 6, 'At that time Rezin king of Syria recovered Elath to Syria, and drove the Jews from Elath; and the Syrians came to Elath, and lived there, to this day.'),
  ('91beae66-fe97-580d-a3f0-0c8c866340a7', 'dab74b3f-c6f3-5d5d-a880-32a4c139e7f7', NULL, 7, 7, 'So Ahaz sent messengers to Tiglath Pileser king of Assyria, saying, "I am your servant and your son. Come up, and save me out of the hand of the king of Syria, and out of the hand of the king of Israel, who rise up against me."'),
  ('7fe3afd6-0e39-5336-ab2b-931deb419bf5', 'dab74b3f-c6f3-5d5d-a880-32a4c139e7f7', NULL, 8, 8, 'Ahaz took the silver and gold that was found in the house of Yahweh, and in the treasures of the king''s house, and sent it for a present to the king of Assyria.'),
  ('b7aec605-781a-5cc5-acac-c6de8b5cb3ff', 'dab74b3f-c6f3-5d5d-a880-32a4c139e7f7', NULL, 9, 9, 'The king of Assyria listened to him; and the king of Assyria went up against Damascus, and took it, and carried [the people of] it captive to Kir, and killed Rezin.'),
  ('9370ad39-9b9d-58e0-aee8-a833bb4254bf', 'dab74b3f-c6f3-5d5d-a880-32a4c139e7f7', NULL, 10, 10, 'King Ahaz went to Damascus to meet Tiglath Pileser king of Assyria, and saw the altar that was at Damascus; and king Ahaz sent to Urijah the priest the fashion of the altar, and its pattern, according to all its workmanship.'),
  ('c23e8f28-37cc-5520-a2f7-28dc2f82156b', 'dab74b3f-c6f3-5d5d-a880-32a4c139e7f7', NULL, 11, 11, 'Urijah the priest built an altar: according to all that king Ahaz had sent from Damascus, so did Urijah the priest make it against the coming of king Ahaz from Damascus.'),
  ('7eecb3c1-675f-53dc-a303-d1611086a415', 'dab74b3f-c6f3-5d5d-a880-32a4c139e7f7', NULL, 12, 12, 'When the king was come from Damascus, the king saw the altar: and the king drew near to the altar, and offered thereon.'),
  ('87f5dc92-d126-514f-a227-f702802f39a5', 'dab74b3f-c6f3-5d5d-a880-32a4c139e7f7', NULL, 13, 13, 'He burnt his burnt offering and his meal offering, and poured his drink offering, and sprinkled the blood of his peace offerings, on the altar.'),
  ('267c7641-fcf1-5592-ad2f-c0bccd8f9167', 'dab74b3f-c6f3-5d5d-a880-32a4c139e7f7', NULL, 14, 14, 'The bronze altar, which was before Yahweh, he brought from the forefront of the house, from between his altar and the house of Yahweh, and put it on the north side of his altar.'),
  ('4759bd84-f6ce-5d91-ad47-ad5e4ed2bf55', 'dab74b3f-c6f3-5d5d-a880-32a4c139e7f7', NULL, 15, 15, 'King Ahaz commanded Urijah the priest, saying, "On the great altar burn the morning burnt offering, and the evening meal offering, and the king''s burnt offering, and his meal offering, with the burnt offering of all the people of the land, and their meal offering, and their drink offerings; and sprinkle on it all the blood of the burnt offering, and all the blood of the sacrifice; but the bronze altar shall be for me to inquire by."'),
  ('073eada2-5a5e-5fef-a780-246585f28197', 'dab74b3f-c6f3-5d5d-a880-32a4c139e7f7', NULL, 16, 16, 'Urijah the priest did so, according to all that king Ahaz commanded.'),
  ('e27c41a4-8da3-5794-a8d4-e767baf33d15', 'dab74b3f-c6f3-5d5d-a880-32a4c139e7f7', NULL, 17, 17, 'King Ahaz cut off the panels of the bases, and removed the basin from off them, and took down the sea from off the bronze oxen that were under it, and put it on a pavement of stone.'),
  ('9cd6fda4-1cc8-515f-a620-9e36f066eac5', 'dab74b3f-c6f3-5d5d-a880-32a4c139e7f7', NULL, 18, 18, 'The covered way for the Sabbath that they had built in the house, and the king''s entry outside, turned he to the house of Yahweh, because of the king of Assyria.'),
  ('6ae94352-8773-51ce-a47e-afe4f3278ba7', 'dab74b3f-c6f3-5d5d-a880-32a4c139e7f7', NULL, 19, 19, 'Now the rest of the acts of Ahaz which he did, aren''t they written in the book of the chronicles of the kings of Judah?'),
  ('cc73b190-81f7-57f9-af2f-16366f2200a3', 'dab74b3f-c6f3-5d5d-a880-32a4c139e7f7', NULL, 20, 20, 'Ahaz slept with his fathers, and was buried with his fathers in the city of David: and Hezekiah his son reigned in his place.'),
  ('7a929a68-0a78-502e-ae98-4dd1f05532f3', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 1, 1, 'In the twelfth year of Ahaz king of Judah began Hoshea the son of Elah to reign in Samaria over Israel, [and reigned] nine years.'),
  ('be0b80a7-6adf-5765-ac3f-f4ea1f3b1f20', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 2, 2, 'He did that which was evil in the sight of Yahweh, yet not as the kings of Israel who were before him.'),
  ('d6a2771e-24d6-592b-afa1-744e64c1d55b', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 3, 3, 'Against him came up Shalmaneser king of Assyria; and Hoshea became his servant, and brought him tribute.'),
  ('1aa7caab-ddd3-53e1-a3f3-0e677b6a1472', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 4, 4, 'The king of Assyria found conspiracy in Hoshea; for he had sent messengers to So king of Egypt, and offered no tribute to the king of Assyria, as he had done year by year: therefore the king of Assyria shut him up, and bound him in prison.'),
  ('e9aa126f-1c83-53e4-abf3-2d50090d980b', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 5, 5, 'Then the king of Assyria came up throughout all the land, and went up to Samaria, and besieged it three years.'),
  ('228e3a20-0fe4-5cf3-afe7-e92aa02cf9db', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 6, 6, 'In the ninth year of Hoshea the king of Assyria took Samaria, and carried Israel away to Assyria, and placed them in Halah, and on the Habor, the river of Gozan, and in the cities of the Medes.'),
  ('37164d0b-71a2-5320-aa43-b16bc363b583', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 7, 7, 'It was so, because the children of Israel had sinned against Yahweh their God, who brought them up out of the land of Egypt from under the hand of Pharaoh king of Egypt, and had feared other gods,'),
  ('9e62b645-0480-505f-a160-55a6195d1917', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 8, 8, 'and walked in the statutes of the nations, whom Yahweh cast out from before the children of Israel, and of the kings of Israel, which they made.'),
  ('5bc895e0-bbe1-5f32-ac81-9423b33e62de', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 9, 9, 'The children of Israel did secretly things that were not right against Yahweh their God: and they built them high places in all their cities, from the tower of the watchmen to the fortified city;'),
  ('f96b749a-9747-5182-a6b8-d0384c364483', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 10, 10, 'and they set them up pillars and Asherim on every high hill, and under every green tree;'),
  ('a143dffe-565e-56de-aefd-9dc0b963b020', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 11, 11, 'and there they burnt incense in all the high places, as did the nations whom Yahweh carried away before them; and they worked wicked things to provoke Yahweh to anger;'),
  ('1959ad7e-c34e-5889-a73a-d3231143f91c', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 12, 12, 'and they served idols, of which Yahweh had said to them, "You shall not do this thing."'),
  ('3fe797f0-eeb0-529b-aae3-44709ca9fae7', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 13, 13, 'Yet Yahweh testified to Israel, and to Judah, by every prophet, and every seer, saying, "Turn from your evil ways, and keep my commandments and my statutes, according to all the law which I commanded your fathers, and which I sent to you by my servants the prophets."'),
  ('c178f5c3-3a6b-5499-ab33-18ecfa9ed0c8', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 14, 14, 'Notwithstanding, they would not listen, but hardened their neck, like the neck of their fathers, who didn''t believe in Yahweh their God.'),
  ('7e0d6b8a-fd80-5460-a160-c008c0e7be74', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 15, 15, 'They rejected his statutes, and his covenant that he made with their fathers, and his testimonies which he testified to them; and they followed vanity, and became vain, and [went] after the nations that were around them, concerning whom Yahweh had commanded them that they should not do like them.'),
  ('f675f402-f432-59ce-aa20-cd378f48cd7d', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 16, 16, 'They forsook all the commandments of Yahweh their God, and made them molten images, even two calves, and made an Asherah, and worshiped all the army of the sky, and served Baal.'),
  ('ac07a1f0-a838-54c5-a56f-1cb879f5567d', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 17, 17, 'They caused their sons and their daughters to pass through the fire, and used divination and enchantments, and sold themselves to do that which was evil in the sight of Yahweh, to provoke him to anger.'),
  ('b3bc566b-37f3-5c6d-a812-e51722efad90', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 18, 18, 'Therefore Yahweh was very angry with Israel, and removed them out of his sight: there was none left but the tribe of Judah only.'),
  ('bae24aca-e4d1-59aa-a978-41d79c3a8573', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 19, 19, 'Also Judah didn''t keep the commandments of Yahweh their God, but walked in the statutes of Israel which they made.'),
  ('3cf4855e-c495-5043-a82e-0b764b274410', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 20, 20, 'Yahweh rejected all the seed of Israel, and afflicted them, and delivered them into the hand of spoilers, until he had cast them out of his sight.'),
  ('9e9ffa2b-5632-5565-a21b-516e2cbe31e9', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 21, 21, 'For he tore Israel from the house of David; and they made Jeroboam the son of Nebat king: and Jeroboam drove Israel from following Yahweh, and made them sin a great sin.'),
  ('63d07824-9b75-5ea0-aa3f-05b6802caddd', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 22, 22, 'The children of Israel walked in all the sins of Jeroboam which he did; they didn''t depart from them;'),
  ('1268a364-d64e-5a97-a2ae-6f5ac1903ecd', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 23, 23, 'until Yahweh removed Israel out of his sight, as he spoke by all his servants the prophets. So Israel was carried away out of their own land to Assyria to this day.'),
  ('be84bce7-0224-52ca-a4bf-33c7f2a4177d', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 24, 24, 'The king of Assyria brought men from Babylon, and from Cuthah, and from Avva, and from Hamath and Sepharvaim, and placed them in the cities of Samaria instead of the children of Israel; and they possessed Samaria, and lived in the cities of it.'),
  ('c20d934e-7e30-58be-aad7-8f869ae202e7', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 25, 25, 'So it was, at the beginning of their dwelling there, that they didn''t fear Yahweh: therefore Yahweh sent lions among them, which killed some of them.'),
  ('2e7e809a-d207-5844-a2e6-dc229f7ba44a', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 26, 26, 'Therefore they spoke to the king of Assyria, saying, "The nations which you have carried away, and placed in the cities of Samaria, don''t know the law of the god of the land. Therefore he has sent lions among them, and behold, they kill them, because they don''t know the law of the god of the land."'),
  ('9cbe8f75-0acb-51ef-a8a8-9a55d3d8c13b', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 27, 27, 'Then the king of Assyria commanded, saying, "Carry there one of the priests whom you brought from there; and let them go and dwell there, and let him teach them the law of the god of the land."'),
  ('8c20e117-c0c5-541b-ac4c-25bf1dda3be6', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 28, 28, 'So one of the priests whom they had carried away from Samaria came and lived in Bethel, and taught them how they should fear Yahweh.'),
  ('65edd109-5a16-57f4-aa5a-eaceb9bb8856', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 29, 29, 'However every nation made gods of their own, and put them in the houses of the high places which the Samaritans had made, every nation in their cities in which they lived.'),
  ('f5108551-56cc-5e42-aeca-4b6f186fdf81', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 30, 30, 'The men of Babylon made Succoth Benoth, and the men of Cuth made Nergal, and the men of Hamath made Ashima,'),
  ('b520e255-9a80-5b8d-ab41-6ae3bb47a6f0', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 31, 31, 'and the Avvites made Nibhaz and Tartak; and the Sepharvites burnt their children in the fire to Adrammelech and Anammelech, the gods of Sepharvaim.'),
  ('b35fd164-ef2b-5bed-aadd-7a07ef6c91e7', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 32, 32, 'So they feared Yahweh, and made to them from among themselves priests of the high places, who sacrificed for them in the houses of the high places.'),
  ('2f2e1a94-6850-50dd-a1d9-c54dc069ea2f', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 33, 33, 'They feared Yahweh, and served their own gods, after the ways of the nations from among whom they had been carried away.'),
  ('a24bb710-1f0e-5fd4-a160-6f175653deed', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 34, 34, 'To this day they do what they did before: they don''t fear Yahweh, neither do they follow their statutes, or their ordinances, or the law or the commandment which Yahweh commanded the children of Jacob, whom he named Israel;'),
  ('db73a82e-627d-56c1-ae87-0c64b3c927a5', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 35, 35, 'with whom Yahweh had made a covenant, and commanded them, saying, "You shall not fear other gods, nor bow yourselves to them, nor serve them, nor sacrifice to them;'),
  ('ce84e9f1-3fd3-5b4f-a24c-4c1f747bb044', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 36, 36, 'but you shall fear Yahweh, who brought you up out of the land of Egypt with great power and with an outstretched arm, and you shall bow yourselves to him, and you shall sacrifice to him.'),
  ('602423ad-9d5d-5dad-a120-30b32272f0bc', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 37, 37, 'The statutes and the ordinances, and the law and the commandment, which he wrote for you, you shall observe to do forevermore. You shall not fear other gods.'),
  ('e2f3fdc1-a474-5e41-a40f-c099a26eb2c6', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 38, 38, 'You shall not forget the covenant that I have made with you; neither shall you fear other gods.'),
  ('61c9508c-6f7f-549b-a378-1ef04711157d', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 39, 39, 'But you shall fear Yahweh your God; and he will deliver you out of the hand of all your enemies."'),
  ('e82dc602-e645-5623-a38a-6efc5f39470e', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 40, 40, 'However they did not listen, but they did what they did before.'),
  ('75cfee45-dbfc-55f8-aaf8-568a2a55648f', '4846d625-fd95-546a-ab4a-d54d1bb6fcf1', NULL, 41, 41, 'So these nations feared Yahweh, and served their engraved images. Their children likewise, and their children''s children, as their fathers did, so they do to this day.'),
  ('45980ea8-6347-54fe-a310-d2efdae21da1', '74d5b7d4-1e31-5699-a218-05907e39c8ea', NULL, 1, 1, 'Now it happened in the third year of Hoshea son of Elah king of Israel, that Hezekiah the son of Ahaz king of Judah began to reign.'),
  ('7d368075-9701-5fb6-aca5-c5cdc1ff9e4e', '74d5b7d4-1e31-5699-a218-05907e39c8ea', NULL, 2, 2, 'He was twenty-five years old when he began to reign; and he reigned twenty-nine years in Jerusalem: and his mother''s name was Abi the daughter of Zechariah.'),
  ('fabbe51d-ecef-5122-a80d-dd1442186065', '74d5b7d4-1e31-5699-a218-05907e39c8ea', NULL, 3, 3, 'He did that which was right in the eyes of Yahweh, according to all that David his father had done.'),
  ('f76842ea-41a7-5138-ada1-cf2ff2d3fe10', '74d5b7d4-1e31-5699-a218-05907e39c8ea', NULL, 4, 4, 'He removed the high places, and broke the pillars, and cut down the Asherah: and he broke in pieces the bronze serpent that Moses had made; for to those days the children of Israel did burn incense to it; and he called it Nehushtan.'),
  ('95fa7f17-ee4e-538f-a20b-3928376d94ea', '74d5b7d4-1e31-5699-a218-05907e39c8ea', NULL, 5, 5, 'He trusted in Yahweh, the God of Israel; so that after him was none like him among all the kings of Judah, nor [among them] that were before him.'),
  ('0ac05824-72ae-58c9-a551-dc6e09b66f87', '74d5b7d4-1e31-5699-a218-05907e39c8ea', NULL, 6, 6, 'For he joined with Yahweh; he didn''t depart from following him, but kept his commandments, which Yahweh commanded Moses.'),
  ('fb9120be-8b98-54d5-a677-1021323aafad', '74d5b7d4-1e31-5699-a218-05907e39c8ea', NULL, 7, 7, 'Yahweh was with him; wherever he went forth he prospered: and he rebelled against the king of Assyria, and didn''t serve him.'),
  ('98dfccdf-9cfe-57d8-a87e-c91d05d1f262', '74d5b7d4-1e31-5699-a218-05907e39c8ea', NULL, 8, 8, 'He struck the Philistines to Gaza and its borders, from the tower of the watchmen to the fortified city.'),
  ('a09c5a5c-2342-5ff0-a41c-a5fd1af90fbc', '74d5b7d4-1e31-5699-a218-05907e39c8ea', NULL, 9, 9, 'It happened in the fourth year of king Hezekiah, which was the seventh year of Hoshea son of Elah king of Israel, that Shalmaneser king of Assyria came up against Samaria, and besieged it.'),
  ('a3782280-383d-502c-afd9-8d2463c13e21', '74d5b7d4-1e31-5699-a218-05907e39c8ea', NULL, 10, 10, 'At the end of three years they took it: in the sixth year of Hezekiah, which was the ninth year of Hoshea king of Israel, Samaria was taken.'),
  ('343dc46f-cc06-55d9-a821-d961a7beb380', '74d5b7d4-1e31-5699-a218-05907e39c8ea', NULL, 11, 11, 'The king of Assyria carried Israel away to Assyria, and put them in Halah, and on the Habor, the river of Gozan, and in the cities of the Medes,'),
  ('df06ff85-ce3c-5b7e-aa70-833b2e7dd906', '74d5b7d4-1e31-5699-a218-05907e39c8ea', NULL, 12, 12, 'because they didn''t obey the voice of Yahweh their God, but transgressed his covenant, even all that Moses the servant of Yahweh commanded, and would not hear it, nor do it.'),
  ('6aecc680-abe1-592d-a23e-82ac0d7164b7', '74d5b7d4-1e31-5699-a218-05907e39c8ea', NULL, 13, 13, 'Now in the fourteenth year of king Hezekiah did Sennacherib king of Assyria come up against all the fortified cities of Judah, and took them.'),
  ('ca21a326-2540-55ae-a7d0-ea1713cbb946', '74d5b7d4-1e31-5699-a218-05907e39c8ea', NULL, 14, 14, 'Hezekiah king of Judah sent to the king of Assyria to Lachish, saying, "I have offended; return from me. That which you put on me, I will bear." The king of Assyria appointed to Hezekiah king of Judah three hundred talents of silver and thirty talents of gold.'),
  ('3aaee428-189d-53f2-a7c6-ee74305b43ff', '74d5b7d4-1e31-5699-a218-05907e39c8ea', NULL, 15, 15, 'Hezekiah gave [him] all the silver that was found in the house of Yahweh, and in the treasures of the king''s house.'),
  ('c8bb8aff-ba84-5a13-a99d-5f1a2e55d895', '74d5b7d4-1e31-5699-a218-05907e39c8ea', NULL, 16, 16, 'At that time did Hezekiah cut off [the gold from] the doors of the temple of Yahweh, and [from] the pillars which Hezekiah king of Judah had overlaid, and gave it to the king of Assyria.'),
  ('708b3633-847a-502a-a17a-08c5d1bf26ac', '74d5b7d4-1e31-5699-a218-05907e39c8ea', NULL, 17, 17, 'The king of Assyria sent Tartan and Rabsaris and Rabshakeh from Lachish to king Hezekiah with a great army to Jerusalem. They went up and came to Jerusalem. When they were come up, they came and stood by the conduit of the upper pool, which is in the highway of the fuller''s field.'),
  ('c7da158e-1293-5ea5-a97b-6ff88698233d', '74d5b7d4-1e31-5699-a218-05907e39c8ea', NULL, 18, 18, 'When they had called to the king, there came out to them Eliakim the son of Hilkiah, who was over the household, and Shebnah the scribe, and Joah the son of Asaph the recorder.'),
  ('45708e9e-a240-5100-a190-abcc525c88ed', '74d5b7d4-1e31-5699-a218-05907e39c8ea', NULL, 19, 19, 'Rabshakeh said to them, "Say now to Hezekiah, ''Thus says the great king, the king of Assyria, "What confidence is this in which you trust?'),
  ('4de8b781-8c15-5d5f-ad24-f02f697764a1', '74d5b7d4-1e31-5699-a218-05907e39c8ea', NULL, 20, 20, 'You say (but they are but vain words), ''There is counsel and strength for war.'' Now on whom do you trust, that you have rebelled against me?'),
  ('b1ce89a4-2f1d-5a66-a157-665655be8089', '74d5b7d4-1e31-5699-a218-05907e39c8ea', NULL, 21, 21, 'Now, behold, you trust in the staff of this bruised reed, even in Egypt. If a man leans on it, it will go into his hand, and pierce it. So is Pharaoh king of Egypt to all who trust on him.'),
  ('0cbb8c8b-4fa8-51be-ae7f-8f27bcf16bb6', '74d5b7d4-1e31-5699-a218-05907e39c8ea', NULL, 22, 22, 'But if you tell me, ''We trust in Yahweh our God;'' isn''t that he whose high places and whose altars Hezekiah has taken away, and has said to Judah and to Jerusalem, ''You shall worship before this altar in Jerusalem?'''),
  ('7caf5f0b-c771-5d5e-a05e-e16c7c8841c9', '74d5b7d4-1e31-5699-a218-05907e39c8ea', NULL, 23, 23, 'Now therefore, please give pledges to my master the king of Assyria, and I will give you two thousand horses, if you are able on your part to set riders on them.'),
  ('c895d3fa-5952-5231-a326-754662dc2ece', '74d5b7d4-1e31-5699-a218-05907e39c8ea', NULL, 24, 24, 'How then can you turn away the face of one captain of the least of my master''s servants, and put your trust on Egypt for chariots and for horsemen?'),
  ('16255d3e-4c31-5a7d-a75c-c81e46840a4f', '74d5b7d4-1e31-5699-a218-05907e39c8ea', NULL, 25, 25, 'Have I now come up without Yahweh against this place to destroy it? Yahweh said to me, ''Go up against this land, and destroy it.''"''"'),
  ('9c1dd669-083f-5e2f-ad3b-a2495692c49c', '74d5b7d4-1e31-5699-a218-05907e39c8ea', NULL, 26, 26, 'Then Eliakim the son of Hilkiah, and Shebnah, and Joah, said to Rabshakeh, "Please speak to your servants in the Syrian language; for we understand it. Don''t speak with us in the Jews'' language, in the hearing of the people who are on the wall."'),
  ('96782949-9fa3-5fb9-af34-422afe39df44', '74d5b7d4-1e31-5699-a218-05907e39c8ea', NULL, 27, 27, 'But Rabshakeh said to them, "Has my master sent me to your master, and to you, to speak these words? Hasn''t he sent me to the men who sit on the wall, to eat their own dung, and to drink their own water with you?"'),
  ('b4120b53-a8f6-53cd-aa33-1d94e288f75e', '74d5b7d4-1e31-5699-a218-05907e39c8ea', NULL, 28, 28, 'Then Rabshakeh stood, and cried with a loud voice in the Jews'' language, and spoke, saying, "Hear the word of the great king, the king of Assyria.'),
  ('bc7e165a-3413-5c33-a27c-79a62c8a86b9', '74d5b7d4-1e31-5699-a218-05907e39c8ea', NULL, 29, 29, 'Thus says the king, ''Don''t let Hezekiah deceive you; for he will not be able to deliver you out of his hand.'),
  ('5503165f-bcaf-530e-a7b7-0368dc74ad6f', '74d5b7d4-1e31-5699-a218-05907e39c8ea', NULL, 30, 30, 'Neither let Hezekiah make you trust in Yahweh, saying, "Yahweh will surely deliver us, and this city shall not be given into the hand of the king of Assyria."'),
  ('f639bc0a-c664-5a00-a1a9-4e1a6ab9b7e9', '74d5b7d4-1e31-5699-a218-05907e39c8ea', NULL, 31, 31, 'Don''t listen to Hezekiah.'' For thus says the king of Assyria, ''Make your peace with me, and come out to me; and everyone of you eat of his vine, and everyone of his fig tree, and everyone drink the waters of his own cistern;'),
  ('8bffadd4-5e44-59dd-a162-b44898ee1647', '74d5b7d4-1e31-5699-a218-05907e39c8ea', NULL, 32, 32, 'until I come and take you away to a land like your own land, a land of grain and new wine, a land of bread and vineyards, a land of olive trees and of honey, that you may live, and not die. Don''t listen to Hezekiah, when he persuades you, saying, "Yahweh will deliver us."'),
  ('bab5e027-40b1-54f8-a10a-785cc152dbe4', '74d5b7d4-1e31-5699-a218-05907e39c8ea', NULL, 33, 33, 'Has any of the gods of the nations ever delivered his land out of the hand of the king of Assyria?'),
  ('11005fa1-1765-5177-ad6a-ca884efa7337', '74d5b7d4-1e31-5699-a218-05907e39c8ea', NULL, 34, 34, 'Where are the gods of Hamath, and of Arpad? Where are the gods of Sepharvaim, of Hena, and Ivvah? Have they delivered Samaria out of my hand?'),
  ('5b56cc98-0557-5ef4-abe2-a9df7435defd', '74d5b7d4-1e31-5699-a218-05907e39c8ea', NULL, 35, 35, 'Who are they among all the gods of the countries, that have delivered their country out of my hand, that Yahweh should deliver Jerusalem out of my hand?''"'),
  ('a1dcf49c-5978-5965-aa68-6843d5338a18', '74d5b7d4-1e31-5699-a218-05907e39c8ea', NULL, 36, 36, 'But the people held their peace, and answered him not a word; for the king''s commandment was, "Don''t answer him."'),
  ('64dd3863-bd89-53ff-a80c-23e10a38bf6a', '74d5b7d4-1e31-5699-a218-05907e39c8ea', NULL, 37, 37, 'Then Eliakim the son of Hilkiah, who was over the household, came with Shebna the scribe, and Joah the son of Asaph the recorder, to Hezekiah with their clothes torn, and told him the words of Rabshakeh.'),
  ('d04cec64-cb85-5a48-a4c8-6c63b9ab63df', 'bd0f0a2c-cf6e-5a6c-aa3f-8a5df5d19258', NULL, 1, 1, 'It happened, when king Hezekiah heard it, that he tore his clothes, and covered himself with sackcloth, and went into the house of Yahweh.'),
  ('89c2f738-e0ea-519d-ad60-da1f22850b71', 'bd0f0a2c-cf6e-5a6c-aa3f-8a5df5d19258', NULL, 2, 2, 'He sent Eliakim, who was over the household, and Shebna the scribe, and the elders of the priests, covered with sackcloth, to Isaiah the prophet the son of Amoz.'),
  ('d0fa27c8-0ad1-58dd-a562-0a81a258dce1', 'bd0f0a2c-cf6e-5a6c-aa3f-8a5df5d19258', NULL, 3, 3, 'They said to him, "Thus says Hezekiah, ''This day is a day of trouble, of rebuke, and of rejection; for the children have come to the point of birth, and there is no strength to deliver them.'),
  ('258349ec-0c4d-5e44-a05c-09444398d94c', 'bd0f0a2c-cf6e-5a6c-aa3f-8a5df5d19258', NULL, 4, 4, 'It may be Yahweh your God will hear all the words of Rabshakeh, whom the king of Assyria his master has sent to defy the living God, and will rebuke the words which Yahweh your God has heard. Therefore lift up your prayer for the remnant that is left.''"'),
  ('06323551-b549-5b60-a7fc-39e99235b1a5', 'bd0f0a2c-cf6e-5a6c-aa3f-8a5df5d19258', NULL, 5, 5, 'So the servants of king Hezekiah came to Isaiah.'),
  ('0ca4ec4c-7526-530e-ada7-51163ce131ad', 'bd0f0a2c-cf6e-5a6c-aa3f-8a5df5d19258', NULL, 6, 6, 'Isaiah said to them, "Thus you shall tell your master, ''Thus says Yahweh, "Don''t be afraid of the words that you have heard, with which the servants of the king of Assyria have blasphemed me.'),
  ('3895e83e-e694-52f1-a8c2-f117adab9e39', 'bd0f0a2c-cf6e-5a6c-aa3f-8a5df5d19258', NULL, 7, 7, 'Behold, I will put a spirit in him, and he will hear news, and will return to his own land. I will cause him to fall by the sword in his own land."''"'),
  ('bd875ca3-7b3e-5a01-ad10-7647a0e2e5f8', 'bd0f0a2c-cf6e-5a6c-aa3f-8a5df5d19258', NULL, 8, 8, 'So Rabshakeh returned, and found the king of Assyria warring against Libnah; for he had heard that he had departed from Lachish.'),
  ('92611948-ba82-5932-a3c9-4eba162062e9', 'bd0f0a2c-cf6e-5a6c-aa3f-8a5df5d19258', NULL, 9, 9, 'When he heard it said of Tirhakah king of Ethiopia, "Behold, he has come out to fight against you, he sent messengers again to Hezekiah, saying,'),
  ('1883f9c1-00fc-573d-a34c-3a9d31d98957', 'bd0f0a2c-cf6e-5a6c-aa3f-8a5df5d19258', NULL, 10, 10, '''Thus you shall speak to Hezekiah king of Judah, saying, "Don''t let your God in whom you trust deceive you, saying, Jerusalem will not be given into the hand of the king of Assyria.'),
  ('2a412b3a-7821-5631-acc2-4bae3eafe1bb', 'bd0f0a2c-cf6e-5a6c-aa3f-8a5df5d19258', NULL, 11, 11, 'Behold, you have heard what the kings of Assyria have done to all lands, by destroying them utterly. Will you be delivered?'),
  ('62f09e04-a5f1-59f9-a276-0843a3a649ea', 'bd0f0a2c-cf6e-5a6c-aa3f-8a5df5d19258', NULL, 12, 12, 'Have the gods of the nations delivered them, which my fathers have destroyed, Gozan, and Haran, and Rezeph, and the children of Eden that were in Telassar?'),
  ('77ddb89a-8d9a-5fb3-a8f4-9b19e48073bc', 'bd0f0a2c-cf6e-5a6c-aa3f-8a5df5d19258', NULL, 13, 13, 'Where is the king of Hamath, and the king of Arpad, and the king of the city of Sepharvaim, of Hena, and Ivvah?"''"'),
  ('fa468783-1081-54dd-a40a-03374c937d50', 'bd0f0a2c-cf6e-5a6c-aa3f-8a5df5d19258', NULL, 14, 14, 'Hezekiah received the letter from the hand of the messengers, and read it. Then Hezekiah went up to the house of Yahweh, and spread it before Yahweh.'),
  ('accbca98-a09b-50fb-abb7-6b90d2bb048d', 'bd0f0a2c-cf6e-5a6c-aa3f-8a5df5d19258', NULL, 15, 15, 'Hezekiah prayed before Yahweh, and said, "Yahweh, the God of Israel, who sit [above] the cherubim, you are the God, even you alone, of all the kingdoms of the earth. You have made heaven and earth.'),
  ('bffc0f54-3f36-5335-a15f-034adc255b49', 'bd0f0a2c-cf6e-5a6c-aa3f-8a5df5d19258', NULL, 16, 16, 'Incline your ear, Yahweh, and hear. Open your eyes, Yahweh, and see. Hear the words of Sennacherib, with which he has sent to defy the living God.'),
  ('bd65f6e9-c061-5e18-aaa3-1eb20330d8c3', 'bd0f0a2c-cf6e-5a6c-aa3f-8a5df5d19258', NULL, 17, 17, 'Truly, Yahweh, the kings of Assyria have laid waste the nations and their lands,'),
  ('c8a4f3cb-ab2b-5825-ad85-a3c8dbd16cad', 'bd0f0a2c-cf6e-5a6c-aa3f-8a5df5d19258', NULL, 18, 18, 'and have cast their gods into the fire; for they were no gods, but the work of men''s hands, wood and stone. Therefore they have destroyed them.'),
  ('9a0948a6-e35f-5a87-a08e-f0cb804bab00', 'bd0f0a2c-cf6e-5a6c-aa3f-8a5df5d19258', NULL, 19, 19, 'Now therefore, Yahweh our God, save us, I beg you, out of his hand, that all the kingdoms of the earth may know that you, Yahweh, are God alone."'),
  ('22dd4be5-7e4f-5b30-a555-fdbbd4859899', 'bd0f0a2c-cf6e-5a6c-aa3f-8a5df5d19258', NULL, 20, 20, 'Then Isaiah the son of Amoz sent to Hezekiah, saying, "Thus says Yahweh, the God of Israel, ''Whereas you have prayed to me against Sennacherib king of Assyria, I have heard you.'),
  ('4a2daba9-cd14-51c1-ae5b-8bd6fc6b8ecc', 'bd0f0a2c-cf6e-5a6c-aa3f-8a5df5d19258', NULL, 21, 21, 'This is the word that Yahweh has spoken concerning him: "The virgin daughter of Zion has despised you and ridiculed you. The daughter of Jerusalem has shaken her head at you.'),
  ('ce540b9b-ce00-53db-a550-dd7a5111fd8a', 'bd0f0a2c-cf6e-5a6c-aa3f-8a5df5d19258', NULL, 22, 22, 'Whom have you defied and blasphemed? Against whom have you exalted your voice and lifted up your eyes on high? Against the Holy One of Israel.'),
  ('81ae0281-370d-55a8-a34e-928f08ca4249', 'bd0f0a2c-cf6e-5a6c-aa3f-8a5df5d19258', NULL, 23, 23, 'By your messengers you have defied the Lord, and have said, ''With the multitude of my chariots, I have come up to the height of the mountains, to the innermost parts of Lebanon; and I will cut down its tall cedars, and its choice fir trees; and I will enter into his farthest lodging place, the forest of his fruitful field.'),
  ('af0c456b-cfe6-5647-aba7-c5becc48afb5', 'bd0f0a2c-cf6e-5a6c-aa3f-8a5df5d19258', NULL, 24, 24, 'I have dug and drunk strange waters, and with the sole of my feet will I dry up all the rivers of Egypt.'''),
  ('979d4fda-237d-55f3-a7a9-81a0fa682a6a', 'bd0f0a2c-cf6e-5a6c-aa3f-8a5df5d19258', NULL, 25, 25, 'Haven''t you heard how I have done it long ago, and formed it of ancient times? Now have I brought it to pass, that it should be yours to lay waste fortified cities into ruinous heaps.'),
  ('16ddb864-45eb-5c03-a85d-661d5034bd6d', 'bd0f0a2c-cf6e-5a6c-aa3f-8a5df5d19258', NULL, 26, 26, 'Therefore their inhabitants were of small power. They were dismayed and confounded. They were like the grass of the field, and like the green herb, like the grass on the housetops, and like grain blasted before it has grown up.'),
  ('c2973b60-8fc4-537b-a317-0ce38a082f2f', 'bd0f0a2c-cf6e-5a6c-aa3f-8a5df5d19258', NULL, 27, 27, 'But I know your sitting down, and your going out, and your coming in, and your raging against me.'),
  ('6de98bab-a730-52e8-ab3e-7a85512eb10e', 'bd0f0a2c-cf6e-5a6c-aa3f-8a5df5d19258', NULL, 28, 28, 'Because of your raging against me, and because your arrogance has come up into my ears, therefore will I put my hook in your nose, and my bridle in your lips, and I will turn you back by the way by which you came."'),
  ('011ee86e-ab74-5fdd-aea7-cc01b819e199', 'bd0f0a2c-cf6e-5a6c-aa3f-8a5df5d19258', NULL, 29, 29, '"''This shall be the sign to you: You shall eat this year that which grows of itself, and in the second year that which springs of the same; and in the third year sow, and reap, and plant vineyards, and eat its fruit.'),
  ('8a3f5569-db9f-5d8f-af96-3428aeb135ed', 'bd0f0a2c-cf6e-5a6c-aa3f-8a5df5d19258', NULL, 30, 30, 'The remnant that has escaped of the house of Judah shall again take root downward, and bear fruit upward.'),
  ('e7d38c33-0822-5209-a9c3-46ef36abff66', 'bd0f0a2c-cf6e-5a6c-aa3f-8a5df5d19258', NULL, 31, 31, 'For out of Jerusalem a remnant will go out, and out of Mount Zion those who shall escape. The zeal of Yahweh will perform this.'''),
  ('44303fd3-9819-5e02-aec8-6cad429623b3', 'bd0f0a2c-cf6e-5a6c-aa3f-8a5df5d19258', NULL, 32, 32, '"Therefore thus says Yahweh concerning the king of Assyria, ''He shall not come to this city, nor shoot an arrow there, neither shall he come before it with shield, nor cast up a mound against it.'),
  ('d8e930b3-f31f-5290-abad-29e21c7235e3', 'bd0f0a2c-cf6e-5a6c-aa3f-8a5df5d19258', NULL, 33, 33, 'By the way that he came, by the same shall he return, and he shall not come to this city,'' says Yahweh.'),
  ('75b5de8d-d622-5266-a5f9-53b4e6a673e0', 'bd0f0a2c-cf6e-5a6c-aa3f-8a5df5d19258', NULL, 34, 34, '''For I will defend this city to save it, for my own sake, and for my servant David''s sake.''"'),
  ('dd00fd36-a814-53f8-adad-0bc8ae44e6d2', 'bd0f0a2c-cf6e-5a6c-aa3f-8a5df5d19258', NULL, 35, 35, 'It happened that night, that the angel of Yahweh went out, and struck one hundred eighty-five thousand in the camp of the Assyrians. When men arose early in the morning, behold, these were all dead bodies.'),
  ('35fdf59a-bd13-54ce-aaab-a84caba8d77d', 'bd0f0a2c-cf6e-5a6c-aa3f-8a5df5d19258', NULL, 36, 36, 'So Sennacherib king of Assyria departed, and went and returned, and lived at Nineveh.'),
  ('b0782211-74c5-5e4a-a72b-e757d863a309', 'bd0f0a2c-cf6e-5a6c-aa3f-8a5df5d19258', NULL, 37, 37, 'It happened, as he was worshipping in the house of Nisroch his god, that Adrammelech and Sharezer struck him with the sword; and they escaped into the land of Ararat. Esar Haddon his son reigned in his place.'),
  ('1b9bae8f-7b7c-5922-a03e-e884b3ef3f04', '37d780cb-5608-5582-ab57-dfac90503a3e', NULL, 1, 1, 'In those days was Hezekiah sick to death. Isaiah the prophet the son of Amoz came to him, and said to him, "Thus says Yahweh, ''Set your house in order; for you shall die, and not live.''"'),
  ('bb628810-8001-5b7e-aeba-066255ff8d28', '37d780cb-5608-5582-ab57-dfac90503a3e', NULL, 2, 2, 'Then he turned his face to the wall, and prayed to Yahweh, saying,'),
  ('8cce780f-2097-5f05-aa62-2a361749f316', '37d780cb-5608-5582-ab57-dfac90503a3e', NULL, 3, 3, '"Remember now, Yahweh, I beg you, how I have walked before you in truth and with a perfect heart, and have done that which is good in your sight." Hezekiah wept bitterly.'),
  ('8a7bdaf8-4e43-59da-a522-3de117ed9c01', '37d780cb-5608-5582-ab57-dfac90503a3e', NULL, 4, 4, 'It happened, before Isaiah had gone out into the middle part of the city, that the word of Yahweh came to him, saying,'),
  ('6405eda7-719e-52eb-a8a5-7c615a54d74f', '37d780cb-5608-5582-ab57-dfac90503a3e', NULL, 5, 5, '"Turn back, and tell Hezekiah the prince of my people, ''Thus says Yahweh, the God of David your father, "I have heard your prayer. I have seen your tears. Behold, I will heal you. On the third day, you shall go up to the house of Yahweh.'),
  ('95de4a41-30bf-5a8d-a1b0-006cf1acc4c8', '37d780cb-5608-5582-ab57-dfac90503a3e', NULL, 6, 6, 'I will add to your days fifteen years. I will deliver you and this city out of the hand of the king of Assyria. I will defend this city for my own sake, and for my servant David''s sake."''"'),
  ('2b9b37ad-fa36-53d2-ab8e-39841418e28b', '37d780cb-5608-5582-ab57-dfac90503a3e', NULL, 7, 7, 'Isaiah said, "Take a cake of figs." They took and laid it on the boil, and he recovered.'),
  ('e9e76b24-464b-5b60-a345-b0f3e7f33bbb', '37d780cb-5608-5582-ab57-dfac90503a3e', NULL, 8, 8, 'Hezekiah said to Isaiah, "What shall be the sign that Yahweh will heal me, and that I shall go up to the house of Yahweh the third day?"'),
  ('2ea673b2-a361-5ecd-aec4-2f30efdb4140', '37d780cb-5608-5582-ab57-dfac90503a3e', NULL, 9, 9, 'Isaiah said, "This shall be the sign to you from Yahweh, that Yahweh will do the thing that he has spoken: shall the shadow go forward ten steps, or go back ten steps?"'),
  ('9cef73c5-9394-5a03-a1f5-bb7ce2cac83e', '37d780cb-5608-5582-ab57-dfac90503a3e', NULL, 10, 10, 'Hezekiah answered, "It is a light thing for the shadow to go forward ten steps. Nay, but let the shadow return backward ten steps."'),
  ('ee83ccce-e075-5612-acda-a8040afb5c48', '37d780cb-5608-5582-ab57-dfac90503a3e', NULL, 11, 11, 'Isaiah the prophet cried to Yahweh; and he brought the shadow ten steps backward, by which it had gone down on the dial of Ahaz.'),
  ('a8f240b6-4f5d-5f47-a8c0-374d518669ec', '37d780cb-5608-5582-ab57-dfac90503a3e', NULL, 12, 12, 'At that time Berodach Baladan the son of Baladan, king of Babylon, sent letters and a present to Hezekiah; for he had heard that Hezekiah had been sick.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('296ffe40-ca76-5cc1-ab2e-60e95441f542', '37d780cb-5608-5582-ab57-dfac90503a3e', NULL, 13, 13, 'Hezekiah listened to them, and showed them all the house of his precious things, the silver, and the gold, and the spices, and the precious oil, and the house of his armor, and all that was found in his treasures: there was nothing in his house, nor in all his dominion, that Hezekiah didn''t show them.'),
  ('6a6270af-1bde-5efa-ac4d-7ad7e32c5315', '37d780cb-5608-5582-ab57-dfac90503a3e', NULL, 14, 14, 'Then Isaiah the prophet came to king Hezekiah, and said to him, "What did these men say? From where did they come to you?" Hezekiah said, "They are come from a far country, even from Babylon."'),
  ('2e9136ef-fe6f-52b9-a188-af4a3052127b', '37d780cb-5608-5582-ab57-dfac90503a3e', NULL, 15, 15, 'He said, "What have they seen in your house?" Hezekiah answered, "They have seen all that is in my house. There is nothing among my treasures that I have not shown them."'),
  ('6c9a1506-58b5-5359-a9e2-3e64bc316eb7', '37d780cb-5608-5582-ab57-dfac90503a3e', NULL, 16, 16, 'Isaiah said to Hezekiah, "Hear the word of Yahweh.'),
  ('525f577a-d77c-5247-a0c3-da6b2b419b02', '37d780cb-5608-5582-ab57-dfac90503a3e', NULL, 17, 17, '''Behold, the days come, that all that is in your house, and that which your fathers have laid up in store to this day, shall be carried to Babylon. Nothing shall be left,'' says Yahweh.'),
  ('9f952a39-b576-5d6a-a1c2-8d16a69cc539', '37d780cb-5608-5582-ab57-dfac90503a3e', NULL, 18, 18, '''Of your sons who shall issue from you, whom you shall father, shall they take away; and they shall be eunuchs in the palace of the king of Babylon.''"'),
  ('3ee61172-d479-506d-a275-7aa5e8e51514', '37d780cb-5608-5582-ab57-dfac90503a3e', NULL, 19, 19, 'Then Hezekiah said to Isaiah, "The word of Yahweh which you have spoken is good." He said moreover, "Isn''t it so, if peace and truth shall be in my days?"'),
  ('9026dbf1-e407-50d2-a1d0-402d7bd88a39', '37d780cb-5608-5582-ab57-dfac90503a3e', NULL, 20, 20, 'Now the rest of the acts of Hezekiah, and all his might, and how he made the pool, and the conduit, and brought water into the city, aren''t they written in the book of the chronicles of the kings of Judah?'),
  ('1b887629-846a-5862-ab25-d24d92c22e69', '37d780cb-5608-5582-ab57-dfac90503a3e', NULL, 21, 21, 'Hezekiah slept with his fathers; and Manasseh his son reigned in his place.'),
  ('0442002c-8008-540c-a3c0-1d6dd8421332', '6d10edbf-b5d9-5abd-ae22-8a6e2e7af11c', NULL, 1, 1, 'Manasseh was twelve years old when he began to reign; and he reigned fifty-five years in Jerusalem: and his mother''s name was Hephzibah.'),
  ('3d658ab9-9d97-5fff-a951-8f7ef02a54c4', '6d10edbf-b5d9-5abd-ae22-8a6e2e7af11c', NULL, 2, 2, 'He did that which was evil in the sight of Yahweh, after the abominations of the nations whom Yahweh cast out before the children of Israel.'),
  ('bc367939-fb19-54d2-a30b-bc257100163c', '6d10edbf-b5d9-5abd-ae22-8a6e2e7af11c', NULL, 3, 3, 'For he built again the high places which Hezekiah his father had destroyed; and he reared up altars for Baal, and made an Asherah, as did Ahab king of Israel, and worshiped all the army of the sky, and served them.'),
  ('735e5c19-2f59-58a2-a207-9b2cc2d0509d', '6d10edbf-b5d9-5abd-ae22-8a6e2e7af11c', NULL, 4, 4, 'He built altars in the house of Yahweh, of which Yahweh said, "I will put my name in Jerusalem."'),
  ('af8bda07-c50e-5a49-a2f8-6d0019b0c118', '6d10edbf-b5d9-5abd-ae22-8a6e2e7af11c', NULL, 5, 5, 'He built altars for all the army of the sky in the two courts of the house of Yahweh.'),
  ('00176229-3776-543e-ad96-69ff2b387a6b', '6d10edbf-b5d9-5abd-ae22-8a6e2e7af11c', NULL, 6, 6, 'He made his son to pass through the fire, and practiced sorcery, and used enchantments, and dealt with those who had familiar spirits, and with wizards: he worked much evil in the sight of Yahweh, to provoke him to anger.'),
  ('55bfc6d3-53bc-5d66-aaf8-e87a6c2f5065', '6d10edbf-b5d9-5abd-ae22-8a6e2e7af11c', NULL, 7, 7, 'He set the engraved image of Asherah, that he had made, in the house of which Yahweh said to David and to Solomon his son, "In this house, and in Jerusalem, which I have chosen out of all the tribes of Israel, will I put my name forever;'),
  ('95e72f68-4168-5c2c-a5fe-765eda334f7b', '6d10edbf-b5d9-5abd-ae22-8a6e2e7af11c', NULL, 8, 8, 'neither will I cause the feet of Israel to wander any more out of the land which I gave their fathers, if only they will observe to do according to all that I have commanded them, and according to all the law that my servant Moses commanded them."'),
  ('04b0df92-ee12-56ad-a162-ffd8be1a4fb3', '6d10edbf-b5d9-5abd-ae22-8a6e2e7af11c', NULL, 9, 9, 'But they didn''t listen: and Manasseh seduced them to do that which is evil more than did the nations whom Yahweh destroyed before the children of Israel.'),
  ('d980d9dc-9c21-5ca0-a29f-2d98f19049b5', '6d10edbf-b5d9-5abd-ae22-8a6e2e7af11c', NULL, 10, 10, 'Yahweh spoke by his servants the prophets, saying,'),
  ('d182b12a-afd1-53e4-ad96-75dfd0638bba', '6d10edbf-b5d9-5abd-ae22-8a6e2e7af11c', NULL, 11, 11, '"Because Manasseh king of Judah has done these abominations, and has done wickedly above all that the Amorites did, who were before him, and has made Judah also to sin with his idols;'),
  ('143eeaa0-6c80-5d9b-a0b8-6d8c18ccc836', '6d10edbf-b5d9-5abd-ae22-8a6e2e7af11c', NULL, 12, 12, 'therefore thus says Yahweh, the God of Israel, ''Behold, I bring such evil on Jerusalem and Judah, that whoever hears of it, both his ears shall tingle.'),
  ('d7d2d7ec-0d41-52f7-a856-b211116eee0f', '6d10edbf-b5d9-5abd-ae22-8a6e2e7af11c', NULL, 13, 13, 'I will stretch over Jerusalem the line of Samaria, and the plummet of the house of Ahab; and I will wipe Jerusalem as a man wipes a dish, wiping it and turning it upside down.'),
  ('cb83bb3b-d659-512b-ad4a-3b23d125cbcb', '6d10edbf-b5d9-5abd-ae22-8a6e2e7af11c', NULL, 14, 14, 'I will cast off the remnant of my inheritance, and deliver them into the hand of their enemies. They will become a prey and a spoil to all their enemies;'),
  ('a886eee7-b3bc-5391-a18d-a563f19cdbf6', '6d10edbf-b5d9-5abd-ae22-8a6e2e7af11c', NULL, 15, 15, 'because they have done that which is evil in my sight, and have provoked me to anger, since the day their fathers came forth out of Egypt, even to this day.''"'),
  ('ec50bf62-539b-5b52-ac86-3cccd191bfd7', '6d10edbf-b5d9-5abd-ae22-8a6e2e7af11c', NULL, 16, 16, 'Moreover Manasseh shed innocent blood very much, until he had filled Jerusalem from one end to another; besides his sin with which he made Judah to sin, in doing that which was evil in the sight of Yahweh.'),
  ('b3068e53-0a46-515b-ae8c-06c3c64d8a97', '6d10edbf-b5d9-5abd-ae22-8a6e2e7af11c', NULL, 17, 17, 'Now the rest of the acts of Manasseh, and all that he did, and his sin that he sinned, aren''t they written in the book of the chronicles of the kings of Judah?'),
  ('c3dcb26d-6de3-56d2-ac31-349642346df9', '6d10edbf-b5d9-5abd-ae22-8a6e2e7af11c', NULL, 18, 18, 'Manasseh slept with his fathers, and was buried in the garden of his own house, in the garden of Uzza: and Amon his son reigned in his place.'),
  ('597b815a-2ab9-5911-acb7-4582e55fe998', '6d10edbf-b5d9-5abd-ae22-8a6e2e7af11c', NULL, 19, 19, 'Amon was twenty-two years old when he began to reign; and he reigned two years in Jerusalem: and his mother''s name was Meshullemeth the daughter of Haruz of Jotbah.'),
  ('f264c699-24de-5146-ae14-c135c2e0ccfe', '6d10edbf-b5d9-5abd-ae22-8a6e2e7af11c', NULL, 20, 20, 'He did that which was evil in the sight of Yahweh, as did Manasseh his father.'),
  ('a6a3482e-2a9b-58ba-aaa8-952f9384f34c', '6d10edbf-b5d9-5abd-ae22-8a6e2e7af11c', NULL, 21, 21, 'He walked in all the way that his father walked in, and served the idols that his father served, and worshiped them:'),
  ('5b84592a-127f-5783-a348-0f669469450e', '6d10edbf-b5d9-5abd-ae22-8a6e2e7af11c', NULL, 22, 22, 'and he forsook Yahweh, the God of his fathers, and didn''t walk in the way of Yahweh.'),
  ('da44a413-454d-5666-a3f6-d2dfdf244f50', '6d10edbf-b5d9-5abd-ae22-8a6e2e7af11c', NULL, 23, 23, 'The servants of Amon conspired against him, and put the king to death in his own house.'),
  ('263ba3a9-6095-526f-a009-6b43c19b4268', '6d10edbf-b5d9-5abd-ae22-8a6e2e7af11c', NULL, 24, 24, 'But the people of the land killed all those who had conspired against king Amon; and the people of the land made Josiah his son king in his place.'),
  ('8ea5c368-c01a-52bb-a481-f93315711671', '6d10edbf-b5d9-5abd-ae22-8a6e2e7af11c', NULL, 25, 25, 'Now the rest of the acts of Amon which he did, aren''t they written in the book of the chronicles of the kings of Judah?'),
  ('cdf06609-9c2f-58f3-ae8a-4f5cca25ab29', '6d10edbf-b5d9-5abd-ae22-8a6e2e7af11c', NULL, 26, 26, 'He was buried in his tomb in the garden of Uzza: and Josiah his son reigned in his place.'),
  ('a9826b83-a514-52a6-a357-b73288c971c8', '496f5cbd-2ebe-5b57-a68f-952ab85e13ef', NULL, 1, 1, 'Josiah was eight years old when he began to reign; and he reigned thirty-one years in Jerusalem: and his mother''s name was Jedidah the daughter of Adaiah of Bozkath.'),
  ('77fc5506-d8ed-55e4-a24a-bed3d444aef3', '496f5cbd-2ebe-5b57-a68f-952ab85e13ef', NULL, 2, 2, 'He did that which was right in the eyes of Yahweh, and walked in all the way of David his father, and didn''t turn aside to the right hand or to the left.'),
  ('aaacd66d-a021-5fc5-a66a-0371a71a8bdb', '496f5cbd-2ebe-5b57-a68f-952ab85e13ef', NULL, 3, 3, 'It happened in the eighteenth year of king Josiah, that the king sent Shaphan, the son of Azaliah the son of Meshullam, the scribe, to the house of Yahweh, saying,'),
  ('1da6094a-14b9-56d6-a17a-5b9704e53111', '496f5cbd-2ebe-5b57-a68f-952ab85e13ef', NULL, 4, 4, '"Go up to Hilkiah the high priest, that he may sum the money which is brought into the house of Yahweh, which the keepers of the threshold have gathered of the people.'),
  ('91b093fb-043d-5ae5-a4a3-95954e8490c1', '496f5cbd-2ebe-5b57-a68f-952ab85e13ef', NULL, 5, 5, 'Let them deliver it into the hand of the workmen who have the oversight of the house of Yahweh; and let them give it to the workmen who are in the house of Yahweh, to repair the breaches of the house,'),
  ('f383fbee-fa1b-56a5-a2ee-7d052765043d', '496f5cbd-2ebe-5b57-a68f-952ab85e13ef', NULL, 6, 6, 'to the carpenters, and to the builders, and to the masons, and for buying timber and cut stone to repair the house.'),
  ('5ce6b202-cc46-5f27-ad13-64c3b686215b', '496f5cbd-2ebe-5b57-a68f-952ab85e13ef', NULL, 7, 7, 'However there was no accounting made with them of the money that was delivered into their hand; for they dealt faithfully."'),
  ('342750f7-f0ae-5e46-a06a-f143b7dfb214', '496f5cbd-2ebe-5b57-a68f-952ab85e13ef', NULL, 8, 8, 'Hilkiah the high priest said to Shaphan the scribe, "I have found the book of the law in the house of Yahweh." Hilkiah delivered the book to Shaphan, and he read it.'),
  ('0a059417-009e-51a9-a458-767bef986ff9', '496f5cbd-2ebe-5b57-a68f-952ab85e13ef', NULL, 9, 9, 'Shaphan the scribe came to the king, and brought the king word again, and said, "Your servants have emptied out the money that was found in the house, and have delivered it into the hand of the workmen who have the oversight of the house of Yahweh."'),
  ('77142739-2f48-550b-af7a-e197f34e8c0b', '496f5cbd-2ebe-5b57-a68f-952ab85e13ef', NULL, 10, 10, 'Shaphan the scribe told the king, saying, "Hilkiah the priest has delivered a book to me." Shaphan read it before the king.'),
  ('b895c507-c599-5c2f-aec5-f158bf0a8414', '496f5cbd-2ebe-5b57-a68f-952ab85e13ef', NULL, 11, 11, 'It happened, when the king had heard the words of the book of the law, that he tore his clothes.'),
  ('492d4dee-20cc-5227-abcd-d18513fd179c', '496f5cbd-2ebe-5b57-a68f-952ab85e13ef', NULL, 12, 12, 'The king commanded Hilkiah the priest, and Ahikam the son of Shaphan, and Achbor the son of Micaiah, and Shaphan the scribe, and Asaiah the king''s servant, saying,'),
  ('4b06ef96-da54-5340-a2aa-d12130dbaa12', '496f5cbd-2ebe-5b57-a68f-952ab85e13ef', NULL, 13, 13, '"Go inquire of Yahweh for me, and for the people, and for all Judah, concerning the words of this book that is found; for great is the wrath of Yahweh that is kindled against us, because our fathers have not listened to the words of this book, to do according to all that which is written concerning us."'),
  ('3569a6e3-eed6-555e-ad1e-19c38d82862d', '496f5cbd-2ebe-5b57-a68f-952ab85e13ef', NULL, 14, 14, 'So Hilkiah the priest, and Ahikam, and Achbor, and Shaphan, and Asaiah, went to Huldah the prophetess, the wife of Shallum the son of Tikvah, the son of Harhas, keeper of the wardrobe (now she lived in Jerusalem in the second quarter); and they talked with her.'),
  ('01e3bcd3-e4c9-5582-af40-88dbf663edea', '496f5cbd-2ebe-5b57-a68f-952ab85e13ef', NULL, 15, 15, 'She said to them, "Thus says Yahweh, the God of Israel: ''Tell the man who sent you to me,'),
  ('71f7699a-2b13-5a3e-ad0d-6760b9586e8f', '496f5cbd-2ebe-5b57-a68f-952ab85e13ef', NULL, 16, 16, '"Thus says Yahweh, ''Behold, I will bring evil on this place, and on its inhabitants, even all the words of the book which the king of Judah has read.'),
  ('616c4e07-ced3-5478-a779-2d594c337eff', '496f5cbd-2ebe-5b57-a68f-952ab85e13ef', NULL, 17, 17, 'Because they have forsaken me, and have burned incense to other gods, that they might provoke me to anger with all the work of their hands, therefore my wrath shall be kindled against this place, and it shall not be quenched.''"'),
  ('8443d614-7a71-536d-ad3b-3ffcb3406679', '496f5cbd-2ebe-5b57-a68f-952ab85e13ef', NULL, 18, 18, 'But to the king of Judah, who sent you to inquire of Yahweh, thus you shall tell him, "Thus says Yahweh, the God of Israel: ''Concerning the words which you have heard,'),
  ('5c9eed56-e831-550c-ac02-c71cbba03f4c', '496f5cbd-2ebe-5b57-a68f-952ab85e13ef', NULL, 19, 19, 'because your heart was tender, and you humbled yourself before Yahweh, when you heard what I spoke against this place, and against its inhabitants, that they should become a desolation and a curse, and have torn your clothes, and wept before me; I also have heard you,'' says Yahweh.'),
  ('7b17ffcb-78d8-5e24-aee7-3eba706cfa61', '496f5cbd-2ebe-5b57-a68f-952ab85e13ef', NULL, 20, 20, '''Therefore, behold, I will gather you to your fathers, and you shall be gathered to your grave in peace, neither shall your eyes see all the evil which I will bring on this place.''"''" They brought back this message to the king.'),
  ('b51e197d-5cfa-5e21-a08d-949a878c9497', '99b8ba91-d04c-5735-ab8c-b54b1f668ada', NULL, 1, 1, 'The king sent, and they gathered to him all the elders of Judah and of Jerusalem.'),
  ('e5b4b95c-ac6d-5db5-ae6e-65bda6cdf004', '99b8ba91-d04c-5735-ab8c-b54b1f668ada', NULL, 2, 2, 'The king went up to the house of Yahweh, and all the men of Judah and all the inhabitants of Jerusalem with him, and the priests, and the prophets, and all the people, both small and great: and he read in their ears all the words of the book of the covenant which was found in the house of Yahweh.'),
  ('810e7b81-6406-502f-a742-87a227217c71', '99b8ba91-d04c-5735-ab8c-b54b1f668ada', NULL, 3, 3, 'The king stood by the pillar, and made a covenant before Yahweh, to walk after Yahweh, and to keep his commandments, and his testimonies, and his statutes, with all [his] heart, and all [his] soul, to confirm the words of this covenant that were written in this book: and all the people stood to the covenant.'),
  ('baa86f39-b629-51b2-a8fb-555aba20ff46', '99b8ba91-d04c-5735-ab8c-b54b1f668ada', NULL, 4, 4, 'The king commanded Hilkiah the high priest, and the priests of the second order, and the keepers of the threshold, to bring forth out of the temple of Yahweh all the vessels that were made for Baal, and for the Asherah, and for all the army of the sky, and he burned them outside of Jerusalem in the fields of the Kidron, and carried the ashes of them to Bethel.'),
  ('2a8871be-3bf7-5f7b-a7db-4285c16ed5ed', '99b8ba91-d04c-5735-ab8c-b54b1f668ada', NULL, 5, 5, 'He put down the idolatrous priests, whom the kings of Judah had ordained to burn incense in the high places in the cities of Judah, and in the places around Jerusalem; those also who burned incense to Baal, to the sun, and to the moon, and to the planets, and to all the army of the sky.'),
  ('552e7617-4c54-568c-acc5-ba687c5bc6df', '99b8ba91-d04c-5735-ab8c-b54b1f668ada', NULL, 6, 6, 'He brought out the Asherah from the house of Yahweh, outside of Jerusalem, to the brook Kidron, and burned it at the brook Kidron, and beat it to dust, and cast its dust on the graves of the common people.'),
  ('474ee5cc-1256-5fdf-aa25-69394fe5ca41', '99b8ba91-d04c-5735-ab8c-b54b1f668ada', NULL, 7, 7, 'He broke down the houses of the sodomites, that were in the house of Yahweh, where the women wove hangings for the Asherah.'),
  ('b0ed7a85-33d8-5aaf-ae23-9cd34500dcb6', '99b8ba91-d04c-5735-ab8c-b54b1f668ada', NULL, 8, 8, 'He brought all the priests out of the cities of Judah, and defiled the high places where the priests had burned incense, from Geba to Beersheba; and he broke down the high places of the gates that were at the entrance of the gate of Joshua the governor of the city, which were on a man''s left hand at the gate of the city.'),
  ('166f1940-0adb-543d-a108-5feecbd77dd3', '99b8ba91-d04c-5735-ab8c-b54b1f668ada', NULL, 9, 9, 'Nevertheless the priests of the high places didn''t come up to the altar of Yahweh in Jerusalem, but they ate unleavened bread among their brothers.'),
  ('c9cd7d93-8475-5105-a8a4-7049e6e64d2b', '99b8ba91-d04c-5735-ab8c-b54b1f668ada', NULL, 10, 10, 'He defiled Topheth, which is in the valley of the children of Hinnom, that no man might make his son or his daughter to pass through the fire to Molech.'),
  ('ba9bd599-050f-53f1-a2f0-e626c55c8bd5', '99b8ba91-d04c-5735-ab8c-b54b1f668ada', NULL, 11, 11, 'He took away the horses that the kings of Judah had given to the sun, at the entrance of the house of Yahweh, by the room of Nathan Melech the officer, who was in the court; and he burned the chariots of the sun with fire.'),
  ('17a34cfe-3166-5bd5-a16e-c4725ba43777', '99b8ba91-d04c-5735-ab8c-b54b1f668ada', NULL, 12, 12, 'The altars that were on the roof of the upper room of Ahaz, which the kings of Judah had made, and the altars which Manasseh had made in the two courts of the house of Yahweh, did the king break down, and beat [them] down from there, and cast the dust of them into the brook Kidron.'),
  ('c82ab1f8-c106-50c1-ae23-87dd4c4b0dd2', '99b8ba91-d04c-5735-ab8c-b54b1f668ada', NULL, 13, 13, 'The high places that were before Jerusalem, which were on the right hand of the mountain of corruption, which Solomon the king of Israel had built for Ashtoreth the abomination of the Sidonians, and for Chemosh the abomination of Moab, and for Milcom the abomination of the children of Ammon, did the king defile.'),
  ('ade01c85-b90b-59b9-ac93-9b6de8e65884', '99b8ba91-d04c-5735-ab8c-b54b1f668ada', NULL, 14, 14, 'He broke in pieces the pillars, and cut down the Asherim, and filled their places with the bones of men.'),
  ('5541f1c7-9f52-58b3-ae57-8ed06f37c97c', '99b8ba91-d04c-5735-ab8c-b54b1f668ada', NULL, 15, 15, 'Moreover the altar that was at Bethel, and the high place which Jeroboam the son of Nebat, who made Israel to sin, had made, even that altar and the high place he broke down; and he burned the high place and beat it to dust, and burned the Asherah.'),
  ('f4b94f4d-e119-5dc0-a985-e4e21cb4193c', '99b8ba91-d04c-5735-ab8c-b54b1f668ada', NULL, 16, 16, 'As Josiah turned himself, he spied the tombs that were there in the mountain; and he sent, and took the bones out of the tombs, and burned them on the altar, and defiled it, according to the word of Yahweh which the man of God proclaimed, who proclaimed these things.'),
  ('ba49a85f-7ad0-5f50-a07d-995dda9d5067', '99b8ba91-d04c-5735-ab8c-b54b1f668ada', NULL, 17, 17, 'Then he said, "What monument is that which I see?" The men of the city told him, "It is the tomb of the man of God, who came from Judah, and proclaimed these things that you have done against the altar of Bethel."'),
  ('de238bd3-5096-57c6-a054-40541613f353', '99b8ba91-d04c-5735-ab8c-b54b1f668ada', NULL, 18, 18, 'He said, "Let him be! Let no man move his bones." So they let his bones alone, with the bones of the prophet who came out of Samaria.'),
  ('652d2586-1429-5d69-a5e2-0b14be54fad2', '99b8ba91-d04c-5735-ab8c-b54b1f668ada', NULL, 19, 19, 'All the houses also of the high places that were in the cities of Samaria, which the kings of Israel had made to provoke [Yahweh] to anger, Josiah took away, and did to them according to all the acts that he had done in Bethel.'),
  ('c7141fca-c761-5e56-a9a2-94d4dd89762f', '99b8ba91-d04c-5735-ab8c-b54b1f668ada', NULL, 20, 20, 'He killed all the priests of the high places that were there, on the altars, and burned men''s bones on them; and he returned to Jerusalem.'),
  ('388130df-e745-5ee0-a988-498504c8e732', '99b8ba91-d04c-5735-ab8c-b54b1f668ada', NULL, 21, 21, 'The king commanded all the people, saying, "Keep the Passover to Yahweh your God, as it is written in this book of the covenant."'),
  ('174179ad-7e73-5bc0-af77-42dc119dae7e', '99b8ba91-d04c-5735-ab8c-b54b1f668ada', NULL, 22, 22, 'Surely there was not kept such a Passover from the days of the judges who judged Israel, nor in all the days of the kings of Israel, nor of the kings of Judah;'),
  ('5f2ba168-f06e-5d5e-af0a-0e71c92611fc', '99b8ba91-d04c-5735-ab8c-b54b1f668ada', NULL, 23, 23, 'but in the eighteenth year of king Josiah was this Passover kept to Yahweh in Jerusalem.'),
  ('6462571c-60a7-5c4c-aba3-7d13e3e3d2ca', '99b8ba91-d04c-5735-ab8c-b54b1f668ada', NULL, 24, 24, 'Moreover those who had familiar spirits, and the wizards, and the teraphim, and the idols, and all the abominations that were seen in the land of Judah and in Jerusalem, did Josiah put away, that he might confirm the words of the law which were written in the book that Hilkiah the priest found in the house of Yahweh.'),
  ('4d78a8c0-0591-54b1-a1ac-82b618b140e0', '99b8ba91-d04c-5735-ab8c-b54b1f668ada', NULL, 25, 25, 'Like him was there no king before him, who turned to Yahweh with all his heart, and with all his soul, and with all his might, according to all the law of Moses; neither after him arose there any like him.'),
  ('d1781a0a-eab8-5ed3-a578-a936b873d3b0', '99b8ba91-d04c-5735-ab8c-b54b1f668ada', NULL, 26, 26, 'Notwithstanding, Yahweh didn''t turn from the fierceness of his great wrath, with which his anger was kindled against Judah, because of all the provocation with which Manasseh had provoked him.'),
  ('7ada3e04-2d88-5690-a94f-abd834b68104', '99b8ba91-d04c-5735-ab8c-b54b1f668ada', NULL, 27, 27, 'Yahweh said, "I will remove Judah also out of my sight, as I have removed Israel, and I will cast off this city which I have chosen, even Jerusalem, and the house of which I said, ''My name shall be there.''"'),
  ('54dc07e2-e6e0-5051-a79c-a683d35cc476', '99b8ba91-d04c-5735-ab8c-b54b1f668ada', NULL, 28, 28, 'Now the rest of the acts of Josiah, and all that he did, aren''t they written in the book of the chronicles of the kings of Judah?'),
  ('b4ad001c-b538-5b89-a05a-1be89373fff1', '99b8ba91-d04c-5735-ab8c-b54b1f668ada', NULL, 29, 29, 'In his days Pharaoh Necoh king of Egypt went up against the king of Assyria to the river Euphrates: and king Josiah went against him; and [Pharaoh Necoh] killed him at Megiddo, when he had seen him.'),
  ('18cfec11-6ec4-5b29-afcb-82f06db9832e', '99b8ba91-d04c-5735-ab8c-b54b1f668ada', NULL, 30, 30, 'His servants carried him in a chariot dead from Megiddo, and brought him to Jerusalem, and buried him in his own tomb. The people of the land took Jehoahaz the son of Josiah, and anointed him, and made him king in his father''s place.'),
  ('438a4b7a-f3bf-5c3a-ab70-81d50fe722a4', '99b8ba91-d04c-5735-ab8c-b54b1f668ada', NULL, 31, 31, 'Jehoahaz was twenty-three years old when he began to reign; and he reigned three months in Jerusalem: and his mother''s name was Hamutal the daughter of Jeremiah of Libnah.'),
  ('2de065cb-a2ea-51e4-a9a6-0c2cd29a9860', '99b8ba91-d04c-5735-ab8c-b54b1f668ada', NULL, 32, 32, 'He did that which was evil in the sight of Yahweh, according to all that his fathers had done.'),
  ('24926bbd-3e03-5382-a0ab-1546583da98f', '99b8ba91-d04c-5735-ab8c-b54b1f668ada', NULL, 33, 33, 'Pharaoh Necoh put him in bonds at Riblah in the land of Hamath, that he might not reign in Jerusalem; and put the land to a tribute of one hundred talents of silver, and a talent of gold.'),
  ('835f21b2-218a-5f45-afe3-27aa2a4ea8cd', '99b8ba91-d04c-5735-ab8c-b54b1f668ada', NULL, 34, 34, 'Pharaoh Necoh made Eliakim the son of Josiah king in the place of Josiah his father, and changed his name to Jehoiakim: but he took Jehoahaz away; and he came to Egypt, and died there.'),
  ('11a3a4e8-4b43-55b3-a4c6-fa2766899b5b', '99b8ba91-d04c-5735-ab8c-b54b1f668ada', NULL, 35, 35, 'Jehoiakim gave the silver and the gold to Pharaoh; but he taxed the land to give the money according to the commandment of Pharaoh: he exacted the silver and the gold of the people of the land, of everyone according to his taxation, to give it to Pharaoh Necoh.'),
  ('ba5b7661-fdbf-5d40-a40f-b8a8f2c273a5', '99b8ba91-d04c-5735-ab8c-b54b1f668ada', NULL, 36, 36, 'Jehoiakim was twenty-five years old when he began to reign; and he reigned eleven years in Jerusalem: and his mother''s name was Zebidah the daughter of Pedaiah of Rumah.'),
  ('deacdf69-6aba-52ed-aaa7-26eb54bd2744', '99b8ba91-d04c-5735-ab8c-b54b1f668ada', NULL, 37, 37, 'He did that which was evil in the sight of Yahweh, according to all that his fathers had done.'),
  ('5b13d59a-17cc-52d5-aadb-a6fea027fc32', 'd6fe8076-23ae-5346-a96b-d4c03b295234', NULL, 1, 1, 'In his days Nebuchadnezzar king of Babylon came up, and Jehoiakim became his servant three years: then he turned and rebelled against him.'),
  ('642c8acc-befd-5965-a8b6-59485e1e551e', 'd6fe8076-23ae-5346-a96b-d4c03b295234', NULL, 2, 2, 'Yahweh sent against him bands of the Chaldeans, and bands of the Syrians, and bands of the Moabites, and bands of the children of Ammon, and sent them against Judah to destroy it, according to the word of Yahweh, which he spoke by his servants the prophets.'),
  ('5eaa24b1-8fd0-54d6-a560-627845e3def8', 'd6fe8076-23ae-5346-a96b-d4c03b295234', NULL, 3, 3, 'Surely at the commandment of Yahweh came this on Judah, to remove them out of his sight, for the sins of Manasseh, according to all that he did,'),
  ('bb0796fc-3f2a-5467-a630-5e7e42056000', 'd6fe8076-23ae-5346-a96b-d4c03b295234', NULL, 4, 4, 'and also for the innocent blood that he shed; for he filled Jerusalem with innocent blood: and Yahweh would not pardon.'),
  ('59649f91-475e-55e5-a70b-05f99ac4b397', 'd6fe8076-23ae-5346-a96b-d4c03b295234', NULL, 5, 5, 'Now the rest of the acts of Jehoiakim, and all that he did, aren''t they written in the book of the chronicles of the kings of Judah?'),
  ('360c2c68-2263-5060-a3ff-0157891d7bbf', 'd6fe8076-23ae-5346-a96b-d4c03b295234', NULL, 6, 6, 'So Jehoiakim slept with his fathers; and Jehoiachin his son reigned in his place.'),
  ('4ab31544-d3e0-58c1-aa30-648330503f97', 'd6fe8076-23ae-5346-a96b-d4c03b295234', NULL, 7, 7, 'The king of Egypt didn''t come again out of his land any more; for the king of Babylon had taken, from the brook of Egypt to the river Euphrates, all that pertained to the king of Egypt.'),
  ('4e39c42e-5578-578e-a843-b3a90bb2cfc0', 'd6fe8076-23ae-5346-a96b-d4c03b295234', NULL, 8, 8, 'Jehoiachin was eighteen years old when he began to reign; and he reigned in Jerusalem three months: and his mother''s name was Nehushta the daughter of Elnathan of Jerusalem.'),
  ('0ac044b3-0dd4-5eb7-a2d9-9f0a366e6d9f', 'd6fe8076-23ae-5346-a96b-d4c03b295234', NULL, 9, 9, 'He did that which was evil in the sight of Yahweh, according to all that his father had done.'),
  ('5c085463-d6e9-5f9c-ad65-c743e2d2df9c', 'd6fe8076-23ae-5346-a96b-d4c03b295234', NULL, 10, 10, 'At that time the servants of Nebuchadnezzar king of Babylon came up to Jerusalem, and the city was besieged.'),
  ('5cfc8dd1-2759-52b7-aec5-dce4dc477bfd', 'd6fe8076-23ae-5346-a96b-d4c03b295234', NULL, 11, 11, 'Nebuchadnezzar king of Babylon came to the city, while his servants were besieging it;'),
  ('9663a2a8-981c-5442-af69-0102313b7901', 'd6fe8076-23ae-5346-a96b-d4c03b295234', NULL, 12, 12, 'and Jehoiachin the king of Judah went out to the king of Babylon, he, and his mother, and his servants, and his princes, and his officers: and the king of Babylon took him in the eighth year of his reign.'),
  ('e5f3895d-4ca4-50c5-ae5d-69118fcb9fec', 'd6fe8076-23ae-5346-a96b-d4c03b295234', NULL, 13, 13, 'He carried out there all the treasures of the house of Yahweh, and the treasures of the king''s house, and cut in pieces all the vessels of gold, which Solomon king of Israel had made in the temple of Yahweh, as Yahweh had said.'),
  ('08dd3704-270b-5633-a775-b354737af719', 'd6fe8076-23ae-5346-a96b-d4c03b295234', NULL, 14, 14, 'He carried away all Jerusalem, and all the princes, and all the mighty men of valor, even ten thousand captives, and all the craftsmen and the smiths; none remained, except the poorest sort of the people of the land.'),
  ('002af989-5c6a-52cb-a66a-ad8b3a366f4c', 'd6fe8076-23ae-5346-a96b-d4c03b295234', NULL, 15, 15, 'He carried away Jehoiachin to Babylon; and the king''s mother, and the king''s wives, and his officers, and the chief men of the land, carried he into captivity from Jerusalem to Babylon.'),
  ('85e80cb0-d78b-5652-a16f-8b0d72e52ed6', 'd6fe8076-23ae-5346-a96b-d4c03b295234', NULL, 16, 16, 'All the men of might, even seven thousand, and the craftsmen and the smiths one thousand, all of them strong and apt for war, even them the king of Babylon brought captive to Babylon.'),
  ('13a70493-f397-5f07-a80d-0e95601baffc', 'd6fe8076-23ae-5346-a96b-d4c03b295234', NULL, 17, 17, 'The king of Babylon made Mattaniah, [Jehoiachin''s] father''s brother, king is his place, and changed his name to Zedekiah.'),
  ('0235b828-cf60-5a80-a64c-ee3d76768e23', 'd6fe8076-23ae-5346-a96b-d4c03b295234', NULL, 18, 18, 'Zedekiah was twenty-one years old when he began to reign; and he reigned eleven years in Jerusalem: and his mother''s name was Hamutal the daughter of Jeremiah of Libnah.'),
  ('df8771d2-a75a-501d-a3fa-aef43ba13294', 'd6fe8076-23ae-5346-a96b-d4c03b295234', NULL, 19, 19, 'He did that which was evil in the sight of Yahweh, according to all that Jehoiakim had done.'),
  ('30a0e4ff-0edf-5805-a58a-d696aa808f00', 'd6fe8076-23ae-5346-a96b-d4c03b295234', NULL, 20, 20, 'For through the anger of Yahweh did it happen in Jerusalem and Judah, until he had cast them out from his presence. Zedekiah rebelled against the king of Babylon.'),
  ('cf59be72-6c74-5cd5-aa6a-128e7a5cce1f', '6c0c8d25-d26b-5dfe-ae3d-206baa47b444', NULL, 1, 1, 'It happened in the ninth year of his reign, in the tenth month, in the tenth day of the month, that Nebuchadnezzar king of Babylon came, he and all his army, against Jerusalem, and encamped against it; and they built forts against it around it.'),
  ('d0eb4de4-e7b8-59c7-a424-c3e61f7e1e2b', '6c0c8d25-d26b-5dfe-ae3d-206baa47b444', NULL, 2, 2, 'So the city was besieged to the eleventh year of king Zedekiah.'),
  ('86632fe8-0fdd-59e5-ad5f-c3da79d25414', '6c0c8d25-d26b-5dfe-ae3d-206baa47b444', NULL, 3, 3, 'On the ninth day of the [fourth] month the famine was severe in the city, so that there was no bread for the people of the land.'),
  ('5396e62d-fadf-5658-a021-a4d36def3433', '6c0c8d25-d26b-5dfe-ae3d-206baa47b444', NULL, 4, 4, 'Then a breach was made in the city, and all the men of war [fled] by night by the way of the gate between the two walls, which was by the king''s garden (now the Chaldeans were against the city around it); and [the king] went by the way of the Arabah.'),
  ('62810092-033b-5978-a2d8-b755e689141b', '6c0c8d25-d26b-5dfe-ae3d-206baa47b444', NULL, 5, 5, 'But the army of the Chaldeans pursued after the king, and overtook him in the plains of Jericho; and all his army was scattered from him.'),
  ('d6e69291-5812-5219-a136-5220b89cd14c', '6c0c8d25-d26b-5dfe-ae3d-206baa47b444', NULL, 6, 6, 'Then they took the king, and carried him up to the king of Babylon to Riblah; and they gave judgment on him.'),
  ('dc2c5827-8f25-5edf-a21f-f99637934509', '6c0c8d25-d26b-5dfe-ae3d-206baa47b444', NULL, 7, 7, 'They killed the sons of Zedekiah before his eyes, and put out the eyes of Zedekiah, and bound him in fetters, and carried him to Babylon.'),
  ('9fd74138-e206-5b07-ad50-5422827219d9', '6c0c8d25-d26b-5dfe-ae3d-206baa47b444', NULL, 8, 8, 'Now in the fifth month, on the seventh day of the month, which was the nineteenth year of king Nebuchadnezzar, king of Babylon, came Nebuzaradan the captain of the guard, a servant of the king of Babylon, to Jerusalem.'),
  ('e816b716-2ebf-58f4-ac3b-e2cf360ed18b', '6c0c8d25-d26b-5dfe-ae3d-206baa47b444', NULL, 9, 9, 'He burnt the house of Yahweh, and the king''s house; and all the houses of Jerusalem, even every great house, burnt he with fire.'),
  ('da53664e-1936-505e-af42-a6d3cd66d7ae', '6c0c8d25-d26b-5dfe-ae3d-206baa47b444', NULL, 10, 10, 'All the army of the Chaldeans, who were [with] the captain of the guard, broke down the walls around Jerusalem.'),
  ('5adda0ef-9bfe-5006-a69c-be56e5a9d703', '6c0c8d25-d26b-5dfe-ae3d-206baa47b444', NULL, 11, 11, 'The residue of the people who were left in the city, and those who fell away, who fell to the king of Babylon, and the residue of the multitude, did Nebuzaradan the captain of the guard carry away captive.'),
  ('b544a406-1c70-548f-a2fd-e17c4041e7de', '6c0c8d25-d26b-5dfe-ae3d-206baa47b444', NULL, 12, 12, 'But the captain of the guard left of the poorest of the land to work the vineyards and fields.'),
  ('7e14350a-5f4e-526f-a5c1-d576467b368c', '6c0c8d25-d26b-5dfe-ae3d-206baa47b444', NULL, 13, 13, 'The pillars of brass that were in the house of Yahweh, and the bases and the bronze sea that were in the house of Yahweh, did the Chaldeans break in pieces, and carried the brass of them to Babylon.'),
  ('bcd7855d-8eca-56a9-aa75-39bbb82bac26', '6c0c8d25-d26b-5dfe-ae3d-206baa47b444', NULL, 14, 14, 'The pots, and the shovels, and the snuffers, and the spoons, and all the vessels of brass with which they ministered, took they away.'),
  ('28d66273-851c-5bb4-af00-0b42659580e1', '6c0c8d25-d26b-5dfe-ae3d-206baa47b444', NULL, 15, 15, 'The fire pans, and the basins, that which was of gold, in gold, and that which was of silver, in silver, the captain of the guard took away.'),
  ('26edeb71-0922-54f0-ac6f-71018a02b828', '6c0c8d25-d26b-5dfe-ae3d-206baa47b444', NULL, 16, 16, 'The two pillars, the one sea, and the bases, which Solomon had made for the house of Yahweh, the brass of all these vessels was without weight.'),
  ('881aaef3-72fb-5e17-a996-22f9a34cdbe0', '6c0c8d25-d26b-5dfe-ae3d-206baa47b444', NULL, 17, 17, 'The height of the one pillar was eighteen cubits, and a capital of brass was on it; and the height of the capital was three cubits, with network and pomegranates on the capital around it, all of brass: and like to these had the second pillar with network.'),
  ('ecb2a2d5-41ea-5260-ac65-25e9f87963b1', '6c0c8d25-d26b-5dfe-ae3d-206baa47b444', NULL, 18, 18, 'The captain of the guard took Seraiah the chief priest, and Zephaniah the second priest, and the three keepers of the threshold:'),
  ('dd3c6e89-af74-5cb5-ad89-c593db433bfc', '6c0c8d25-d26b-5dfe-ae3d-206baa47b444', NULL, 19, 19, 'and out of the city he took an officer who was set over the men of war; and five men of those who saw the king''s face, who were found in the city; and the scribe, the captain of the army, who mustered the people of the land; and sixty men of the people of the land, who were found in the city.'),
  ('cc0ea90a-848b-5b61-a19f-d91d7935f152', '6c0c8d25-d26b-5dfe-ae3d-206baa47b444', NULL, 20, 20, 'Nebuzaradan the captain of the guard took them, and brought them to the king of Babylon to Riblah.'),
  ('b3e6f0aa-877b-590f-a30a-476f79f0608e', '6c0c8d25-d26b-5dfe-ae3d-206baa47b444', NULL, 21, 21, 'The king of Babylon struck them, and put them to death at Riblah in the land of Hamath. So Judah was carried away captive out of his land.'),
  ('6d861511-c2a4-5d39-a9e0-75c812e3d5e2', '6c0c8d25-d26b-5dfe-ae3d-206baa47b444', NULL, 22, 22, 'As for the people who were left in the land of Judah, whom Nebuchadnezzar king of Babylon had left, even over them he made Gedaliah the son of Ahikam, the son of Shaphan, governor.'),
  ('91a19f70-0fba-5b7a-a46f-dd32e865b59c', '6c0c8d25-d26b-5dfe-ae3d-206baa47b444', NULL, 23, 23, 'Now when all the captains of the forces, they and their men, heard that the king of Babylon had made Gedaliah governor, they came to Gedaliah to Mizpah, even Ishmael the son of Nethaniah, and Johanan the son of Kareah, and Seraiah the son of Tanhumeth the Netophathite, and Jaazaniah the son of the Maacathite, they and their men.'),
  ('1f3b010d-a260-536f-a863-35efc9b41e5b', '6c0c8d25-d26b-5dfe-ae3d-206baa47b444', NULL, 24, 24, 'Gedaliah swore to them and to their men, and said to them, "Don''t be afraid because of the servants of the Chaldeans. Dwell in the land, and serve the king of Babylon, and it shall be well with you."'),
  ('30ae250d-c0fe-51f3-a9ce-70b9ed132bc1', '6c0c8d25-d26b-5dfe-ae3d-206baa47b444', NULL, 25, 25, 'But it happened in the seventh month, that Ishmael the son of Nethaniah, the son of Elishama, of the royal seed came, and ten men with him, and struck Gedaliah, so that he died, and the Jews and the Chaldeans that were with him at Mizpah.'),
  ('f9b5e722-c74e-52a0-adfc-2a84d5220781', '6c0c8d25-d26b-5dfe-ae3d-206baa47b444', NULL, 26, 26, 'All the people, both small and great, and the captains of the forces, arose, and came to Egypt; for they were afraid of the Chaldeans.'),
  ('a1f263cb-ae85-53d2-a752-d994deb8167f', '6c0c8d25-d26b-5dfe-ae3d-206baa47b444', NULL, 27, 27, 'It happened in the seven and thirtieth year of the captivity of Jehoiachin king of Judah, in the twelfth month, on the seven and twentieth day of the month, that Evilmerodach king of Babylon, in the year that he began to reign, did lift up the head of Jehoiachin king of Judah out of prison;'),
  ('bc4d6327-18e7-52cc-a815-afad5b8b739c', '6c0c8d25-d26b-5dfe-ae3d-206baa47b444', NULL, 28, 28, 'and he spoke kindly to him, and set his throne above the throne of the kings who were with him in Babylon,'),
  ('5cde5f05-41eb-5be2-ad37-14f07c2102eb', '6c0c8d25-d26b-5dfe-ae3d-206baa47b444', NULL, 29, 29, 'and changed his prison garments. [Jehoiachin] ate bread before him continually all the days of his life:'),
  ('e4b42970-80b7-537e-a43f-11efcbcb99f9', '6c0c8d25-d26b-5dfe-ae3d-206baa47b444', NULL, 30, 30, 'and for his allowance, there was a continual allowance given him of the king, every day a portion, all the days of his life.'),
  ('b71d2c91-1b91-5a6b-a974-26f38e1f60cc', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 1, 1, 'Adam, Seth, Enosh,'),
  ('58f34d0a-a156-5bfd-aaec-c7cc75d35398', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 2, 2, 'Kenan, Mahalalel, Jared,'),
  ('813848ea-6ae8-5d05-a95f-995d46b535a9', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 3, 3, 'Enoch, Methuselah, Lamech,'),
  ('41c3a184-4e05-54c5-a816-ea47385ce02b', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 4, 4, 'Noah, Shem, Ham, and Japheth.'),
  ('48f17ee1-b9d9-5fdb-a8db-dd86ad72fcd4', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 5, 5, 'The sons of Japheth: Gomer, and Magog, and Madai, and Javan, and Tubal, and Meshech, and Tiras.'),
  ('e575f1a9-87b6-5c92-a5f6-846035a04815', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 6, 6, 'The sons of Gomer: Ashkenaz, and Diphath, and Togarmah.'),
  ('cbf26b11-4eb8-5961-aa94-a310a0e7860c', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 7, 7, 'The sons of Javan: Elishah, and Tarshish, Kittim, and Rodanim.'),
  ('a1270f08-339a-5b89-ad44-b10f665189b3', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 8, 8, 'The sons of Ham: Cush, and Mizraim, Put, and Canaan.'),
  ('d8b68cf5-2fae-5da1-ae00-978b458256ef', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 9, 9, 'The sons of Cush: Seba, and Havilah, and Sabta, and Raama, and Sabteca. The sons of Raamah: Sheba, and Dedan.'),
  ('f928742c-1ab2-59f8-a4d0-f03ca6a318a0', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 10, 10, 'Cush became the father of Nimrod; he began to be a mighty one in the earth.'),
  ('fde847d1-d8a1-5292-a609-602ea5e8a95a', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 11, 11, 'Mizraim became the father of Ludim, and Anamim, and Lehabim, and Naphtuhim,'),
  ('b5044cfa-8141-5730-a075-e36fb2c9fdfa', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 12, 12, 'and Pathrusim, and Casluhim (where the Philistines came from), and Caphtorim.'),
  ('857a9d3f-6f23-5c2f-afbc-fd669da536fe', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 13, 13, 'Canaan became the father of Sidon his firstborn, and Heth,'),
  ('33bdf704-be7a-5e38-adf9-cb8df6c4dc0a', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 14, 14, 'and the Jebusite, and the Amorite, and the Girgashite,'),
  ('35dc87f9-3273-5944-a531-1958a25e6d9b', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 15, 15, 'and the Hivite, and the Arkite, and the Sinite,'),
  ('98548728-c245-5b1a-a758-ee2294eaa9bf', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 16, 16, 'and the Arvadite, and the Zemarite, and the Hamathite.'),
  ('799bd91e-174d-5831-ade5-70935c61f0ff', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 17, 17, 'The sons of Shem: Elam, and Asshur, and Arpachshad, and Lud, and Aram, and Uz, and Hul, and Gether, and Meshech.'),
  ('ee76fcfa-90a6-58a6-a1ba-2d84363158d9', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 18, 18, 'Arpachshad became the father of Shelah, and Shelah became the father of Eber.'),
  ('3bb2952f-108d-5de1-ad6d-d62ad196a7b6', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 19, 19, 'To Eber were born two sons: the name of the one was Peleg; for in his days the earth was divided; and his brother''s name was Joktan.'),
  ('ee3dcebd-373f-5ace-ac9c-1477876dc3f1', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 20, 20, 'Joktan became the father of Almodad, and Sheleph, and Hazarmaveth, and Jerah,'),
  ('a380bb3a-4557-563f-a21f-92aeddbdfb93', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 21, 21, 'and Hadoram, and Uzal, and Diklah,'),
  ('9e7850fc-6be4-535e-abec-504bb2060900', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 22, 22, 'and Ebal, and Abimael, and Sheba,'),
  ('07cc3f1f-c97e-531e-aac0-1a4937b682d1', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 23, 23, 'and Ophir, and Havilah, and Jobab. All these were the sons of Joktan.'),
  ('2933071d-6581-5ab3-a8bf-a34c58125cb9', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 24, 24, 'Shem, Arpachshad, Shelah,'),
  ('c42d68e0-8407-5fad-aa2b-8a638f2da6f2', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 25, 25, 'Eber, Peleg, Reu,'),
  ('fe920043-5426-529b-aef2-21a1804f5f8b', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 26, 26, 'Serug, Nahor, Terah,'),
  ('a23451ec-d770-5ca1-aee4-50abeab69912', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 27, 27, 'Abram (the same is Abraham).'),
  ('498ee3b8-af14-5160-ae9d-4b54db58ab42', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 28, 28, 'The sons of Abraham: Isaac, and Ishmael.'),
  ('606acdbe-c336-5806-a56f-f7891f2daf8a', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 29, 29, 'These are their generations: the firstborn of Ishmael, Nebaioth; then Kedar, and Adbeel, and Mibsam,'),
  ('c21a97df-4f42-5a98-ae40-0908948b6b45', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 30, 30, 'Mishma, and Dumah, Massa, Hadad, and Tema,'),
  ('3768af43-4316-54dc-af46-fdbd92a0e31c', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 31, 31, 'Jetur, Naphish, and Kedemah. These are the sons of Ishmael.'),
  ('3a0e8d35-1431-50b2-a654-8f90cd3e0c4b', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 32, 32, 'The sons of Keturah, Abraham''s concubine: she bore Zimran, and Jokshan, and Medan, and Midian, and Ishbak, and Shuah. The sons of Jokshan: Sheba, and Dedan.'),
  ('340a0918-7ccc-5079-ab84-526444492518', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 33, 33, 'The sons of Midian: Ephah, and Epher, and Hanoch, and Abida, and Eldaah. All these were the sons of Keturah.'),
  ('fbd365b3-29b4-5c9f-a39b-e3b85ddc9516', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 34, 34, 'Abraham became the father of Isaac. The sons of Isaac: Esau, and Israel.'),
  ('ceeafcd5-5356-5e95-abb0-255b4394c5d5', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 35, 35, 'The sons of Esau: Eliphaz, Reuel, and Jeush, and Jalam, and Korah.'),
  ('728659ff-70b6-5368-a128-6d1521ae3fc3', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 36, 36, 'The sons of Eliphaz: Teman, and Omar, Zephi, and Gatam, Kenaz, and Timna, and Amalek.'),
  ('39c791d9-eea5-50d7-aee2-f51a832af72b', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 37, 37, 'The sons of Reuel: Nahath, Zerah, Shammah, and Mizzah.'),
  ('8e21204a-58dc-52d4-ad84-412228e4d75b', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 38, 38, 'The sons of Seir: Lotan, and Shobal, and Zibeon, and Anah, and Dishon, and Ezer, and Dishan.'),
  ('6a0dadbc-2fce-5967-aad3-86b6be4e2fbf', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 39, 39, 'The sons of Lotan: Hori, and Homam; and Timna was Lotan''s sister.'),
  ('a35f6315-0d94-5d81-aa2a-1e5b6b945368', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 40, 40, 'The sons of Shobal: Alian, and Manahath, and Ebal, Shephi, and Onam. The sons of Zibeon: Aiah, and Anah.'),
  ('d58ad7cf-68a2-5a0a-afcc-3a3b92f083b5', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 41, 41, 'The sons of Anah: Dishon. The sons of Dishon: Hamran, and Eshban, and Ithran, and Cheran.'),
  ('756f8c24-4dc6-5c02-a152-dceb5d7800ad', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 42, 42, 'The sons of Ezer: Bilhan, and Zaavan, Jaakan. The sons of Dishan: Uz, and Aran.'),
  ('8dab9e18-11e2-540c-a8a5-8322a17f876f', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 43, 43, 'Now these are the kings who reigned in the land of Edom, before there reigned any king over the children of Israel: Bela the son of Beor; and the name of his city was Dinhabah.'),
  ('f304ac4f-0e3b-52b6-aeb7-95144a3d9a2f', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 44, 44, 'Bela died, and Jobab the son of Zerah of Bozrah reigned in his place.'),
  ('4eb35334-12aa-5e2e-a6c9-116d4f9830d5', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 45, 45, 'Jobab died, and Husham of the land of the Temanites reigned in his place.'),
  ('6ab3a452-4056-58bf-a350-127f0f839d3c', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 46, 46, 'Husham died, and Hadad the son of Bedad, who struck Midian in the field of Moab, reigned in his place; and the name of his city was Avith.'),
  ('d1f75373-ee9e-5978-aa03-9adc5c25c333', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 47, 47, 'Hadad died, and Samlah of Masrekah reigned in his place.'),
  ('0e82e9df-189d-515e-a992-382e6286ae91', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 48, 48, 'Samlah died, and Shaul of Rehoboth by the River reigned in his place.'),
  ('139ed7d7-6957-551b-a319-d9bcc5ac2a82', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 49, 49, 'Shaul died, and Baal Hanan the son of Achbor reigned in his place.'),
  ('bc3475ab-e57d-5859-a359-45863c3ff8e7', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 50, 50, 'Baal Hanan died, and Hadad reigned in his place; and the name of his city was Pai: and his wife''s name was Mehetabel, the daughter of Matred, the daughter of Mezahab.'),
  ('0139ce11-b13b-5a70-a59d-73ef81be1a97', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 51, 51, 'Hadad died. The chiefs of Edom were: chief Timna, chief Aliah, chief Jetheth,'),
  ('a541d6c6-d204-51e9-adba-a91dbe5e6052', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 52, 52, 'chief Oholibamah, chief Elah, chief Pinon,'),
  ('be914175-c01a-5bbf-ad14-782fcfbf11d4', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 53, 53, 'chief Kenaz, chief Teman, chief Mibzar,'),
  ('060c35bb-54f7-5c27-a3b4-54b3751eae49', '529a9806-7c4d-52e9-abef-f897b5f98be6', NULL, 54, 54, 'chief Magdiel, chief Iram. These are the chiefs of Edom.'),
  ('2b4bce74-e55e-5fc3-aebf-1546f67edbe2', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 1, 1, 'These are the sons of Israel: Reuben, Simeon, Levi, and Judah, Issachar, and Zebulun,'),
  ('14fca895-d061-54a1-a152-9f7c909ad492', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 2, 2, 'Dan, Joseph, and Benjamin, Naphtali, Gad, and Asher.'),
  ('e1c8fa05-17b7-5805-acc1-6b23baab503e', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 3, 3, 'The sons of Judah: Er, and Onan, and Shelah; which three were born to him of Shua''s daughter the Canaanitess. Er, Judah''s firstborn, was wicked in the sight of Yahweh; and he killed him.'),
  ('d0b1bc8e-c423-51b3-a5a2-b07642092b5a', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 4, 4, 'Tamar his daughter-in-law bore him Perez and Zerah. All the sons of Judah were five.'),
  ('e209c823-c54c-5ae2-a953-308e06328fec', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 5, 5, 'The sons of Perez: Hezron, and Hamul.'),
  ('d6d757ea-a77b-59ff-a3f5-338a1971cf8e', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 6, 6, 'The sons of Zerah: Zimri, and Ethan, and Heman, and Calcol, and Dara; five of them in all.'),
  ('02e1eb98-f494-5955-adef-b91b8ef5c481', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 7, 7, 'The sons of Carmi: Achar, the troubler of Israel, who committed a trespass in the devoted thing.'),
  ('a7f60853-4842-5a91-a8d5-6ec9824dec67', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 8, 8, 'The sons of Ethan: Azariah.'),
  ('de41054c-8596-5d99-a51f-a0317247cd38', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 9, 9, 'The sons also of Hezron, who were born to him: Jerahmeel, and Ram, and Chelubai.'),
  ('fa469804-d8b4-5359-aede-72176a382c65', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 10, 10, 'Ram became the father of Amminadab, and Amminadab became the father of Nahshon, prince of the children of Judah;'),
  ('90aeaea2-f0eb-54a4-a93c-effa8508dfba', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 11, 11, 'and Nahshon became the father of Salma, and Salma became the father of Boaz,'),
  ('0d29efc7-1552-5da0-a8c4-66166449e309', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 12, 12, 'and Boaz became the father of Obed, and Obed became the father of Jesse;'),
  ('f1ee944d-0e3f-5cf6-a272-f7ca7f74011c', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 13, 13, 'and Jesse became the father of his firstborn Eliab, and Abinadab the second, and Shimea the third,'),
  ('120c0520-b004-5089-ab72-3ba7658e905b', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 14, 14, 'Nethanel the fourth, Raddai the fifth,'),
  ('2238a198-f816-5937-a448-b6efc691cce2', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 15, 15, 'Ozem the sixth, David the seventh;'),
  ('e7cde2e1-35e3-5c77-a6db-ff60687dbc78', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 16, 16, 'and their sisters were Zeruiah and Abigail. The sons of Zeruiah: Abishai, and Joab, and Asahel, three.'),
  ('9be501bf-334f-54b6-aae4-fac6c68181d1', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 17, 17, 'Abigail bore Amasa; and the father of Amasa was Jether the Ishmaelite.'),
  ('f695c2bf-a139-5f80-aa70-d38a037d5e41', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 18, 18, 'Caleb the son of Hezron became the father of [children] of Azubah [his] wife, and of Jerioth; and these were her sons: Jesher, and Shobab, and Ardon.'),
  ('2a7ec6cc-dd1c-507b-aaee-848cf67f5bee', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 19, 19, 'Azubah died, and Caleb took to him Ephrath, who bore him Hur.'),
  ('8ffb4fbb-2edd-59d4-addd-5ed5c4109d68', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 20, 20, 'Hur became the father of Uri, and Uri became the father of Bezalel.'),
  ('b65e1385-9809-50e9-ab98-8188ca5d18a1', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 21, 21, 'Afterward Hezron went in to the daughter of Machir the father of Gilead, whom he took [as wife] when he was sixty years old; and she bore him Segub.'),
  ('502d51cf-3315-520e-a94f-7f563e02e033', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 22, 22, 'Segub became the father of Jair, who had twenty-three cities in the land of Gilead.'),
  ('19c86b8c-a0bf-50a8-a3d7-2911a33e328c', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 23, 23, 'Geshur and Aram took the towns of Jair from them, with Kenath, and its villages, even sixty cities. All these were the sons of Machir the father of Gilead.'),
  ('19253c7f-29e0-5160-aabf-5e43fb86ea3f', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 24, 24, 'After that Hezron was dead in Caleb Ephrathah, then Abijah Hezron''s wife bore him Ashhur the father of Tekoa.'),
  ('9b850243-5b87-50ec-a32c-f4c2d26370a7', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 25, 25, 'The sons of Jerahmeel the firstborn of Hezron were Ram the firstborn, and Bunah, and Oren, and Ozem, Ahijah.'),
  ('f34c22ee-3362-5228-a429-67f177dd6839', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 26, 26, 'Jerahmeel had another wife, whose name was Atarah; she was the mother of Onam.'),
  ('a8c62daf-b0e7-5397-a320-379423505c8d', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 27, 27, 'The sons of Ram the firstborn of Jerahmeel were Maaz, and Jamin, and Eker.'),
  ('6e8593e2-1cbe-5e10-aeb9-f82e9365675a', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 28, 28, 'The sons of Onam were Shammai, and Jada. The sons of Shammai: Nadab, and Abishur.'),
  ('7426f9e9-3b30-51e0-a6ae-727f8ec25d30', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 29, 29, 'The name of the wife of Abishur was Abihail; and she bore him Ahban, and Molid.'),
  ('510dfdb6-82e3-50a8-a3da-5f7a4e7d733f', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 30, 30, 'The sons of Nadab: Seled, and Appaim; but Seled died without children.'),
  ('09e2476e-1f5f-58ac-a9bf-787070cfdeda', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 31, 31, 'The sons of Appaim: Ishi. The sons of Ishi: Sheshan. The sons of Sheshan: Ahlai.'),
  ('9b85c722-bf37-51e6-a0f0-3c351ed4438a', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 32, 32, 'The sons of Jada the brother of Shammai: Jether, and Jonathan; and Jether died without children.'),
  ('53eb44da-ac8b-575f-aa11-0380511584f8', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 33, 33, 'The sons of Jonathan: Peleth, and Zaza. These were the sons of Jerahmeel.'),
  ('52766ec2-691a-5764-aae3-511f16cee6da', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 34, 34, 'Now Sheshan had no sons, but daughters. Sheshan had a servant, an Egyptian, whose name was Jarha.'),
  ('25c1f113-50dc-5918-aaf9-f83f018716fb', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 35, 35, 'Sheshan gave his daughter to Jarha his servant as wife; and she bore him Attai.'),
  ('e959a8f3-41ca-5614-a691-d1e2a2e75788', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 36, 36, 'Attai became the father of Nathan, and Nathan became the father of Zabad,'),
  ('aeaaec56-2ad6-5b7a-a898-54f0934fd274', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 37, 37, 'and Zabad became the father of Ephlal, and Ephlal became the father of Obed,'),
  ('ef6dd7da-4632-594e-acb7-f93414c3e5f3', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 38, 38, 'and Obed became the father of Jehu, and Jehu became the father of Azariah,'),
  ('1608d2e3-e707-56a5-af8b-a647dc5aeb6c', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 39, 39, 'and Azariah became the father of Helez, and Helez became the father of Eleasah,'),
  ('0de1b37f-44c1-5da5-adfb-98bdf4a5dada', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 40, 40, 'and Eleasah became the father of Sismai, and Sismai became the father of Shallum,'),
  ('ffd1c776-c8e1-59ec-a243-b989ea1e895c', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 41, 41, 'and Shallum became the father of Jekamiah, and Jekamiah became the father of Elishama.'),
  ('0698ab6b-5c63-51dd-a314-a1f2b60b0ba2', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 42, 42, 'The sons of Caleb the brother of Jerahmeel were Mesha his firstborn, who was the father of Ziph; and the sons of Mareshah the father of Hebron.'),
  ('913cae51-67de-59ca-a597-40dceb70e350', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 43, 43, 'The sons of Hebron: Korah, and Tappuah, and Rekem, and Shema.'),
  ('f01c2a88-b69b-5fc4-a4a5-1848a31ea8fb', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 44, 44, 'Shema became the father of Raham, the father of Jorkeam; and Rekem became the father of Shammai.'),
  ('5b0fc488-79e8-5129-a6a6-4e6ba859d053', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 45, 45, 'The son of Shammai was Maon; and Maon was the father of Beth Zur.'),
  ('b3e76e1f-49b1-590d-a4ec-987d846b8861', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 46, 46, 'Ephah, Caleb''s concubine, bore Haran, and Moza, and Gazez; and Haran became the father of Gazez.'),
  ('a93fac45-17f1-5aad-a91c-dabc3c0b4ddf', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 47, 47, 'The sons of Jahdai: Regem, and Jothan, and Geshan, and Pelet, and Ephah, and Shaaph.'),
  ('ed6ef371-b2cd-5870-a240-c4b8e1f99171', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 48, 48, 'Maacah, Caleb''s concubine, bore Sheber and Tirhanah.'),
  ('f68bad41-e28e-5b39-a613-8fcb2c857da7', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 49, 49, 'She bore also Shaaph the father of Madmannah, Sheva the father of Machbena, and the father of Gibea; and the daughter of Caleb was Achsah.'),
  ('eda5f282-c26c-572e-ac22-913d05d2bbd9', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 50, 50, 'These were the sons of Caleb, the son of Hur, the firstborn of Ephrathah: Shobal the father of Kiriath Jearim,'),
  ('8595bfab-bbb4-5ebe-a18a-cee263bbf81a', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 51, 51, 'Salma the father of Bethlehem, Hareph the father of Beth Gader.'),
  ('51b4101d-dfb3-5580-a5a4-c0600d1de159', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 52, 52, 'Shobal the father of Kiriath Jearim had sons: Haroeh, half of the Menuhoth.'),
  ('7c0493dc-1e66-51d3-a735-7e8feb8d23f8', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 53, 53, 'The families of Kiriath Jearim: The Ithrites, and the Puthites, and the Shumathites, and the Mishraites; of them came the Zorathites and the Eshtaolites.'),
  ('0ef6e3d8-2bd9-50dd-a870-1262a5d86e40', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 54, 54, 'The sons of Salma: Bethlehem, and the Netophathites, Atroth Beth Joab, and half of the Manahathites, the Zorites.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('a94a2a89-c0fd-5366-adef-bbe2d84fc0a1', 'e6b13e3c-8d1c-5906-a168-506a5c615e0b', NULL, 55, 55, 'The families of scribes who lived at Jabez: the Tirathites, the Shimeathites, the Sucathites. These are the Kenites who came of Hammath, the father of the house of Rechab.'),
  ('656c44a9-7218-50ca-acd5-d9635ceb47c2', '5a0c7e8d-120b-5c51-a5bf-df1bc145fc41', NULL, 1, 1, 'Now these were the sons of David, who were born to him in Hebron: the firstborn, Amnon, of Ahinoam the Jezreelitess; the second, Daniel, of Abigail the Carmelitess;'),
  ('8f5df04f-500a-5b9a-a67f-aa4adbe2882c', '5a0c7e8d-120b-5c51-a5bf-df1bc145fc41', NULL, 2, 2, 'the third, Absalom the son of Maacah the daughter of Talmai king of Geshur; the fourth, Adonijah the son of Haggith;'),
  ('8e55ef03-4676-5c35-aed3-54afc9f268b2', '5a0c7e8d-120b-5c51-a5bf-df1bc145fc41', NULL, 3, 3, 'the fifth, Shephatiah of Abital; the sixth, Ithream by Eglah his wife:'),
  ('842368b3-48e0-5f7c-a46b-0232ac1fac14', '5a0c7e8d-120b-5c51-a5bf-df1bc145fc41', NULL, 4, 4, 'six were born to him in Hebron; and there he reigned seven years and six months. In Jerusalem he reigned thirty-three years;'),
  ('74cce676-f39a-5f2e-a817-5df69296cf4e', '5a0c7e8d-120b-5c51-a5bf-df1bc145fc41', NULL, 5, 5, 'and these were born to him in Jerusalem: Shimea, and Shobab, and Nathan, and Solomon, four, of Bathshua the daughter of Ammiel;'),
  ('abc6a297-a700-5146-ad72-12cb71b7ce63', '5a0c7e8d-120b-5c51-a5bf-df1bc145fc41', NULL, 6, 6, 'and Ibhar, and Elishama, and Eliphelet,'),
  ('896fff5e-2566-5e04-a79d-8c5ed70caee5', '5a0c7e8d-120b-5c51-a5bf-df1bc145fc41', NULL, 7, 7, 'and Nogah, and Nepheg, and Japhia,'),
  ('1f479145-1613-5c53-a7f7-2f425538e932', '5a0c7e8d-120b-5c51-a5bf-df1bc145fc41', NULL, 8, 8, 'and Elishama, and Eliada, and Eliphelet, nine.'),
  ('30ac5a21-a897-5719-a978-b88dd4537181', '5a0c7e8d-120b-5c51-a5bf-df1bc145fc41', NULL, 9, 9, 'All these were the sons of David, besides the sons of the concubines; and Tamar was their sister.'),
  ('acbaccda-7ecc-5111-a3a2-31e983fcd1aa', '5a0c7e8d-120b-5c51-a5bf-df1bc145fc41', NULL, 10, 10, 'Solomon''s son was Rehoboam, Abijah his son, Asa his son, Jehoshaphat his son,'),
  ('7d158928-e180-5cc8-a065-c0cf46457fd3', '5a0c7e8d-120b-5c51-a5bf-df1bc145fc41', NULL, 11, 11, 'Joram his son, Ahaziah his son, Joash his son,'),
  ('5962fb92-0bfa-5cda-a436-dd6c637a5051', '5a0c7e8d-120b-5c51-a5bf-df1bc145fc41', NULL, 12, 12, 'Amaziah his son, Azariah his son, Jotham his son,'),
  ('6fa4a576-5050-5889-a275-cbbe9ba609d7', '5a0c7e8d-120b-5c51-a5bf-df1bc145fc41', NULL, 13, 13, 'Ahaz his son, Hezekiah his son, Manasseh his son,'),
  ('aec82436-41b2-50d3-aa01-b276d74ac7e6', '5a0c7e8d-120b-5c51-a5bf-df1bc145fc41', NULL, 14, 14, 'Amon his son, Josiah his son.'),
  ('2015948c-14cd-5f32-a38d-6de7f81064f5', '5a0c7e8d-120b-5c51-a5bf-df1bc145fc41', NULL, 15, 15, 'The sons of Josiah: the firstborn Johanan, the second Jehoiakim, the third Zedekiah, the fourth Shallum.'),
  ('a963e2d4-c42d-581c-a737-8776f5a66add', '5a0c7e8d-120b-5c51-a5bf-df1bc145fc41', NULL, 16, 16, 'The sons of Jehoiakim: Jeconiah his son, Zedekiah his son.'),
  ('5970e7a5-86bf-5385-a1b3-a9e4d3410027', '5a0c7e8d-120b-5c51-a5bf-df1bc145fc41', NULL, 17, 17, 'The sons of Jeconiah, the captive: Shealtiel his son,'),
  ('56b81c16-8aba-5c95-a29d-d70871f72208', '5a0c7e8d-120b-5c51-a5bf-df1bc145fc41', NULL, 18, 18, 'and Malchiram, and Pedaiah, and Shenazzar, Jekamiah, Hoshama, and Nedabiah.'),
  ('95df41c2-e509-5e93-af3f-b3e1bd22c3f8', '5a0c7e8d-120b-5c51-a5bf-df1bc145fc41', NULL, 19, 19, 'The sons of Pedaiah: Zerubbabel, and Shimei. The sons of Zerubbabel: Meshullam, and Hananiah; and Shelomith was their sister;'),
  ('875710d5-0865-5b1d-a1c3-7f7ab259c27a', '5a0c7e8d-120b-5c51-a5bf-df1bc145fc41', NULL, 20, 20, 'and Hashubah, and Ohel, and Berechiah, and Hasadiah, Jushab Hesed, five.'),
  ('277cd3de-ab54-595b-a695-0512fd59e794', '5a0c7e8d-120b-5c51-a5bf-df1bc145fc41', NULL, 21, 21, 'The sons of Hananiah: Pelatiah, and Jeshaiah; the sons of Rephaiah, the sons of Arnan, the sons of Obadiah, the sons of Shecaniah.'),
  ('c8876c6b-2d5e-515e-a7e3-c370202066ce', '5a0c7e8d-120b-5c51-a5bf-df1bc145fc41', NULL, 22, 22, 'The sons of Shecaniah: Shemaiah. The sons of Shemaiah: Hattush, and Igal, and Bariah, and Neariah, and Shaphat, six.'),
  ('66410458-bfa0-5edd-a8ae-443377efa6c2', '5a0c7e8d-120b-5c51-a5bf-df1bc145fc41', NULL, 23, 23, 'The sons of Neariah: Elioenai, and Hizkiah, and Azrikam, three.'),
  ('9748ba35-62c7-515d-aa60-ce406762278c', '5a0c7e8d-120b-5c51-a5bf-df1bc145fc41', NULL, 24, 24, 'The sons of Elioenai: Hodaviah, and Eliashib, and Pelaiah, and Akkub, and Johanan, and Delaiah, and Anani, seven.'),
  ('152cd125-d43a-5b44-a04a-1b50f5f1f674', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 1, 1, 'The sons of Judah: Perez, Hezron, and Carmi, and Hur, and Shobal.'),
  ('1d4773d9-11be-5467-a521-9a1ee556cdb2', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 2, 2, 'Reaiah the son of Shobal became the father of Jahath; and Jahath became the father of Ahumai and Lahad. These are the families of the Zorathites.'),
  ('d0212d35-2d87-57d9-a81e-7d38c67763fd', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 3, 3, 'These were [the sons of] the father of Etam: Jezreel, and Ishma, and Idbash; and the name of their sister was Hazzelelponi;'),
  ('8cfbf3d1-b348-53e3-a024-455a9a86e462', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 4, 4, 'and Penuel the father of Gedor, and Ezer the father of Hushah. These are the sons of Hur, the firstborn of Ephrathah, the father of Bethlehem.'),
  ('23d03705-20b2-56e1-abc1-cd5c676944e9', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 5, 5, 'Ashhur the father of Tekoa had two wives, Helah and Naarah.'),
  ('2d1fa4d7-a396-56c6-a59c-274192cc516b', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 6, 6, 'Naarah bore him Ahuzzam, and Hepher, and Temeni, and Haahashtari. These were the sons of Naarah.'),
  ('10783c9e-b868-5e52-a6c1-0430b65eff59', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 7, 7, 'The sons of Helah were Zereth, Izhar, and Ethnan.'),
  ('5ec2bf40-7bd7-5dbb-a505-a758f6ed05f4', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 8, 8, 'Hakkoz became the father of Anub, and Zobebah, and the families of Aharhel the son of Harum.'),
  ('1d205c44-3da2-5f54-a481-e6c7a00c7991', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 9, 9, 'Jabez was more honorable than his brothers: and his mother named him Jabez, saying, "Because I bore him with sorrow."'),
  ('d1ec732b-e535-5ce9-a873-ae6bb77b3798', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 10, 10, 'Jabez called on the God of Israel, saying, "Oh that you would bless me indeed, and enlarge my border, and that your hand might be with me, and that you would keep me from evil, that it not be to my sorrow!" God granted him that which he requested.'),
  ('c099a869-afef-5862-aa63-5f7cb5bafb8c', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 11, 11, 'Chelub the brother of Shuhah became the father of Mehir, who was the father of Eshton.'),
  ('3306fd23-dade-5f3b-aec2-2fe9510b5f5d', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 12, 12, 'Eshton became the father of Beth Rapha, and Paseah, and Tehinnah the father of Ir Nahash. These are the men of Recah.'),
  ('2ff2a2d3-87b2-58fa-a3a2-2c6b18b43487', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 13, 13, 'The sons of Kenaz: Othniel, and Seraiah. The sons of Othniel: Hathath.'),
  ('0c4430d2-72c1-5e8a-a4f3-4b26671c9f99', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 14, 14, 'Meonothai became the father of Ophrah: and Seraiah became the father of Joab the father of Ge Harashim; for they were craftsmen.'),
  ('a2a10d4b-bcfa-5c0a-ae6e-a1a8f044acd1', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 15, 15, 'The sons of Caleb the son of Jephunneh: Iru, Elah, and Naam; and the sons of Elah; and Kenaz.'),
  ('10f8987e-f770-5ff2-aa4b-69a567240cb4', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 16, 16, 'The sons of Jehallelel: Ziph, and Ziphah, Tiria, and Asarel.'),
  ('6d3bb6bf-01e2-5852-af6a-ca77cb45b7c8', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 17, 17, 'The sons of Ezrah: Jether, and Mered, and Epher, and Jalon; and she bore Miriam, and Shammai, and Ishbah the father of Eshtemoa.'),
  ('98a6b554-da50-5f97-ae84-b5acd5cfe7df', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 18, 18, 'His wife the Jewess bore Jered the father of Gedor, and Heber the father of Soco, and Jekuthiel the father of Zanoah. These are the sons of Bithiah the daughter of Pharaoh, whom Mered took.'),
  ('52cde8e7-c7d2-5b8f-ad35-beb631950933', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 19, 19, 'The sons of the wife of Hodiah, the sister of Naham, were the father of Keilah the Garmite, and Eshtemoa the Maacathite.'),
  ('a819219d-5319-5206-a4c2-c37895935208', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 20, 20, 'The sons of Shimon: Amnon, and Rinnah, Ben Hanan, and Tilon. The sons of Ishi: Zoheth, and Ben Zoheth.'),
  ('bc8905f2-483e-5e1b-a096-8b3f317ae9ae', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 21, 21, 'The sons of Shelah the son of Judah: Er the father of Lecah, and Laadah the father of Mareshah, and the families of the house of those who worked fine linen, of the house of Ashbea;'),
  ('05354b50-1f1e-5c8c-a61f-110bc6a2deee', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 22, 22, 'and Jokim, and the men of Cozeba, and Joash, and Saraph, who had dominion in Moab, and Jashubilehem. The records are ancient.'),
  ('d12017b8-4bce-5d63-ae92-0289896ae95c', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 23, 23, 'These were the potters, and the inhabitants of Netaim and Gederah: there they lived with the king for his work.'),
  ('c5be280e-10d6-5f6e-ad93-b7c49ea366fb', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 24, 24, 'The sons of Simeon: Nemuel, and Jamin, Jarib, Zerah, Shaul;'),
  ('baa69e07-d2dd-588a-a970-d6ea1323e6ff', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 25, 25, 'Shallum his son, Mibsam his son, Mishma his son.'),
  ('b53017ca-976a-5a6f-a32d-462cc807aca5', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 26, 26, 'The sons of Mishma: Hammuel his son, Zaccur his son, Shimei his son.'),
  ('0967b4bb-148d-5b4a-a5a1-39a951b61c5c', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 27, 27, 'Shimei had sixteen sons and six daughters; but his brothers didn''t have many children, neither did all their family multiply like the children of Judah.'),
  ('637f6f50-e1a2-5a63-a071-2152bbb17816', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 28, 28, 'They lived at Beersheba, and Moladah, and Hazarshual,'),
  ('52a46fa4-65ab-5bff-a502-0480f0a73340', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 29, 29, 'and at Bilhah, and at Ezem, and at Tolad,'),
  ('c7e6cc51-e7a4-5b28-a4c5-a8a56387b4b7', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 30, 30, 'and at Bethuel, and at Hormah, and at Ziklag,'),
  ('6f160ef4-0362-561a-ad0f-7738f11b043f', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 31, 31, 'and at Beth Marcaboth, and Hazar Susim, and at Beth Biri, and at Shaaraim. These were their cities to the reign of David.'),
  ('1f891810-6ff6-54f2-a6f6-c2ff5d8138eb', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 32, 32, 'Their villages were Etam, and Ain, Rimmon, and Tochen, and Ashan, five cities;'),
  ('f694e23c-38a3-5767-acf8-c3616d2538a5', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 33, 33, 'and all their villages that were around the same cities, to Baal. These were their habitations, and they have their genealogy.'),
  ('99cd8e32-7645-5da2-a6fc-017f5fdbfc20', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 34, 34, 'Meshobab, and Jamlech, and Joshah the son of Amaziah,'),
  ('1082ba58-f0e2-56cc-a51b-cb5822c4c974', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 35, 35, 'and Joel, and Jehu the son of Joshibiah, the son of Seraiah, the son of Asiel,'),
  ('4a584954-8e24-56c2-ad31-df65c56ea8be', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 36, 36, 'and Elioenai, and Jaakobah, and Jeshohaiah, and Asaiah, and Adiel, and Jesimiel, and Benaiah,'),
  ('c91b2085-285a-5d39-a24f-10ab2b814b3e', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 37, 37, 'and Ziza the son of Shiphi, the son of Allon, the son of Jedaiah, the son of Shimri, the son of Shemaiah--'),
  ('016e7fc1-17f0-51a3-a801-347d8d838b0f', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 38, 38, 'these mentioned by name were princes in their families: and their fathers'' houses increased greatly.'),
  ('b474461e-6dc4-590b-ac64-b608b8118916', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 39, 39, 'They went to the entrance of Gedor, even to the east side of the valley, to seek pasture for their flocks.'),
  ('6164a323-34c4-5c37-ae3e-940dda02d8b2', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 40, 40, 'They found fat pasture and good, and the land was wide, and quiet, and peaceable; for those who lived there before were of Ham.'),
  ('d8b9b83f-94c6-52cb-a281-b053e3b51aaf', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 41, 41, 'These written by name came in the days of Hezekiah king of Judah, and struck their tents, and the Meunim who were found there, and destroyed them utterly to this day, and lived in their place; because there was pasture there for their flocks.'),
  ('8b1c658b-f953-52a0-a45f-7f672942c8c8', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 42, 42, 'Some of them, even of the sons of Simeon, five hundred men, went to Mount Seir, having for their captains Pelatiah, and Neariah, and Rephaiah, and Uzziel, the sons of Ishi.'),
  ('ac142791-280c-5411-a6df-2ac49732f9b7', 'f74d690b-a2bb-54c1-a483-1f3b65670de7', NULL, 43, 43, 'They struck the remnant of the Amalekites who escaped, and have lived there to this day.'),
  ('6418a1af-f85a-5e24-ac4c-c299e88a0c7e', '2c83675b-dfab-5bb4-ab44-5ebf37cfd44e', NULL, 1, 1, 'The sons of Reuben the firstborn of Israel (for he was the firstborn; but, because he defiled his father''s couch, his birthright was given to the sons of Joseph the son of Israel; and the genealogy is not to be reckoned after the birthright.'),
  ('53bbe0fa-2a47-503f-aa57-83f24a9f3092', '2c83675b-dfab-5bb4-ab44-5ebf37cfd44e', NULL, 2, 2, 'For Judah prevailed above his brothers, and of him came the prince; but the birthright was Joseph''s:)'),
  ('d0126e11-2d2a-5156-a08b-7d0bb338830d', '2c83675b-dfab-5bb4-ab44-5ebf37cfd44e', NULL, 3, 3, 'the sons of Reuben the firstborn of Israel: Hanoch, and Pallu, Hezron, and Carmi.'),
  ('0ad2edbd-8b56-5f74-aaa1-be1ee20d48b3', '2c83675b-dfab-5bb4-ab44-5ebf37cfd44e', NULL, 4, 4, 'The sons of Joel: Shemaiah his son, Gog his son, Shimei his son,'),
  ('fce1a4f9-0645-52b9-aa7f-5b36c97d8139', '2c83675b-dfab-5bb4-ab44-5ebf37cfd44e', NULL, 5, 5, 'Micah his son, Reaiah his son, Baal his son,'),
  ('2d9d1792-f5b9-5de4-a8cc-7a3c0726cae0', '2c83675b-dfab-5bb4-ab44-5ebf37cfd44e', NULL, 6, 6, 'Beerah his son, whom Tilgath Pilneser king of Assyria carried away captive: he was prince of the Reubenites.'),
  ('b2452bdc-8e66-5ee9-a6f1-b9adee1cf461', '2c83675b-dfab-5bb4-ab44-5ebf37cfd44e', NULL, 7, 7, 'His brothers by their families, when the genealogy of their generations was reckoned: the chief, Jeiel, and Zechariah,'),
  ('9275fcec-1140-5716-a167-5c3f87710e45', '2c83675b-dfab-5bb4-ab44-5ebf37cfd44e', NULL, 8, 8, 'and Bela the son of Azaz, the son of Shema, the son of Joel, who lived in Aroer, even to Nebo and Baal Meon:'),
  ('49cbbf82-4fcc-5d6b-a37d-9eb247e2ac64', '2c83675b-dfab-5bb4-ab44-5ebf37cfd44e', NULL, 9, 9, 'and eastward he lived even to the entrance of the wilderness from the river Euphrates, because their livestock were multiplied in the land of Gilead.'),
  ('8481bdfa-a0fb-58a3-aa5f-b14aabc49095', '2c83675b-dfab-5bb4-ab44-5ebf37cfd44e', NULL, 10, 10, 'In the days of Saul, they made war with the Hagrites, who fell by their hand; and they lived in their tents throughout all the [land] east of Gilead.'),
  ('bb10ccd9-229b-5200-a8e4-d2c5e7cbc658', '2c83675b-dfab-5bb4-ab44-5ebf37cfd44e', NULL, 11, 11, 'The sons of Gad lived over against them, in the land of Bashan to Salecah:'),
  ('e20776b5-7dc9-5d91-a846-ea1e13c9df3b', '2c83675b-dfab-5bb4-ab44-5ebf37cfd44e', NULL, 12, 12, 'Joel the chief, and Shapham the second, and Janai, and Shaphat in Bashan.'),
  ('520d96df-0a2c-5fdf-acb2-3b4df2299e49', '2c83675b-dfab-5bb4-ab44-5ebf37cfd44e', NULL, 13, 13, 'Their brothers of their fathers'' houses: Michael, and Meshullam, and Sheba, and Jorai, and Jacan, and Zia, and Eber, seven.'),
  ('51099246-8054-5fe7-aaa1-62ff9092b197', '2c83675b-dfab-5bb4-ab44-5ebf37cfd44e', NULL, 14, 14, 'These were the sons of Abihail, the son of Huri, the son of Jaroah, the son of Gilead, the son of Michael, the son of Jeshishai, the son of Jahdo, the son of Buz;'),
  ('508f1c6b-1890-55f8-ab00-1f897b0ced0b', '2c83675b-dfab-5bb4-ab44-5ebf37cfd44e', NULL, 15, 15, 'Ahi the son of Abdiel, the son of Guni, chief of their fathers'' houses.'),
  ('e5e17281-a535-581e-a6df-80dabbd33792', '2c83675b-dfab-5bb4-ab44-5ebf37cfd44e', NULL, 16, 16, 'They lived in Gilead in Bashan, and in its towns, and in all the suburbs of Sharon, as far as their borders.'),
  ('1421887e-90a8-5e02-ac91-c2acfa399fc5', '2c83675b-dfab-5bb4-ab44-5ebf37cfd44e', NULL, 17, 17, 'All these were reckoned by genealogies in the days of Jotham king of Judah, and in the days of Jeroboam king of Israel.'),
  ('4482b836-ba64-5162-a108-e5ccf7835ce9', '2c83675b-dfab-5bb4-ab44-5ebf37cfd44e', NULL, 18, 18, 'The sons of Reuben, and the Gadites, and the half-tribe of Manasseh, of valiant men, men able to bear buckler and sword, and to shoot with bow, and skillful in war, were forty-four thousand seven hundred and sixty, that were able to go forth to war.'),
  ('1fa71c48-5815-5789-a91c-ba4c31a34d3b', '2c83675b-dfab-5bb4-ab44-5ebf37cfd44e', NULL, 19, 19, 'They made war with the Hagrites, with Jetur, and Naphish, and Nodab.'),
  ('30e751b1-35cf-53d7-a30c-cde2f416ac9a', '2c83675b-dfab-5bb4-ab44-5ebf37cfd44e', NULL, 20, 20, 'They were helped against them, and the Hagrites were delivered into their hand, and all who were with them; for they cried to God in the battle, and he was entreated of them, because they put their trust in him.'),
  ('4b65497f-e9f9-5437-a4d3-4314e8937404', '2c83675b-dfab-5bb4-ab44-5ebf37cfd44e', NULL, 21, 21, 'They took away their livestock; of their camels fifty thousand, and of sheep two hundred fifty thousand, and of donkeys two thousand, and of men one hundred thousand.'),
  ('9dbaf9f3-1938-5d24-a86a-cc0dc3af353d', '2c83675b-dfab-5bb4-ab44-5ebf37cfd44e', NULL, 22, 22, 'For there fell many slain, because the war was of God. They lived in their place until the captivity.'),
  ('b424a141-80f6-510e-a39b-4c37ff513420', '2c83675b-dfab-5bb4-ab44-5ebf37cfd44e', NULL, 23, 23, 'The children of the half-tribe of Manasseh lived in the land: they increased from Bashan to Baal Hermon and Senir and Mount Hermon.'),
  ('6472ab19-4333-5c73-a8e1-014483fa574d', '2c83675b-dfab-5bb4-ab44-5ebf37cfd44e', NULL, 24, 24, 'These were the heads of their fathers'' houses: even Epher, and Ishi, and Eliel, and Azriel, and Jeremiah, and Hodaviah, and Jahdiel, mighty men of valor, famous men, heads of their fathers'' houses.'),
  ('5f78e9f9-c67b-5211-a8cf-78e29c223609', '2c83675b-dfab-5bb4-ab44-5ebf37cfd44e', NULL, 25, 25, 'They trespassed against the God of their fathers, and played the prostitute after the gods of the peoples of the land, whom God destroyed before them.'),
  ('cdf70e8f-8911-5ed4-abca-7e596ebbe72d', '2c83675b-dfab-5bb4-ab44-5ebf37cfd44e', NULL, 26, 26, 'The God of Israel stirred up the spirit of Pul king of Assyria, and the spirit of Tilgath Pilneser king of Assyria, and he carried them away, even the Reubenites, and the Gadites, and the half-tribe of Manasseh, and brought them to Halah, and Habor, and Hara, and to the river of Gozan, to this day.'),
  ('95b19b64-9cf2-5bf4-adef-f508d3be3b76', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 1, 1, 'The sons of Levi: Gershon, Kohath, and Merari.'),
  ('d50e6bcf-cb75-5045-af11-fe4c25729c60', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 2, 2, 'The sons of Kohath: Amram, Izhar, and Hebron, and Uzziel.'),
  ('5ff9f7f5-cdde-5ef9-a699-705000ce34d8', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 3, 3, 'The children of Amram: Aaron, and Moses, and Miriam. The sons of Aaron: Nadab, and Abihu, Eleazar, and Ithamar.'),
  ('07da9c53-53ab-594e-a3b8-b17b89f317d3', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 4, 4, 'Eleazar became the father of Phinehas, Phinehas became the father of Abishua,'),
  ('c50a9bc1-b55e-52b5-a24f-de295d02a236', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 5, 5, 'and Abishua became the father of Bukki, and Bukki became the father of Uzzi,'),
  ('4d6438ec-e715-5db5-a161-a410622dcf38', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 6, 6, 'and Uzzi became the father of Zerahiah, and Zerahiah became the father of Meraioth,'),
  ('2ba01db4-bec9-52b6-ad7d-617831242976', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 7, 7, 'Meraioth became the father of Amariah, and Amariah became the father of Ahitub,'),
  ('e7480216-64ee-517e-a946-ce9f83f23727', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 8, 8, 'and Ahitub became the father of Zadok, and Zadok became the father of Ahimaaz,'),
  ('02714176-3b06-5c95-ac5a-1d29b80fc153', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 9, 9, 'and Ahimaaz became the father of Azariah, and Azariah became the father of Johanan,'),
  ('ba4e9750-16e6-56a0-a8c4-c87c5b71ccd1', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 10, 10, 'and Johanan became the father of Azariah, (he it is who executed the priest''s office in the house that Solomon built in Jerusalem),'),
  ('9c29e000-8fc9-5590-a2c6-26546759ad49', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 11, 11, 'and Azariah became the father of Amariah, and Amariah became the father of Ahitub,'),
  ('047b1ebc-f6e2-54a8-a442-1172e98aa5c2', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 12, 12, 'and Ahitub became the father of Zadok, and Zadok became the father of Shallum,'),
  ('a1f5a249-24c5-5f0d-a8b0-86cfcf3b539f', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 13, 13, 'and Shallum became the father of Hilkiah, and Hilkiah became the father of Azariah,'),
  ('988e003e-03ce-5d4f-a709-f31b98f96a13', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 14, 14, 'and Azariah became the father of Seraiah, and Seraiah became the father of Jehozadak;'),
  ('5b94e57c-1635-5482-a50b-9fe47a5f01b1', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 15, 15, 'Jehozadak went [into captivity], when Yahweh carried away Judah and Jerusalem by the hand of Nebuchadnezzar.'),
  ('eabf718f-68cf-57f8-afac-964fcf5d156d', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 16, 16, 'The sons of Levi: Gershom, Kohath, and Merari.'),
  ('8b814326-96e7-5c9e-afab-739ae1664b05', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 17, 17, 'These are the names of the sons of Gershom: Libni and Shimei.'),
  ('5ffd6c87-2d6e-564a-ae61-6fed6c5b8b35', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 18, 18, 'The sons of Kohath were Amram, and Izhar, and Hebron, and Uzziel.'),
  ('2c1d8c59-5fba-5cba-a584-020014f75d35', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 19, 19, 'The sons of Merari: Mahli and Mushi. These are the families of the Levites according to their fathers'' [houses].'),
  ('1122914d-16d7-5db9-a6ac-3ee93a3f7827', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 20, 20, 'Of Gershom: Libni his son, Jahath his son, Zimmah his son,'),
  ('89ad71a8-1361-5790-ac7a-dae21698efc4', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 21, 21, 'Joah his son, Iddo his son, Zerah his son, Jeatherai his son.'),
  ('3b4e0e31-e399-5ddc-aa90-0fb8d031ef1d', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 22, 22, 'The sons of Kohath: Amminadab his son, Korah his son, Assir his son,'),
  ('163e4c21-fb6a-5985-acec-b276e4df63d4', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 23, 23, 'Elkanah his son, and Ebiasaph his son, and Assir his son,'),
  ('1fb854ac-2ec0-53f8-a622-0fedd55c40ea', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 24, 24, 'Tahath his son, Uriel his son, Uzziah his son, and Shaul his son.'),
  ('4041df25-998a-5d90-ac71-91f1a9c6c663', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 25, 25, 'The sons of Elkanah: Amasai, and Ahimoth.'),
  ('cefba080-6570-57de-a3ef-94c236951b1c', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 26, 26, 'As for Elkanah, the sons of Elkanah: Zophai his son, and Nahath his son,'),
  ('3f5914fe-1f3c-5888-a867-284fd78e756c', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 27, 27, 'Eliab his son, Jeroham his son, Elkanah his son.'),
  ('8b17aef3-d7e7-58fb-a52f-61c4c0271eda', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 28, 28, 'The sons of Samuel: the firstborn [Joel], and the second Abijah.'),
  ('1f8e64cd-ad51-5014-a839-8d89ca99d49a', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 29, 29, 'The sons of Merari: Mahli, Libni his son, Shimei his son, Uzzah his son,'),
  ('7ad6f691-a9e8-52c6-aa3b-5682a587f671', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 30, 30, 'Shimea his son, Haggiah his son, Asaiah his son.'),
  ('57cc3874-aee3-566f-a4e1-60931d0a67b1', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 31, 31, 'These are they whom David set over the service of song in the house of Yahweh, after that the ark had rest.'),
  ('eb39b27c-fd6b-50c6-a0c2-e5a74d9412c9', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 32, 32, 'They ministered with song before the tabernacle of the Tent of Meeting, until Solomon had built the house of Yahweh in Jerusalem: and they waited on their office according to their order.'),
  ('ab83a778-d9d3-5f58-acb4-aab0c6a98dfd', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 33, 33, 'These are those who waited, and their sons. Of the sons of the Kohathites: Heman the singer, the son of Joel, the son of Samuel,'),
  ('666f957b-ccb7-5409-aded-b359ddb5f933', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 34, 34, 'the son of Elkanah, the son of Jeroham, the son of Eliel, the son of Toah,'),
  ('7d805bb3-6955-5f22-a467-21e031f7fc78', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 35, 35, 'the son of Zuph, the son of Elkanah, the son of Mahath, the son of Amasai,'),
  ('7bb9cb1e-13af-5d64-a312-2864f50f68d0', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 36, 36, 'the son of Elkanah, the son of Joel, the son of Azariah, the son of Zephaniah,'),
  ('886be1e7-d447-5384-a0e7-7de74f551ec4', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 37, 37, 'the son of Tahath, the son of Assir, the son of Ebiasaph, the son of Korah,'),
  ('30a95d04-480d-5417-a2a7-6d176417c9c8', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 38, 38, 'the son of Izhar, the son of Kohath, the son of Levi, the son of Israel.'),
  ('0e9365a7-a8ef-5ea5-aa01-48e17019925a', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 39, 39, 'His brother Asaph, who stood on his right hand, even Asaph the son of Berechiah, the son of Shimea,'),
  ('3ae39e53-b5a0-5835-a104-dadf371dcd1c', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 40, 40, 'the son of Michael, the son of Baaseiah, the son of Malchijah,'),
  ('15da42f2-56c8-580d-a9dd-c6f956fa2710', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 41, 41, 'the son of Ethni, the son of Zerah, the son of Adaiah,'),
  ('529f5e3e-2bb2-5646-aca0-57ab6a6480a6', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 42, 42, 'the son of Ethan, the son of Zimmah, the son of Shimei,'),
  ('c75d052e-475f-55f3-a4c1-449fe3d467e3', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 43, 43, 'the son of Jahath, the son of Gershom, the son of Levi.'),
  ('f228c5f0-c11b-568c-ad49-f803601a2135', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 44, 44, 'On the left hand their brothers the sons of Merari: Ethan the son of Kishi, the son of Abdi, the son of Malluch,'),
  ('a136331e-c510-5ad4-ad7b-50a83f0655cf', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 45, 45, 'the son of Hashabiah, the son of Amaziah, the son of Hilkiah,'),
  ('ca92f408-aa5c-5e57-ab05-e195714d8506', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 46, 46, 'the son of Amzi, the son of Bani, the son of Shemer,'),
  ('3ae76139-b1c9-5718-a882-805e83007069', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 47, 47, 'the son of Mahli, the son of Mushi, the son of Merari, the son of Levi.'),
  ('9ba1306c-3ae8-55cd-a1d2-8a71cb5b926f', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 48, 48, 'Their brothers the Levites were appointed for all the service of the tabernacle of the house of God.'),
  ('ade1be5d-585d-52a6-a1a2-aae8580dbea8', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 49, 49, 'But Aaron and his sons offered on the altar of burnt offering, and on the altar of incense, for all the work of the most holy place, and to make atonement for Israel, according to all that Moses the servant of God had commanded.'),
  ('cf7c5c8b-8e86-5304-aeb1-5b9a9b2397c4', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 50, 50, 'These are the sons of Aaron: Eleazar his son, Phinehas his son, Abishua his son,'),
  ('23351f41-4bbb-5150-a5bc-709592806d0d', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 51, 51, 'Bukki his son, Uzzi his son, Zerahiah his son,'),
  ('60cdd405-17c2-51ea-a390-39bcc41c48b6', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 52, 52, 'Meraioth his son, Amariah his son, Ahitub his son,'),
  ('831e4891-40d7-5907-a77d-d2bbb56669a2', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 53, 53, 'Zadok his son, Ahimaaz his son.'),
  ('2895ee13-7d19-5462-a00d-5dc2a502bf80', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 54, 54, 'Now these are their dwelling places according to their encampments in their borders: to the sons of Aaron, of the families of the Kohathites (for theirs was the [first] lot),'),
  ('06c469ec-6ab7-5bdb-a04c-5baaae88776e', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 55, 55, 'to them they gave Hebron in the land of Judah, and its suburbs around it;'),
  ('3afd1a25-9d18-57dc-a2dd-9d7d8dd165b4', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 56, 56, 'but the fields of the city, and its villages, they gave to Caleb the son of Jephunneh.'),
  ('346c682b-dc7f-5e96-a352-774366f24715', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 57, 57, 'To the sons of Aaron they gave the cities of refuge, Hebron; Libnah also with its suburbs, and Jattir, and Eshtemoa with its suburbs,'),
  ('f6ce569f-62f6-5167-a5b8-63d1463939f0', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 58, 58, 'and Hilen with its suburbs, Debir with its suburbs,'),
  ('5ff863c4-133a-5000-ada0-8266ca259397', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 59, 59, 'and Ashan with its suburbs, and Beth Shemesh with its suburbs;'),
  ('83652d61-18a7-536d-a93f-cdd25390b29b', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 60, 60, 'and out of the tribe of Benjamin, Geba with its suburbs, and Allemeth with its suburbs, and Anathoth with its suburbs. All their cities throughout their families were thirteen cities.'),
  ('259e527e-7ed7-5855-a765-4d2eac935978', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 61, 61, 'To the rest of the sons of Kohath [were given] by lot, out of the family of the tribe, out of the half-tribe, the half of Manasseh, ten cities.'),
  ('b7f64d3d-e0dc-5259-a5b2-cc5a0fa8dc5a', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 62, 62, 'To the sons of Gershom, according to their families, out of the tribe of Issachar, and out of the tribe of Asher, and out of the tribe of Naphtali, and out of the tribe of Manasseh in Bashan, thirteen cities.'),
  ('f013da46-b08a-5d75-ab17-2fc21530c34b', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 63, 63, 'To the sons of Merari [were given] by lot, according to their families, out of the tribe of Reuben, and out of the tribe of Gad, and out of the tribe of Zebulun, twelve cities.'),
  ('a60138fe-ab1f-5a40-afee-8fd70998980a', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 64, 64, 'The children of Israel gave to the Levites the cities with their suburbs.'),
  ('c8783426-1dd1-5183-ab73-393f34a0d772', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 65, 65, 'They gave by lot out of the tribe of the children of Judah, and out of the tribe of the children of Simeon, and out of the tribe of the children of Benjamin, these cities which are mentioned by name.'),
  ('4a1298c8-32db-50d5-a9ca-71f4defe9eff', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 66, 66, 'Some of the families of the sons of Kohath had cities of their borders out of the tribe of Ephraim.'),
  ('9b8f59e2-e8e6-5a04-af88-eb54b4683459', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 67, 67, 'They gave to them the cities of refuge, Shechem in the hill country of Ephraim with its suburbs; Gezer also with its suburbs,'),
  ('7e813a50-e042-54ff-a3c2-d37cc97ff6b6', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 68, 68, 'and Jokmeam with its suburbs, and Beth Horon with its suburbs,'),
  ('2fd10cfc-9513-5fba-ac9e-78efaf25a29e', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 69, 69, 'and Aijalon with its suburbs, and Gath Rimmon with its suburbs;'),
  ('e759b167-8f3d-51e1-a5b4-6487b3e9d6b6', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 70, 70, 'and out of the half-tribe of Manasseh, Aner with its suburbs, and Bileam with its suburbs, for the rest of the family of the sons of Kohath.'),
  ('8e4999dc-528c-5793-a85a-9b8e5d85981b', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 71, 71, 'To the sons of Gershom [were given], out of the family of the half-tribe of Manasseh, Golan in Bashan with its suburbs, and Ashtaroth with its suburbs;'),
  ('35fa16f1-4e50-5716-a991-dcc93815ac6b', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 72, 72, 'and out of the tribe of Issachar, Kedesh with its suburbs, Daberath with its suburbs,'),
  ('309ec5f2-2f55-50ed-ab8c-7b994a954398', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 73, 73, 'and Ramoth with its suburbs, and Anem with its suburbs;'),
  ('3d352c22-0e53-5cbe-a892-921b1eb134a1', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 74, 74, 'and out of the tribe of Asher, Mashal with its suburbs, and Abdon with its suburbs,'),
  ('f4474de6-45fc-5e81-aa99-d08a06f2113a', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 75, 75, 'and Hukok with its suburbs, and Rehob with its suburbs;'),
  ('4271e0dd-2026-5f87-adfc-48090562e7f3', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 76, 76, 'and out of the tribe of Naphtali, Kedesh in Galilee with its suburbs, and Hammon with its suburbs, and Kiriathaim with its suburbs.'),
  ('3c198a23-3f55-528c-ab19-33e47ff403f1', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 77, 77, 'To the rest of [the Levites], the sons of Merari, [were given], out of the tribe of Zebulun, Rimmono with its suburbs, Tabor with its suburbs;'),
  ('8a6f1df8-c481-564e-aeed-a48d46683341', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 78, 78, 'and beyond the Jordan at Jericho, on the east side of the Jordan, [were given them], out of the tribe of Reuben, Bezer in the wilderness with its suburbs, and Jahzah with its suburbs,'),
  ('6d395fea-ac6b-5cfc-a6de-ec98d6a85b33', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 79, 79, 'and Kedemoth with its suburbs, and Mephaath with its suburbs;'),
  ('c2ab0bf7-c1b2-5b19-add7-50a7a455c8e4', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 80, 80, 'and out of the tribe of Gad, Ramoth in Gilead with its suburbs, and Mahanaim with its suburbs,'),
  ('d3a47a43-0740-5853-aca4-af078cac73b6', 'd6fcf34d-a8da-50fa-a98c-043dc43cd9dd', NULL, 81, 81, 'and Heshbon with its suburbs, and Jazer with its suburbs.'),
  ('6e7c6a81-116a-5f4a-a02d-3c01dd20db5c', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 1, 1, 'Of the sons of Issachar: Tola, and Puah, Jashub, and Shimron, four.'),
  ('bcbfb082-7c5b-523d-a957-cf46d3c9ac5f', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 2, 2, 'The sons of Tola: Uzzi, and Rephaiah, and Jeriel, and Jahmai, and Ibsam, and Shemuel, heads of their fathers'' houses, [to wit], of Tola; mighty men of valor in their generations: their number in the days of David was twenty-two thousand six hundred.'),
  ('68f2df0f-650e-505e-a0ab-dc243bff6f0d', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 3, 3, 'The sons of Uzzi: Izrahiah. The sons of Izrahiah: Michael, and Obadiah, and Joel, Isshiah, five; all of them chief men.'),
  ('7e5f7a60-b763-53c9-a24c-8ac668cb5b8b', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 4, 4, 'With them, by their generations, after their fathers'' houses, were bands of the army for war, thirty-six thousand; for they had many wives and sons.'),
  ('96be23e1-2a5b-5a97-a855-0e20a00ca8f8', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 5, 5, 'Their brothers among all the families of Issachar, mighty men of valor, reckoned in all by genealogy, were eighty-seven thousand.'),
  ('bdf49e19-390a-5ea5-a4e1-51102d0af18e', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 6, 6, '[The sons of] Benjamin: Bela, and Becher, and Jediael, three.'),
  ('19bc10d0-27b2-51f7-a0e8-15a3a9d1deb7', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 7, 7, 'The sons of Bela: Ezbon, and Uzzi, and Uzziel, and Jerimoth, and Iri, five; heads of fathers'' houses, mighty men of valor; and they were reckoned by genealogy twenty-two thousand thirty-four.'),
  ('b644f723-6d4d-5051-a363-36e3aa89012e', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 8, 8, 'The sons of Becher: Zemirah, and Joash, and Eliezer, and Elioenai, and Omri, and Jeremoth, and Abijah, and Anathoth, and Alemeth. All these were the sons of Becher.'),
  ('6d197dc3-ebe4-54ae-afc0-9081b7ccc946', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 9, 9, 'They were reckoned by genealogy, after their generations, heads of their fathers'' houses, mighty men of valor, twenty thousand two hundred.'),
  ('1b41c789-deb5-5274-a153-1d21133e6ea6', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 10, 10, 'The sons of Jediael: Bilhan. The sons of Bilhan: Jeush, and Benjamin, and Ehud, and Chenaanah, and Zethan, and Tarshish, and Ahishahar.'),
  ('051a0324-bc97-577d-a9f2-2848405c1059', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 11, 11, 'All these were sons of Jediael, according to the heads of their fathers'' [houses], mighty men of valor, seventeen thousand and two hundred, who were able to go forth in the army for war.'),
  ('cc0765c7-190d-5f7e-a76d-931452d3172a', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 12, 12, 'Shuppim also, and Huppim, the sons of Ir, Hushim, the sons of Aher.'),
  ('7f07eabc-9a82-535c-a402-574bdb387f51', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 13, 13, 'The sons of Naphtali: Jahziel, and Guni, and Jezer, and Shallum, the sons of Bilhah.'),
  ('d2533aca-a17b-5d2e-a2c5-1373212ced85', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 14, 14, 'The sons of Manasseh: Asriel, whom his concubine the Aramitess bore: she bore Machir the father of Gilead:'),
  ('7b185cff-c565-504c-a46f-6c1825f71446', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 15, 15, 'and Machir took a wife of Huppim and Shuppim, whose sister''s name was Maacah; and the name of the second was Zelophehad: and Zelophehad had daughters.'),
  ('1ff809e9-b310-51bc-a9dc-4382e1145493', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 16, 16, 'Maacah the wife of Machir bore a son, and she named him Peresh; and the name of his brother was Sheresh; and his sons were Ulam and Rakem.'),
  ('d92883bd-ff0c-5d14-a678-c2919f26e7f7', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 17, 17, 'The sons of Ulam: Bedan. These were the sons of Gilead the son of Machir, the son of Manasseh.'),
  ('e6634371-69d5-5de3-a464-a34abf229140', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 18, 18, 'His sister Hammolecheth bore Ishhod, and Abiezer, and Mahlah.'),
  ('2ae36963-f0a5-5983-a6c8-a9a1919ccd5f', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 19, 19, 'The sons of Shemida were Ahian, and Shechem, and Likhi, and Aniam.'),
  ('6f9c7639-c51e-5dd9-aba3-c492e563f4f5', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 20, 20, 'The sons of Ephraim: Shuthelah, and Bered his son, and Tahath his son, and Eleadah his son, and Tahath his son,'),
  ('5b3c925c-6741-5290-ac11-3fa913b0a1be', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 21, 21, 'and Zabad his son, and Shuthelah his son, and Ezer, and Elead, whom the men of Gath who were born in the land killed, because they came down to take away their livestock.'),
  ('5572e07f-b920-50bb-a216-48529ca795b4', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 22, 22, 'Ephraim their father mourned many days, and his brothers came to comfort him.'),
  ('b648d6b7-a1eb-5e97-a2f3-3cb74ad5b5c2', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 23, 23, 'He went in to his wife, and she conceived, and bore a son, and he named him Beriah, because it went evil with his house.'),
  ('a2fd47a5-6d54-5d12-a615-aec14d30c27f', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 24, 24, 'His daughter was Sheerah, who built Beth Horon the lower and the upper, and Uzzen Sheerah.'),
  ('972536da-8ba6-59f4-a0cf-2cca784329a8', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 25, 25, 'Rephah was his son, and Resheph, and Telah his son, and Tahan his son,'),
  ('b93ebadb-1d48-5811-a3ba-42a134d38ca6', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 26, 26, 'Ladan his son, Ammihud his son, Elishama his son,'),
  ('d7c8abc0-1fbf-52c2-aba6-728e78e675c0', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 27, 27, 'Nun his son, Joshua his son.'),
  ('a16b489b-4ea9-5007-a640-389a959323bd', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 28, 28, 'Their possessions and habitations were Bethel and its towns, and eastward Naaran, and westward Gezer, with its towns; Shechem also and its towns, to Azzah and its towns;'),
  ('9062a7cb-2cd0-529d-ad82-b8f27fd91c40', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 29, 29, 'and by the borders of the children of Manasseh, Beth Shean and its towns, Taanach and its towns, Megiddo and its towns, Dor and its towns. In these lived the children of Joseph the son of Israel.'),
  ('3eb10683-51ca-5fa0-ab35-ac30a68c4641', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 30, 30, 'The sons of Asher: Imnah, and Ishvah, and Ishvi, and Beriah, and Serah their sister.'),
  ('cf519451-4fb1-51ea-adac-514a9c500b86', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 31, 31, 'The sons of Beriah: Heber, and Malchiel, who was the father of Birzaith.'),
  ('3b74729b-37bb-5d00-a5b5-880464faa399', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 32, 32, 'Heber became the father of Japhlet, and Shomer, and Hotham, and Shua their sister.'),
  ('acadfa23-b325-5692-a207-b4f0a577fe36', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 33, 33, 'The sons of Japhlet: Pasach, and Bimhal, and Ashvath. These are the children of Japhlet.'),
  ('14381b81-991f-5a32-adfd-2fcee47f88bb', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 34, 34, 'The sons of Shemer: Ahi, and Rohgah, Jehubbah, and Aram.'),
  ('33ac50d7-88f0-5e28-a4a7-4a978428eee2', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 35, 35, 'The sons of Helem his brother: Zophah, and Imna, and Shelesh, and Amal.'),
  ('e781f701-8c03-5ed0-a74c-442e357d72ec', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 36, 36, 'The sons of Zophah: Suah, and Harnepher, and Shual, and Beri, and Imrah,'),
  ('4b02365f-af37-558e-a502-d48d6d9b23a5', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 37, 37, 'Bezer, and Hod, and Shamma, and Shilshah, and Ithran, and Beera.'),
  ('e79eddcd-b9f0-5e9a-a62e-e37e650d17ff', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 38, 38, 'The sons of Jether: Jephunneh, and Pispa, and Ara.'),
  ('e1645c5d-3064-5bb4-add7-bf65c8136ef9', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 39, 39, 'The sons of Ulla: Arah, and Hanniel, and Rizia.'),
  ('da5320cb-bb34-5237-a1f0-369f9dfb69bf', '964e220f-c501-5130-aa5d-b3a13d6fa885', NULL, 40, 40, 'All these were the children of Asher, heads of the fathers'' houses, choice and mighty men of valor, chief of the princes. The number of them reckoned by genealogy for service in war was twenty-six thousand men.'),
  ('7488c03a-657f-5670-a6ca-74760a621b75', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 1, 1, 'Benjamin became the father of Bela his firstborn, Ashbel the second, and Aharah the third,'),
  ('e0fff105-31ea-5bc8-a948-eee5b14f351d', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 2, 2, 'Nohah the fourth, and Rapha the fifth.'),
  ('53c05cab-74c0-5ef8-a105-5128ef66eb87', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 3, 3, 'Bela had sons: Addar, and Gera, and Abihud,'),
  ('98e468fa-fe8e-5673-a611-f5e2c83f4feb', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 4, 4, 'and Abishua, and Naaman, and Ahoah,'),
  ('f05a40ac-652b-5f21-aa05-50fc19e967cc', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 5, 5, 'and Gera, and Shephuphan, and Huram.'),
  ('9fa7dcf9-e1c3-5ad7-a8a3-846aaebfbe2a', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 6, 6, 'These are the sons of Ehud: these are the heads of fathers'' [houses] of the inhabitants of Geba, and they carried them captive to Manahath:'),
  ('adbbf5eb-5fc7-515e-aa6d-56ef316f95b6', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 7, 7, 'and Naaman, and Ahijah, and Gera, he carried them captive: and he became the father of Uzza and Ahihud.'),
  ('7a5951bb-0961-5fcb-a9af-2abab29ba0b6', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 8, 8, 'Shaharaim became the father of children in the field of Moab, after he had sent them away; Hushim and Baara were his wives.'),
  ('d8138dc8-186a-5f8f-ad56-33fd479b27f2', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 9, 9, 'He became the father of Hodesh his wife, Jobab, and Zibia, and Mesha, and Malcam,'),
  ('cda4731a-d318-51f1-a873-61d614095983', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 10, 10, 'and Jeuz, and Shachia, and Mirmah. These were his sons, heads of fathers'' [houses].'),
  ('caabaae0-ff4d-570a-a65f-05ec10d229c3', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 11, 11, 'Of Hushim he became the father of Abitub and Elpaal.'),
  ('f2e61086-df2f-5bb4-a30a-1332c922de3d', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 12, 12, 'The sons of Elpaal: Eber, and Misham, and Shemed, who built Ono and Lod, with its towns;'),
  ('1bf1ba81-1dbd-5e51-a9a3-0ef0f4a23336', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 13, 13, 'and Beriah, and Shema, who were heads of fathers'' [houses] of the inhabitants of Aijalon, who put to flight the inhabitants of Gath;'),
  ('4d455a2d-3b46-5b27-a0a4-72f79a926b7c', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 14, 14, 'and Ahio, Shashak, and Jeremoth,'),
  ('ad3a6adc-c04d-5079-a680-faf876e9e037', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 15, 15, 'and Zebadiah, and Arad, and Eder,'),
  ('e042df44-ba99-557f-ad0c-39ec717f194c', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 16, 16, 'and Michael, and Ishpah, and Joha, the sons of Beriah,'),
  ('fd456a4a-6026-5af1-a711-e023a50bc8d9', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 17, 17, 'and Zebadiah, and Meshullam, and Hizki, and Heber,'),
  ('2cfefec9-2bb7-5489-aff2-3f2ab6fb3d90', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 18, 18, 'and Ishmerai, and Izliah, and Jobab, the sons of Elpaal,'),
  ('318e0a41-478c-5454-a6a9-a8603b6dae3d', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 19, 19, 'and Jakim, and Zichri, and Zabdi,'),
  ('56f27f24-9218-56d2-a78c-820658a15197', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 20, 20, 'and Elienai, and Zillethai, and Eliel,'),
  ('5de8c227-e003-518e-ab8a-c660afdade06', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 21, 21, 'and Adaiah, and Beraiah, and Shimrath, the sons of Shimei,'),
  ('d70c58ed-12ae-5806-a70e-71c889e94c1b', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 22, 22, 'and Ishpan, and Eber, and Eliel,'),
  ('a58925ba-3574-5689-a09d-c8bb4f371811', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 23, 23, 'and Abdon, and Zichri, and Hanan,'),
  ('e32f1527-00aa-564b-aa11-b7cc7473ce0c', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 24, 24, 'and Hananiah, and Elam, and Anthothijah,'),
  ('186169ce-dd79-5e3f-a8b4-e5b64e509005', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 25, 25, 'and Iphdeiah, and Penuel, the sons of Shashak,'),
  ('6aa979e3-65ee-547f-a86e-af33b91ee6a9', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 26, 26, 'and Shamsherai, and Shehariah, and Athaliah,'),
  ('e65d8c14-241c-5977-ab8c-3059e1281ac1', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 27, 27, 'and Jaareshiah, and Elijah, and Zichri, the sons of Jeroham.'),
  ('154fe956-2530-5058-ab3e-093ef29b6b6d', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 28, 28, 'These were heads of fathers'' [houses] throughout their generations, chief men: these lived in Jerusalem.'),
  ('c6b0325b-6b60-5a66-ab7e-6ef47ccd8ce0', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 29, 29, 'In Gibeon there lived the father of Gibeon, [Jeiel], whose wife''s name was Maacah;'),
  ('3cd2e5bd-10eb-5f65-aab8-1c6ae5152ff6', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 30, 30, 'and his firstborn son Abdon, and Zur, and Kish, and Baal, and Nadab,'),
  ('4768e83b-2702-51c9-a361-4256c232a952', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 31, 31, 'and Gedor, and Ahio, and Zecher.'),
  ('f700286a-8b33-5edd-a4b5-12b7b41f3ffd', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 32, 32, 'Mikloth became the father of Shimeah. They also lived with their brothers in Jerusalem, over against their brothers.'),
  ('f374e7ee-7cfd-5e49-a19f-998b045a8356', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 33, 33, 'Ner became the father of Kish; and Kish became the father of Saul; and Saul became the father of Jonathan, and Malchishua, and Abinadab, and Eshbaal.'),
  ('1b5922d9-fe13-5e05-aae1-dc0d41e89b09', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 34, 34, 'The son of Jonathan was Merib Baal; and Merib Baal became the father of Micah.'),
  ('f45777c0-0917-524c-a3c3-2c9ed735cc44', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 35, 35, 'The sons of Micah: Pithon, and Melech, and Tarea, and Ahaz.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('7aa8aed6-c174-5113-aff1-6d74afaf5c43', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 36, 36, 'Ahaz became the father of Jehoaddah; and Jehoaddah became the father of Alemeth, and Azmaveth, and Zimri; and Zimri became the father of Moza.'),
  ('06f24993-dc91-592e-aa72-20220ce8938d', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 37, 37, 'Moza became the father of Binea; Raphah was his son, Eleasah his son, Azel his son.'),
  ('d781d662-9bcf-5559-a2c0-0e2b1d162068', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 38, 38, 'Azel had six sons, whose names are these: Azrikam, Bocheru, and Ishmael, and Sheariah, and Obadiah, and Hanan. All these were the sons of Azel.'),
  ('7d3b12e1-4927-56e2-aa9c-114c89b8262f', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 39, 39, 'The sons of Eshek his brother: Ulam his firstborn, Jeush the second, and Eliphelet the third.'),
  ('c2a51dbe-c278-5d0b-a9fb-0f19fdb84566', '59a25189-a300-556f-af52-4dcca4a8a922', NULL, 40, 40, 'The sons of Ulam were mighty men of valor, archers, and had many sons, and sons'' sons, one hundred fifty. All these were of the sons of Benjamin.'),
  ('dc2b908a-2f65-5c32-a6f8-2ee7eea13c48', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 1, 1, 'So all Israel were reckoned by genealogies; and behold, they are written in the book of the kings of Israel: and Judah was carried away captive to Babylon for their disobedience.'),
  ('a09f2b5b-834b-5430-aa79-f96802b7784d', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 2, 2, 'Now the first inhabitants who lived in their possessions in their cities were Israel, the priests, the Levites, and the Nethinim.'),
  ('d7eb8c78-53bd-5261-ac90-17130097a2f3', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 3, 3, 'In Jerusalem lived of the children of Judah, and of the children of Benjamin, and of the children of Ephraim and Manasseh:'),
  ('0001b063-79f9-5f4f-a7bb-6c8f7c8a4113', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 4, 4, 'Uthai the son of Ammihud, the son of Omri, the son of Imri, the son of Bani, of the children of Perez the son of Judah.'),
  ('bb72489a-1e5c-5045-a7b3-3a532d0776b4', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 5, 5, 'Of the Shilonites: Asaiah the firstborn, and his sons.'),
  ('403f5bf1-6d11-58cc-ae40-f025a05056ba', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 6, 6, 'Of the sons of Zerah: Jeuel, and their brothers, six hundred ninety.'),
  ('1697db29-24a2-5b1a-a7d6-af07bd82ab8a', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 7, 7, 'Of the sons of Benjamin: Sallu the son of Meshullam, the son of Hodaviah, the son of Hassenuah,'),
  ('69d9cac9-acb9-5171-a8dd-de435e7b8014', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 8, 8, 'and Ibneiah the son of Jeroham, and Elah the son of Uzzi, the son of Michri, and Meshullam the son of Shephatiah, the son of Reuel, the son of Ibnijah;'),
  ('0be105f4-b826-5a42-a501-bd05f03a4324', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 9, 9, 'and their brothers, according to their generations, nine hundred fifty-six. All these men were heads of fathers'' [houses] by their fathers'' houses.'),
  ('b800f62f-c871-5b6e-aa37-bad66973bcec', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 10, 10, 'Of the priests: Jedaiah, and Jehoiarib, Jachin,'),
  ('70b1140f-b844-5fee-a05f-3da3283f8800', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 11, 11, 'and Azariah the son of Hilkiah, the son of Meshullam, the son of Zadok, the son of Meraioth, the son of Ahitub, the ruler of the house of God;'),
  ('a65a132d-ac49-5357-a916-8b09ec2b3b82', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 12, 12, 'and Adaiah the son of Jeroham, the son of Pashhur, the son of Malchijah, and Maasai the son of Adiel, the son of Jahzerah, the son of Meshullam, the son of Meshillemith, the son of Immer;'),
  ('bb621301-312f-55cd-acb8-6fb9b6e5b5d5', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 13, 13, 'and their brothers, heads of their fathers'' houses, one thousand seven hundred sixty; very able men for the work of the service of the house of God.'),
  ('9fbff8fa-88db-53e1-ae31-432d607121c2', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 14, 14, 'Of the Levites: Shemaiah the son of Hasshub, the son of Azrikam, the son of Hashabiah, of the sons of Merari;'),
  ('75b10c78-3ef3-5e18-acdf-f1d993bf9790', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 15, 15, 'and Bakbakkar, Heresh, and Galal, and Mattaniah the son of Mica, the son of Zichri, the son of Asaph,'),
  ('9e02b81d-cb55-5578-aca1-dab4bbb5cb6d', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 16, 16, 'and Obadiah the son of Shemaiah, the son of Galal, the son of Jeduthun, and Berechiah the son of Asa, the son of Elkanah, who lived in the villages of the Netophathites.'),
  ('38eb8410-6eb1-51da-a059-4f63fb349868', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 17, 17, 'The porters: Shallum, and Akkub, and Talmon, and Ahiman, and their brothers (Shallum was the chief),'),
  ('92a52917-c01f-59a8-a3d8-9a76faef1856', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 18, 18, 'who hitherto [waited] in the king''s gate eastward: they were the porters for the camp of the children of Levi.'),
  ('b0bba069-810a-5447-a838-e7aa4367bc3b', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 19, 19, 'Shallum the son of Kore, the son of Ebiasaph, the son of Korah, and his brothers, of his father''s house, the Korahites, were over the work of the service, keepers of the thresholds of the tent: and their fathers had been over the camp of Yahweh, keepers of the entry.'),
  ('d41b6726-4acd-55b6-a5c8-261af3e05bb3', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 20, 20, 'Phinehas the son of Eleazar was ruler over them in time past, [and] Yahweh was with him.'),
  ('2fa9bf30-993b-5289-a334-474cea1abcee', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 21, 21, 'Zechariah the son of Meshelemiah was porter of the door of the Tent of Meeting.'),
  ('237f3db1-6b5b-5b5d-a726-5b876ffe52d2', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 22, 22, 'All these who were chosen to be porters in the thresholds were two hundred and twelve. These were reckoned by genealogy in their villages, whom David and Samuel the seer did ordain in their office of trust.'),
  ('c5379c9a-356c-5fa1-a0c8-b9447a4249c4', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 23, 23, 'So they and their children had the oversight of the gates of the house of Yahweh, even the house of the tent, by wards.'),
  ('f5451887-1c5e-5962-a2a7-a846dd13f3d8', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 24, 24, 'On the four sides were the porters, toward the east, west, north, and south.'),
  ('f4fd4c6b-6b44-5124-a536-466b6d899c77', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 25, 25, 'Their brothers, in their villages, were to come in every seven days from time to time to be with them:'),
  ('c18a93cb-3ba1-5f24-a41a-baf1a37eef52', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 26, 26, 'for the four chief porters, who were Levites, were in an office of trust, and were over the rooms and over the treasuries in the house of God.'),
  ('14ea3f5a-143c-5002-a795-51d16496a1f9', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 27, 27, 'They lodged around the house of God, because that duty was on them; and to them pertained its opening morning by morning.'),
  ('ba4d0d95-597c-5574-a053-c61bd0241185', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 28, 28, 'Certain of them were in charge of the vessels of service; for by count were these brought in and by count were these taken out.'),
  ('99eb5b3a-de23-5fff-a060-f2ef709e67c9', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 29, 29, 'Some of them also were appointed over the furniture, and over all the vessels of the sanctuary, and over the fine flour, and the wine, and the oil, and the frankincense, and the spices.'),
  ('7d9a2850-73f8-5ba9-aab8-0b126ef6b396', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 30, 30, 'Some of the sons of the priests prepared the confection of the spices.'),
  ('34dc602f-721e-598e-ab69-048101156be8', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 31, 31, 'Mattithiah, one of the Levites, who was the firstborn of Shallum the Korahite, had the office of trust over the things that were baked in pans.'),
  ('5d7438af-6b8a-59f8-aebf-a733997dfd40', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 32, 32, 'Some of their brothers, of the sons of the Kohathites, were over the show bread, to prepare it every Sabbath.'),
  ('9ec8e40d-9d8e-5b74-a9f0-16b018f1b1fe', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 33, 33, 'These are the singers, heads of fathers'' [houses] of the Levites, [who lived] in the rooms [and were] free [from other service]; for they were employed in their work day and night.'),
  ('3aa44052-5417-5d21-ad49-30bf922da167', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 34, 34, 'These were heads of fathers'' [houses] of the Levites, throughout their generations, chief men: these lived at Jerusalem.'),
  ('05203de6-4619-5647-adf4-371af6572729', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 35, 35, 'In Gibeon there lived the father of Gibeon, Jeiel, whose wife''s name was Maacah:'),
  ('161d6b4b-e6d2-54de-a6f7-0da3dae33c27', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 36, 36, 'and his firstborn son Abdon, and Zur, and Kish, and Baal, and Ner, and Nadab,'),
  ('18756649-60b7-5a0f-af03-6b5455f2a4d6', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 37, 37, 'and Gedor, and Ahio, and Zechariah, and Mikloth.'),
  ('b0795c6d-a425-56c0-a9fc-3574a8bd9246', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 38, 38, 'Mikloth became the father of Shimeam. They also lived with their brothers in Jerusalem, over against their brothers.'),
  ('6ccaf4de-5288-5063-a4b8-ba61055d4d90', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 39, 39, 'Ner became the father of Kish; and Kish became the father of Saul; and Saul became the father of Jonathan, and Malchishua, and Abinadab, and Eshbaal.'),
  ('611148da-5f0d-59cb-aca8-bda3fd2f8003', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 40, 40, 'The son of Jonathan was Merib Baal; and Merib Baal became the father of Micah.'),
  ('488e91bc-3422-50bd-af91-44b9c5ed2bae', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 41, 41, 'The sons of Micah: Pithon, and Melech, and Tahrea, [and Ahaz].'),
  ('3ee76ef8-c8e8-5337-a396-6c8867b6a076', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 42, 42, 'Ahaz became the father of Jarah; and Jarah became the father of Alemeth, and Azmaveth, and Zimri; and Zimri became the father of Moza;'),
  ('e02db5de-48da-594d-a00b-d909216d2cab', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 43, 43, 'and Moza became the father of Binea; and Rephaiah his son, Eleasah his son, Azel his son.'),
  ('e063b18f-71b2-53b2-ade6-e5a1e915fde3', 'cfb0551e-7efd-5c33-a3f8-903f339fce33', NULL, 44, 44, 'Azel had six sons, whose names are these: Azrikam, Bocheru, and Ishmael, and Sheariah, and Obadiah, and Hanan: these were the sons of Azel.'),
  ('334ddda1-f320-5166-a1c7-13c3fb5fb6de', '63966303-6145-5963-a81a-05438051a307', NULL, 1, 1, 'Now the Philistines fought against Israel: and the men of Israel fled from before the Philistines, and fell down slain on Mount Gilboa.'),
  ('0d4f28c4-f126-5138-a14f-ddbbe047e19d', '63966303-6145-5963-a81a-05438051a307', NULL, 2, 2, 'The Philistines followed hard after Saul and after his sons; and the Philistines killed Jonathan, and Abinadab, and Malchishua, the sons of Saul.'),
  ('676e62e2-aa8d-5d1e-a727-3f29ee2658f4', '63966303-6145-5963-a81a-05438051a307', NULL, 3, 3, 'The battle went hard against Saul, and the archers overtook him; and he was distressed by reason of the archers.'),
  ('70a2168b-eeee-5244-aa1e-578889609f66', '63966303-6145-5963-a81a-05438051a307', NULL, 4, 4, 'Then Saul said to his armor bearer, "Draw your sword, and thrust me through with it, lest these uncircumcised come and abuse me." But his armor bearer would not; for he was terrified. Therefore Saul took his sword, and fell on it.'),
  ('c2635bde-8366-50a0-a65d-f0ca99820dd3', '63966303-6145-5963-a81a-05438051a307', NULL, 5, 5, 'When his armor bearer saw that Saul was dead, he likewise fell on his sword, and died.'),
  ('172747af-3477-5e01-a171-9abf6bb8db10', '63966303-6145-5963-a81a-05438051a307', NULL, 6, 6, 'So Saul died, and his three sons; and all his house died together.'),
  ('2031c971-7108-56b2-a5e5-93686ca6ef3e', '63966303-6145-5963-a81a-05438051a307', NULL, 7, 7, 'When all the men of Israel who were in the valley saw that they fled, and that Saul and his sons were dead, they forsook their cities, and fled; and the Philistines came and lived in them.'),
  ('fef9dfa7-99f1-5320-aa11-b24f60333e79', '63966303-6145-5963-a81a-05438051a307', NULL, 8, 8, 'It happened on the next day, when the Philistines came to strip the slain, that they found Saul and his sons fallen on Mount Gilboa.'),
  ('cd11c444-5277-5792-af3f-c75d9453e2ab', '63966303-6145-5963-a81a-05438051a307', NULL, 9, 9, 'They stripped him, and took his head, and his armor, and sent into the land of the Philistines all around, to carry the news to their idols, and to the people.'),
  ('5ccd89ec-132c-54e8-a880-75ee15a5146d', '63966303-6145-5963-a81a-05438051a307', NULL, 10, 10, 'They put his armor in the house of their gods, and fastened his head in the house of Dagon.'),
  ('5a6e1856-110f-5e01-a88d-0104e4ed0338', '63966303-6145-5963-a81a-05438051a307', NULL, 11, 11, 'When all Jabesh Gilead heard all that the Philistines had done to Saul,'),
  ('8168212f-30af-5004-ae20-964c9351f130', '63966303-6145-5963-a81a-05438051a307', NULL, 12, 12, 'all the valiant men arose, and took away the body of Saul, and the bodies of his sons, and brought them to Jabesh, and buried their bones under the oak in Jabesh, and fasted seven days.'),
  ('7e8d856e-e16c-50f1-a2bb-ae9e3161dc73', '63966303-6145-5963-a81a-05438051a307', NULL, 13, 13, 'So Saul died for his trespass which he committed against Yahweh, because of the word of Yahweh, which he didn''t keep; and also because he asked counsel of one who had a familiar spirit, to inquire [thereby],'),
  ('fbc1d749-9608-5e4b-affa-58cebff460d5', '63966303-6145-5963-a81a-05438051a307', NULL, 14, 14, 'and didn''t inquire of Yahweh: therefore he killed him, and turned the kingdom to David the son of Jesse.'),
  ('501729fc-575e-56c4-a3ee-e33108c122f2', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 1, 1, 'Then all Israel gathered themselves to David to Hebron, saying, "Behold, we are your bone and your flesh.'),
  ('2bbf59e8-df2e-56df-a0ca-37286756e20e', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 2, 2, 'In times past, even when Saul was king, it was you who led out and brought in Israel. Yahweh your God said to you, ''You shall be shepherd of my people Israel, and you shall be prince over my people Israel.''"'),
  ('4cab745b-d7be-5293-ad95-c7da52475a6c', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 3, 3, 'So all the elders of Israel came to the king to Hebron; and David made a covenant with them in Hebron before Yahweh; and they anointed David king over Israel, according to the word of Yahweh by Samuel.'),
  ('2c7f95aa-7d53-54b3-a6ee-52aa075fce8d', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 4, 4, 'David and all Israel went to Jerusalem (the same is Jebus); and the Jebusites, the inhabitants of the land, were there.'),
  ('7b397b90-0666-5616-ade1-ff3fe091877f', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 5, 5, 'The inhabitants of Jebus said to David, "You shall not come in here." Nevertheless David took the stronghold of Zion. The same is the city of David.'),
  ('73f0678b-d4f8-57ad-a1d1-023598cbe765', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 6, 6, 'David said, "Whoever strikes the Jebusites first shall be chief and captain." Joab the son of Zeruiah went up first, and was made chief.'),
  ('98008c11-a577-50ee-ae93-704c4878fb27', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 7, 7, 'David lived in the stronghold; therefore they called it the city of David.'),
  ('cafb582a-7a8a-5b52-aba1-53ee896c3755', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 8, 8, 'He built the city all around, from Millo even around; and Joab repaired the rest of the city.'),
  ('d40688c0-803a-5652-a0c9-2fd3438af12c', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 9, 9, 'David grew greater and greater; for Yahweh of Armies was with him.'),
  ('60c8ba82-a585-5c44-a6be-cdea2856440a', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 10, 10, 'Now these are the chief of the mighty men whom David had, who showed themselves strong with him in his kingdom, together with all Israel, to make him king, according to the word of Yahweh concerning Israel.'),
  ('a41206fd-6b8d-50d0-a0e2-6e052101119e', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 11, 11, 'This is the number of the mighty men whom David had: Jashobeam, the son of a Hachmonite, the chief of the thirty; he lifted up his spear against three hundred and killed them at one time.'),
  ('0090f89a-47f3-5f59-a208-4b14631c1166', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 12, 12, 'After him was Eleazar the son of Dodo, the Ahohite, who was one of the three mighty men.'),
  ('1ec0b97f-0d37-53e9-a6d6-e2edae70ce81', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 13, 13, 'He was with David at Pasdammim, and there the Philistines were gathered together to battle, where there was a plot of ground full of barley; and the people fled from before the Philistines.'),
  ('4305e903-2eba-58c4-ac7f-5f373ce5e830', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 14, 14, 'They stood in the midst of the plot, and defended it, and killed the Philistines; and Yahweh saved them by a great victory.'),
  ('9275417e-3cc2-5eb5-a62d-0be36d80a201', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 15, 15, 'Three of the thirty chief men went down to the rock to David, into the cave of Adullam; and the army of the Philistines were encamped in the valley of Rephaim.'),
  ('8a44525a-f0a5-5151-a0c1-8ee7469d2c09', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 16, 16, 'David was then in the stronghold, and the garrison of the Philistines was then in Bethlehem.'),
  ('d8fe30bb-0733-503f-a669-aa5c95b3b863', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 17, 17, 'David longed, and said, "Oh that one would give me water to drink of the well of Bethlehem, which is by the gate!"'),
  ('2181cf66-c183-554e-ab22-a9e1afca3bec', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 18, 18, 'The three broke through the army of the Philistines, and drew water out of the well of Bethlehem, that was by the gate, and took it, and brought it to David: but David would not drink of it, but poured it out to Yahweh,'),
  ('f31eb778-af92-5074-acbd-4f3ec859f5f0', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 19, 19, 'and said, "My God forbid it me, that I should do this! Shall I drink the blood of these men who have put their lives in jeopardy?" For they risked their lives to bring it. Therefore he would not drink it. The three mighty men did these things.'),
  ('99e0d3eb-1d37-5644-a923-d07ff78a2185', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 20, 20, 'Abishai, the brother of Joab, he was chief of the three; for he lifted up his spear against three hundred and killed them, and had a name among the three.'),
  ('7df6e560-9bbe-559e-a118-062a80fa5028', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 21, 21, 'Of the three, he was more honorable than the two, and was made their captain: however he didn''t attain to the [first] three.'),
  ('b2c11d25-55b7-52e3-a60a-b66f4fb8914d', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 22, 22, 'Benaiah the son of Jehoiada, the son of a valiant man of Kabzeel, who had done mighty deeds, he killed the two [sons of] Ariel of Moab: he went down also and killed a lion in the midst of a pit in time of snow.'),
  ('1aa1ed30-0e43-5ead-a26b-d87a69654cd7', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 23, 23, 'He killed an Egyptian, a man of great stature, five cubits high; and in the Egyptian''s hand was a spear like a weaver''s beam; and he went down to him with a staff, and plucked the spear out of the Egyptian''s hand, and killed him with his own spear.'),
  ('4a1880c1-7c59-508b-a15c-1fa90529489a', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 24, 24, 'These things did Benaiah the son of Jehoiada, and had a name among the three mighty men.'),
  ('fef4d34b-b700-5861-aa40-b770b1667b6f', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 25, 25, 'Behold, he was more honorable than the thirty, but he didn''t attain to the [first] three: and David set him over his guard.'),
  ('ee5a0bb6-082a-57b0-a9e4-0f39ab082047', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 26, 26, 'Also the mighty men of the armies: Asahel the brother of Joab, Elhanan the son of Dodo of Bethlehem,'),
  ('0cb51add-8b55-5e44-a9ef-bc59a0a44aa5', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 27, 27, 'Shammoth the Harorite, Helez the Pelonite,'),
  ('9a3f4a49-5096-5977-aefd-97827378fb88', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 28, 28, 'Ira the son of Ikkesh the Tekoite, Abiezer the Anathothite,'),
  ('a1c0ce9d-4f6a-5695-a976-2040bfac806b', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 29, 29, 'Sibbecai the Hushathite, Ilai the Ahohite,'),
  ('b713cff8-7b97-53ad-abc1-e1360f343e3a', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 30, 30, 'Maharai the Netophathite, Heled the son of Baanah the Netophathite,'),
  ('15a582e6-dfae-5db5-a9d9-0aa13f6cde90', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 31, 31, 'Ithai the son of Ribai of Gibeah of the children of Benjamin, Benaiah the Pirathonite,'),
  ('28f82709-51e9-5168-a7bf-3ed2632e7b72', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 32, 32, 'Hurai of the brooks of Gaash, Abiel the Arbathite,'),
  ('8e9e8b9a-5bc4-53ef-ad78-7b8809f09647', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 33, 33, 'Azmaveth the Baharumite, Eliahba the Shaalbonite,'),
  ('c0595fd7-83fc-5b42-a674-6c3fbf8bcdf0', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 34, 34, 'the sons of Hashem the Gizonite, Jonathan the son of Shagee the Hararite,'),
  ('62be7696-631e-51b6-a65e-e79e01ae5e33', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 35, 35, 'Ahiam the son of Sacar the Hararite, Eliphal the son of Ur,'),
  ('b248fff1-be97-5d83-a364-5a0b454d79bd', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 36, 36, 'Hepher the Mecherathite, Ahijah the Pelonite,'),
  ('487f1c7f-b986-55d2-a3cf-434308ad6a2c', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 37, 37, 'Hezro the Carmelite, Naarai the son of Ezbai,'),
  ('f7206aba-dac8-5de8-ae77-30f8048e1bce', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 38, 38, 'Joel the brother of Nathan, Mibhar the son of Hagri,'),
  ('a79efcfb-8037-5b7d-a7f0-585a8353b41b', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 39, 39, 'Zelek the Ammonite, Naharai the Berothite, the armor bearer of Joab the son of Zeruiah,'),
  ('739ce423-ba86-58ec-a544-7f6e87e0af26', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 40, 40, 'Ira the Ithrite, Gareb the Ithrite,'),
  ('b5cc584c-cbcb-5fea-a691-68f0740301d7', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 41, 41, 'Uriah the Hittite, Zabad the son of Ahlai,'),
  ('11f7e3df-ceb7-5d46-a4f8-39829c5eecd9', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 42, 42, 'Adina the son of Shiza the Reubenite, a chief of the Reubenites, and thirty with him,'),
  ('372922b6-435f-5c6d-ac0e-79c1e203403d', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 43, 43, 'Hanan the son of Maacah, and Joshaphat the Mithnite,'),
  ('34a765f0-8235-596d-a6a0-9ac7cb7626db', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 44, 44, 'Uzzia the Ashterathite, Shama and Jeiel the sons of Hotham the Aroerite,'),
  ('bc23f706-42d7-57fb-a372-11eadeeeabf1', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 45, 45, 'Jediael the son of Shimri, and Joha his brother, the Tizite,'),
  ('83a9a5f3-4a56-5356-a894-ef12dc1a3d8b', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 46, 46, 'Eliel the Mahavite, and Jeribai, and Joshaviah, the sons of Elnaam, and Ithmah the Moabite,'),
  ('8cd8f72b-8a5a-5012-a510-1e3ee6ff62bf', '54b41a51-40c5-5ff6-ab3a-bc94dde6de1b', NULL, 47, 47, 'Eliel, and Obed, and Jaasiel the Mezobaite.'),
  ('506f8d95-f335-5cd8-a535-3e48e61f6321', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 1, 1, 'Now these are those who came to David to Ziklag, while he yet kept himself close because of Saul the son of Kish; and they were among the mighty men, his helpers in war.'),
  ('8c731277-72b7-54ac-aed4-7794b1ab9cd3', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 2, 2, 'They were armed with bows, and could use both the right hand and the left in slinging stones and in shooting arrows from the bow: they were of Saul''s brothers of Benjamin.'),
  ('545a4513-f72d-5a91-aabc-379780673593', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 3, 3, 'The chief was Ahiezer; then Joash, the sons of Shemaah the Gibeathite, and Jeziel, and Pelet, the sons of Azmaveth, and Beracah, and Jehu the Anathothite,'),
  ('977dbad8-d7b8-5d27-a921-2494c2a31075', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 4, 4, 'and Ishmaiah the Gibeonite, a mighty man among the thirty, and over the thirty, and Jeremiah, and Jahaziel, and Johanan, and Jozabad the Gederathite,'),
  ('bbb27b1d-aceb-5b84-a49f-a1c23c61ede5', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 5, 5, 'Eluzai, and Jerimoth, and Bealiah, and Shemariah, and Shephatiah the Haruphite,'),
  ('5d7475d8-da22-57dc-acc2-517d91965929', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 6, 6, 'Elkanah, and Isshiah, and Azarel, and Joezer, and Jashobeam, the Korahites,'),
  ('2b3bb60b-a45b-5fc8-a138-cdb0ec8a2868', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 7, 7, 'and Joelah, and Zebadiah, the sons of Jeroham of Gedor.'),
  ('fb00341a-fd4b-5c60-a46d-ee7060ff364a', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 8, 8, 'Of the Gadites there separated themselves to David to the stronghold in the wilderness, mighty men of valor, men trained for war, that could handle shield and spear; whose faces were like the faces of lions, and they were as swift as the roes on the mountains;'),
  ('42231078-99f5-5ace-abd9-685b3e0abbf3', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 9, 9, 'Ezer the chief, Obadiah the second, Eliab the third,'),
  ('b889d962-51b5-5e60-aee5-5387ddad0c3e', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 10, 10, 'Mishmannah the fourth, Jeremiah the fifth,'),
  ('3b8f3be5-12d6-5d0c-a85e-e6f81d3f4163', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 11, 11, 'Attai the sixth, Eliel the seventh,'),
  ('33b40863-7d8c-5df6-af2b-d2789a90edf2', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 12, 12, 'Johanan the eighth, Elzabad the ninth,'),
  ('0df9fe19-811e-5b33-aadb-e759cf14193a', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 13, 13, 'Jeremiah the tenth, Machbannai the eleventh.'),
  ('bff50b8b-b5b9-5075-a42f-94615249277a', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 14, 14, 'These of the sons of Gad were captains of the army: he who was least was equal to one hundred, and the greatest to one thousand.'),
  ('826e5c1e-a061-5eeb-a5b7-e283093061ac', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 15, 15, 'These are those who went over the Jordan in the first month, when it had overflowed all its banks; and they put to flight all them of the valleys, both toward the east, and toward the west.'),
  ('608ca864-8679-5a60-a169-e76544f969e4', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 16, 16, 'There came of the children of Benjamin and Judah to the stronghold to David.'),
  ('481422a3-a91b-5e16-a7e1-5f69d1b094fa', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 17, 17, 'David went out to meet them, and answered them, "If you have come peaceably to me to help me, my heart shall be knit to you; but if you have come to betray me to my adversaries, since there is no wrong in my hands, may the God of our fathers look thereon, and rebuke it."'),
  ('1f0c2a13-ca8f-5391-a68c-21e2d72a73de', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 18, 18, 'Then the Spirit came on Amasai, who was chief of the thirty, [and he said], "We are yours, David, and on your side, you son of Jesse: peace, peace be to you, and peace be to your helpers; for your God helps you." Then David received them, and made them captains of the band.'),
  ('ea470342-8bac-571c-a313-0c7abf1617c5', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 19, 19, 'Of Manasseh also there fell away some to David, when he came with the Philistines against Saul to battle; but they didn''t help them; for the lords of the Philistines sent him away after consultation, saying, "He will fall away to his master Saul to the jeopardy of our heads."'),
  ('730aeab5-b6a7-523f-ad41-9ba408dc6abd', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 20, 20, 'As he went to Ziklag, there fell to him of Manasseh, Adnah, and Jozabad, and Jediael, and Michael, and Jozabad, and Elihu, and Zillethai, captains of thousands who were of Manasseh.'),
  ('df53ed6d-7be1-55d6-ac61-2871b825d16b', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 21, 21, 'They helped David against the band of rovers: for they were all mighty men of valor, and were captains in the army.'),
  ('24ab5bcb-c2a7-5e96-a2a3-61bfc0bec734', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 22, 22, 'For from day to day men came to David to help him, until there was a great army, like the army of God.'),
  ('8181b8f8-bc22-55a7-aaf7-8dc541882469', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 23, 23, 'These are the numbers of the heads of those who were armed for war, who came to David to Hebron, to turn the kingdom of Saul to him, according to the word of Yahweh.'),
  ('e0bb65de-f536-566a-a97b-dc983f2d1f78', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 24, 24, 'The children of Judah who bore shield and spear were six thousand and eight hundred, armed for war.'),
  ('74bb73dd-03e2-5207-ab90-f8049e0a185a', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 25, 25, 'Of the children of Simeon, mighty men of valor for the war, seven thousand and one hundred.'),
  ('6d96db6b-b496-5992-a33e-b7c874f2c93d', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 26, 26, 'Of the children of Levi four thousand and six hundred.'),
  ('9e28aedf-f9aa-523f-a57b-d43237dd62a1', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 27, 27, 'Jehoiada was the leader of [the house of] Aaron; and with him were three thousand and seven hundred,'),
  ('74b9a46f-182b-55bb-ad03-e28fed7c7705', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 28, 28, 'and Zadok, a young man mighty of valor, and of his father''s house twenty-two captains.'),
  ('2b42ae29-6ae9-5986-ac2c-0310eab1735d', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 29, 29, 'Of the children of Benjamin, the brothers of Saul, three thousand: for hitherto the greatest part of them had kept their allegiance to the house of Saul.'),
  ('1be5b1a5-d49f-50bc-ab95-ef70da010224', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 30, 30, 'Of the children of Ephraim twenty thousand eight hundred, mighty men of valor, famous men in their fathers'' houses.'),
  ('c4e42ba7-6775-5002-ac32-f7f205278d98', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 31, 31, 'Of the half-tribe of Manasseh eighteen thousand, who were mentioned by name, to come and make David king.'),
  ('1745ff99-4c61-575a-a188-33268da3db64', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 32, 32, 'Of the children of Issachar, men who had understanding of the times, to know what Israel ought to do, the heads of them were two hundred; and all their brothers were at their commandment.'),
  ('780acb1e-16e2-5261-aa87-1c43d84e1441', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 33, 33, 'Of Zebulun, such as were able to go out in the army, who could set the battle in array, with all kinds of instruments of war, fifty thousand, and who could order [the battle array, and were] not of double heart.'),
  ('e4046993-c44d-5016-a0bf-dc7cd40a9fc1', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 34, 34, 'Of Naphtali one thousand captains, and with them with shield and spear thirty-seven thousand.'),
  ('f4db54b5-c37f-51d0-a122-cdaa7ceb1bee', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 35, 35, 'Of the Danites who could set the battle in array, twenty-eight thousand six hundred.'),
  ('8bf0340b-4109-5ecf-a8fe-c9d30b68176a', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 36, 36, 'Of Asher, such as were able to go out in the army, who could set the battle in array, forty thousand.'),
  ('b96956f6-2ec2-5b7d-a1b9-dc000dc09ec9', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 37, 37, 'On the other side of the Jordan, of the Reubenites, and the Gadites, and of the half-tribe of Manasseh, with all kinds of instruments of war for the battle, one hundred twenty thousand.'),
  ('cc6e884c-dfd5-5141-a8a0-da4421343404', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 38, 38, 'All these being men of war, who could order the battle array, came with a perfect heart to Hebron, to make David king over all Israel: and all the rest also of Israel were of one heart to make David king.'),
  ('a2122c46-b955-59b1-a30b-cba360f54893', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 39, 39, 'They were there with David three days, eating and drinking; for their brothers had made preparation for them.'),
  ('72b77a45-8837-5d5e-a947-76aa6ae95271', '37f0c73c-419d-5a33-aed2-01e6c00df17c', NULL, 40, 40, 'Moreover those who were near to them, [even] as far as Issachar and Zebulun and Naphtali, brought bread on donkeys, and on camels, and on mules, and on oxen, food of meal, cakes of figs, and clusters of raisins, and wine, and oil, and cattle, and sheep in abundance: for there was joy in Israel.'),
  ('9c83b804-7f7b-5fee-a294-3c3292d78043', '210f6e7e-d7f1-5c95-ad7b-bbd5484962cb', NULL, 1, 1, 'David consulted with the captains of thousands and of hundreds, even with every leader.'),
  ('9d41801a-dcc1-5253-a071-878b17929d36', '210f6e7e-d7f1-5c95-ad7b-bbd5484962cb', NULL, 2, 2, 'David said to all the assembly of Israel, "If it seems good to you, and if it is of Yahweh our God, let us send abroad everywhere to our brothers who are left in all the land of Israel, with whom the priests and Levites are in their cities that have suburbs, that they may gather themselves to us;'),
  ('600d5024-a859-57cc-a58d-713b44260a09', '210f6e7e-d7f1-5c95-ad7b-bbd5484962cb', NULL, 3, 3, 'and let us bring again the ark of our God to us. For we didn''t seek it in the days of Saul."'),
  ('d55bd45c-e854-55ca-ac24-0e6375580330', '210f6e7e-d7f1-5c95-ad7b-bbd5484962cb', NULL, 4, 4, 'All the assembly said that they would do so; for the thing was right in the eyes of all the people.'),
  ('f4ac5ddf-6605-5f3d-acb7-d2d8956c0605', '210f6e7e-d7f1-5c95-ad7b-bbd5484962cb', NULL, 5, 5, 'So David assembled all Israel together, from the Shihor [the brook] of Egypt even to the entrance of Hamath, to bring the ark of God from Kiriath Jearim.'),
  ('17dd4cab-e7e9-58be-aaa8-c41a40a6aaf5', '210f6e7e-d7f1-5c95-ad7b-bbd5484962cb', NULL, 6, 6, 'David went up, and all Israel, to Baalah, [that is], to Kiriath Jearim, which belonged to Judah, to bring up from there the ark of God Yahweh that sits [above] the cherubim, that is called by the Name.'),
  ('edcc16bf-7e2f-5e92-a31f-59b7910d67ea', '210f6e7e-d7f1-5c95-ad7b-bbd5484962cb', NULL, 7, 7, 'They carried the ark of God on a new cart, [and brought it] out of the house of Abinadab: and Uzza and Ahio drove the cart.'),
  ('483acbbb-06eb-518d-a7f5-4c7583cda1eb', '210f6e7e-d7f1-5c95-ad7b-bbd5484962cb', NULL, 8, 8, 'David and all Israel played before God with all their might, even with songs, and with harps, and with stringed instruments, and with tambourines, and with cymbals, and with trumpets.'),
  ('11dc8dec-afb6-5d4e-a21a-eec630ab0511', '210f6e7e-d7f1-5c95-ad7b-bbd5484962cb', NULL, 9, 9, 'When they came to the threshing floor of Chidon, Uzza put forth his hand to hold the ark; for the oxen stumbled.'),
  ('1f26ce8a-96ec-5af0-a08e-e3edf9832e96', '210f6e7e-d7f1-5c95-ad7b-bbd5484962cb', NULL, 10, 10, 'The anger of Yahweh was kindled against Uzza, and he struck him, because he put forth his hand to the ark; and there he died before God.'),
  ('a5805072-e10a-5d5b-a5e3-c6684cae0132', '210f6e7e-d7f1-5c95-ad7b-bbd5484962cb', NULL, 11, 11, 'David was displeased, because Yahweh had broken forth on Uzza; and he called that place Perez Uzza, to this day.'),
  ('b79ce252-a7bc-5faa-a24d-bb59cad0674d', '210f6e7e-d7f1-5c95-ad7b-bbd5484962cb', NULL, 12, 12, 'David was afraid of God that day, saying, "How shall I bring the ark of God home to me?"'),
  ('567557c7-19be-5411-adb2-62ce34b131b0', '210f6e7e-d7f1-5c95-ad7b-bbd5484962cb', NULL, 13, 13, 'So David didn''t move the ark to him into the city of David, but carried it aside into the house of Obed-Edom the Gittite.'),
  ('f5b79632-7b50-56db-a15e-4d17cb9b249b', '210f6e7e-d7f1-5c95-ad7b-bbd5484962cb', NULL, 14, 14, 'The ark of God remained with the family of Obed-Edom in his house three months: and Yahweh blessed the house of Obed-Edom, and all that he had.'),
  ('58d23b5c-cbaa-5997-a002-c69e8c9c3413', '49b50c47-86fe-5df7-ae3e-84f295997f6a', NULL, 1, 1, 'Hiram king of Tyre sent messengers to David, and cedar trees, and masons, and carpenters, to build him a house.'),
  ('11169616-2051-51fe-a022-fb9d41e85c26', '49b50c47-86fe-5df7-ae3e-84f295997f6a', NULL, 2, 2, 'David perceived that Yahweh had established him king over Israel; for his kingdom was exalted on high, for his people Israel''s sake.'),
  ('1620c04f-f951-5ebe-a57b-64cf4dea191c', '49b50c47-86fe-5df7-ae3e-84f295997f6a', NULL, 3, 3, 'David took more wives at Jerusalem; and David became the father of more sons and daughters.'),
  ('a4988fa5-7764-5951-ab05-71768a5750c9', '49b50c47-86fe-5df7-ae3e-84f295997f6a', NULL, 4, 4, 'These are the names of the children whom he had in Jerusalem: Shammua, and Shobab, Nathan, and Solomon,'),
  ('de5a051b-0abb-5993-a5b3-cb22dd5b7ac9', '49b50c47-86fe-5df7-ae3e-84f295997f6a', NULL, 5, 5, 'and Ibhar, and Elishua, and Elpelet,'),
  ('3e1fe369-216e-5c00-a997-a650098ef77d', '49b50c47-86fe-5df7-ae3e-84f295997f6a', NULL, 6, 6, 'and Nogah, and Nepheg, and Japhia,'),
  ('46c3ef08-f1f5-5f64-abd2-69755167c862', '49b50c47-86fe-5df7-ae3e-84f295997f6a', NULL, 7, 7, 'and Elishama, and Beeliada, and Eliphelet.'),
  ('a0b02ef9-ddc9-58dd-aca1-1585376fec1f', '49b50c47-86fe-5df7-ae3e-84f295997f6a', NULL, 8, 8, 'When the Philistines heard that David was anointed king over all Israel, all the Philistines went up to seek David: and David heard of it, and went out against them.'),
  ('8dfe242d-8b86-5b86-a2f7-fc6cbbbc07aa', '49b50c47-86fe-5df7-ae3e-84f295997f6a', NULL, 9, 9, 'Now the Philistines had come and made a raid in the valley of Rephaim.'),
  ('615e1979-5e98-52d5-acd4-22c3a30f5c38', '49b50c47-86fe-5df7-ae3e-84f295997f6a', NULL, 10, 10, 'David inquired of God, saying, "Shall I go up against the Philistines? Will you deliver them into my hand?" Yahweh said to him, "Go up; for I will deliver them into your hand."'),
  ('bc0f6a9e-f2b1-5930-aeeb-54a7f02ca422', '49b50c47-86fe-5df7-ae3e-84f295997f6a', NULL, 11, 11, 'So they came up to Baal Perazim, and David struck them there; and David said, God has broken my enemies by my hand, like the breach of waters. Therefore they called the name of that place Baal Perazim.'),
  ('e2bc2310-9aa3-5209-ac89-c6e7708971da', '49b50c47-86fe-5df7-ae3e-84f295997f6a', NULL, 12, 12, 'They left their gods there; and David gave commandment, and they were burned with fire.'),
  ('bf6e794e-e7d2-5d9d-a515-ec46fad4733b', '49b50c47-86fe-5df7-ae3e-84f295997f6a', NULL, 13, 13, 'The Philistines yet again made a raid in the valley.'),
  ('cec6c0b3-8554-54bf-a3d2-13e9dd3365ea', '49b50c47-86fe-5df7-ae3e-84f295997f6a', NULL, 14, 14, 'David inquired again of God; and God said to him, "You shall not go up after them. Turn away from them, and come on them over against the mulberry trees.'),
  ('6e3c454c-6952-505b-a59f-527ed6260d04', '49b50c47-86fe-5df7-ae3e-84f295997f6a', NULL, 15, 15, 'It shall be, when you hear the sound of marching in the tops of the mulberry trees, that then you shall go out to battle; for God has gone out before you to strike the army of the Philistines."'),
  ('7b9153a7-98a1-5adb-afd4-c17064ba07dd', '49b50c47-86fe-5df7-ae3e-84f295997f6a', NULL, 16, 16, 'David did as God commanded him: and they struck the army of the Philistines from Gibeon even to Gezer.'),
  ('ce2c9076-6ef2-5684-a452-88ad98285f4e', '49b50c47-86fe-5df7-ae3e-84f295997f6a', NULL, 17, 17, 'The fame of David went out into all lands; and Yahweh brought the fear of him on all nations.'),
  ('1818b543-5dc9-58b1-a4a4-a57df2066db1', 'e0068aeb-d802-5493-ad12-56550e885f30', NULL, 1, 1, '[David] made him houses in the city of David; and he prepared a place for the ark of God, and pitched for it a tent.'),
  ('e80a2018-6a78-55ff-a812-ca767f49435b', 'e0068aeb-d802-5493-ad12-56550e885f30', NULL, 2, 2, 'Then David said, "No one ought to carry the ark of God but the Levites. For Yahweh has chosen them to carry the ark of God, and to minister to him forever."'),
  ('4a425438-4f06-5f2f-a299-2474821f0922', 'e0068aeb-d802-5493-ad12-56550e885f30', NULL, 3, 3, 'David assembled all Israel at Jerusalem, to bring up the ark of Yahweh to its place, which he had prepared for it.'),
  ('08b05c46-a052-5c63-a281-71e76b1ea016', 'e0068aeb-d802-5493-ad12-56550e885f30', NULL, 4, 4, 'David gathered together the sons of Aaron, and the Levites:'),
  ('63f376f1-9d34-5cf9-a233-d8cbafebd313', 'e0068aeb-d802-5493-ad12-56550e885f30', NULL, 5, 5, 'of the sons of Kohath, Uriel the chief, and his brothers one hundred twenty;'),
  ('76954ce5-c68c-51c5-a4cd-264408f3db85', 'e0068aeb-d802-5493-ad12-56550e885f30', NULL, 6, 6, 'of the sons of Merari, Asaiah the chief, and his brothers two hundred twenty;'),
  ('611f3f6b-250b-5d2d-ab86-e2596c7c5768', 'e0068aeb-d802-5493-ad12-56550e885f30', NULL, 7, 7, 'of the sons of Gershom, Joel the chief, and his brothers one hundred thirty;'),
  ('7664fa48-1af6-5685-ade2-1ca96b6b15cc', 'e0068aeb-d802-5493-ad12-56550e885f30', NULL, 8, 8, 'of the sons of Elizaphan, Shemaiah the chief, and his brothers two hundred;'),
  ('d5960d26-0621-50fa-ab3e-3ab442a3fd5d', 'e0068aeb-d802-5493-ad12-56550e885f30', NULL, 9, 9, 'of the sons of Hebron, Eliel the chief, and his brothers eighty;'),
  ('aee411d5-6e8a-5bd9-a3a4-1ae548a7b793', 'e0068aeb-d802-5493-ad12-56550e885f30', NULL, 10, 10, 'of the sons of Uzziel, Amminadab the chief, and his brothers one hundred twelve.'),
  ('a3474439-da7f-5061-a727-22fa3e50e2bb', 'e0068aeb-d802-5493-ad12-56550e885f30', NULL, 11, 11, 'David called for Zadok and Abiathar the priests, and for the Levites, for Uriel, Asaiah, and Joel, Shemaiah, and Eliel, and Amminadab,'),
  ('0637c0f0-74e1-5c55-a7ad-7f23822499f0', 'e0068aeb-d802-5493-ad12-56550e885f30', NULL, 12, 12, 'and said to them, "You are the heads of the fathers'' [houses] of the Levites. Sanctify yourselves, both you and your brothers, that you may bring up the ark of Yahweh, the God of Israel, to the place that I have prepared for it.'),
  ('7c75d49a-e857-5a41-a795-340ef963e7ae', 'e0068aeb-d802-5493-ad12-56550e885f30', NULL, 13, 13, 'For because you didn''t carry it at first, Yahweh our God made broke out against us, because we didn''t seek him according to the ordinance."'),
  ('bf52df8e-97a6-5e97-af74-3273b80aa0c2', 'e0068aeb-d802-5493-ad12-56550e885f30', NULL, 14, 14, 'So the priests and the Levites sanctified themselves to bring up the ark of Yahweh, the God of Israel.'),
  ('7de796ac-d1c1-5f48-acfa-c46f57c25b31', 'e0068aeb-d802-5493-ad12-56550e885f30', NULL, 15, 15, 'The children of the Levites bore the ark of God on their shoulders with the poles thereon, as Moses commanded according to the word of Yahweh.'),
  ('844b9e4d-d43b-5f65-aa5c-c9644bdadda4', 'e0068aeb-d802-5493-ad12-56550e885f30', NULL, 16, 16, 'David spoke to the chief of the Levites to appoint their brothers the singers, with instruments of music, stringed instruments and harps and cymbals, sounding aloud and lifting up the voice with joy.'),
  ('b8606774-9dc4-5955-a17a-6c29b934fba5', 'e0068aeb-d802-5493-ad12-56550e885f30', NULL, 17, 17, 'So the Levites appointed Heman the son of Joel; and of his brothers, Asaph the son of Berechiah; and of the sons of Merari their brothers, Ethan the son of Kushaiah;'),
  ('17991da6-0ab2-51c4-ad2b-9875e6bfeb4b', 'e0068aeb-d802-5493-ad12-56550e885f30', NULL, 18, 18, 'and with them their brothers of the second degree, Zechariah, Ben, and Jaaziel, and Shemiramoth, and Jehiel, and Unni, Eliab, and Benaiah, and Maaseiah, and Mattithiah, and Eliphelehu, and Mikneiah, and Obed-Edom, and Jeiel, the doorkeepers.'),
  ('f4c8c0cc-d46f-5f21-aef5-b2a159472850', 'e0068aeb-d802-5493-ad12-56550e885f30', NULL, 19, 19, 'So the singers, Heman, Asaph, and Ethan, [were appointed] with cymbals of brass to sound aloud;'),
  ('88f064a7-c8ec-5616-a367-1ac9f3f4269f', 'e0068aeb-d802-5493-ad12-56550e885f30', NULL, 20, 20, 'and Zechariah, and Aziel, and Shemiramoth, and Jehiel, and Unni, and Eliab, and Maaseiah, and Benaiah, with stringed instruments set to Alamoth;'),
  ('4b5d285b-fa0a-5c3c-a0df-4119eb6d6aa6', 'e0068aeb-d802-5493-ad12-56550e885f30', NULL, 21, 21, 'and Mattithiah, and Eliphelehu, and Mikneiah, and Obed-Edom, and Jeiel, and Azaziah, with harps tuned to the eight-stringed lyre, to lead.'),
  ('b6158981-f733-5e75-a2b2-1bf34acb9adf', 'e0068aeb-d802-5493-ad12-56550e885f30', NULL, 22, 22, 'Chenaniah, chief of the Levites, was over the song: he instructed about the song, because he was skillful.'),
  ('320e76a6-d4f9-5a7b-acfd-164e058b9e8d', 'e0068aeb-d802-5493-ad12-56550e885f30', NULL, 23, 23, 'Berechiah and Elkanah were doorkeepers for the ark.'),
  ('e2c8ac0d-7de1-52e5-a0d9-3b9178fcfe34', 'e0068aeb-d802-5493-ad12-56550e885f30', NULL, 24, 24, 'Shebaniah, and Joshaphat, and Nethanel, and Amasai, and Zechariah, and Benaiah, and Eliezer, the priests, did blow the trumpets before the ark of God: and Obed-Edom and Jehiah were doorkeepers for the ark.'),
  ('3ad5e3d6-e5b8-5647-aaa3-7645857837d2', 'e0068aeb-d802-5493-ad12-56550e885f30', NULL, 25, 25, 'So David, and the elders of Israel, and the captains over thousands, went to bring up the ark of the covenant of Yahweh out of the house of Obed-Edom with joy.'),
  ('b5ef637e-426b-5ac2-a911-52391ae0f926', 'e0068aeb-d802-5493-ad12-56550e885f30', NULL, 26, 26, 'It happened, when God helped the Levites who bore the ark of the covenant of Yahweh, that they sacrificed seven bulls and seven rams.'),
  ('f401401e-5e54-59d9-ae4a-8952141a0fe9', 'e0068aeb-d802-5493-ad12-56550e885f30', NULL, 27, 27, 'David was clothed with a robe of fine linen, and all the Levites who bore the ark, and the singers, and Chenaniah the master of the song [with] the singers: and David had on him an ephod of linen.'),
  ('8a6a326f-8903-51d0-aa87-89eda35ee19d', 'e0068aeb-d802-5493-ad12-56550e885f30', NULL, 28, 28, 'Thus all Israel brought up the ark of the covenant of Yahweh with shouting, and with sound of the cornet, and with trumpets, and with cymbals, sounding aloud with stringed instruments and harps.'),
  ('6b89e851-0901-5a0b-a161-2049f5041ade', 'e0068aeb-d802-5493-ad12-56550e885f30', NULL, 29, 29, 'It happened, as the ark of the covenant of Yahweh came to the city of David, that Michal the daughter of Saul looked out at the window, and saw king David dancing and playing; and she despised him in her heart.'),
  ('c98a3863-4501-53cd-a098-0971336b40a3', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 1, 1, 'They brought in the ark of God, and set it in the midst of the tent that David had pitched for it: and they offered burnt offerings and peace offerings before God.'),
  ('65172ddf-a857-5a6b-a923-de6ff1c4fb5b', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 2, 2, 'When David had made an end of offering the burnt offering and the peace offerings, he blessed the people in the name of Yahweh.'),
  ('55bc4f2c-e7e4-58ef-a09f-4c7dea460d45', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 3, 3, 'He dealt to everyone of Israel, both man and woman, to every one a loaf of bread, and a portion [of flesh], and a cake of raisins.'),
  ('6ef33078-f8e2-5cc2-a669-edfc1c3f8754', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 4, 4, 'He appointed certain of the Levites to minister before the ark of Yahweh, and to celebrate and to thank and praise Yahweh, the God of Israel:'),
  ('39d11c24-8e03-55db-a959-e36648c40065', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 5, 5, 'Asaph the chief, and second to him Zechariah, Jeiel, and Shemiramoth, and Jehiel, and Mattithiah, and Eliab, and Benaiah, and Obed-Edom, and Jeiel, with stringed instruments and with harps; and Asaph with cymbals, sounding aloud;'),
  ('13215e1c-9153-55be-ae90-50ac20d3eb47', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 6, 6, 'and Benaiah and Jahaziel the priests with trumpets continually, before the ark of the covenant of God.'),
  ('4083aa36-048e-5fa1-a532-ccf577ab4795', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 7, 7, 'Then on that day David first ordained to give thanks to Yahweh, by the hand of Asaph and his brothers.'),
  ('787f6c6a-f972-5977-ac4f-2cb31c8c75a0', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 8, 8, 'Oh give thanks to Yahweh. Call on his name. Make his doings known among the peoples.'),
  ('d8bd0d6b-1fd2-595b-ad22-de506a490c35', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 9, 9, 'Sing to him. Sing praises to him. Tell of all his marvelous works.'),
  ('f8a868d6-fd04-587a-ae6b-42786254aee6', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 10, 10, 'Glory in his holy name. Let the heart of those who seek Yahweh rejoice.'),
  ('33ec1519-6b92-582e-a65f-4f1cd3457e49', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 11, 11, 'Seek Yahweh and his strength. Seek his face forever more.'),
  ('e8b4de1a-f319-5e6f-a1cb-00f495fa0301', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 12, 12, 'Remember his marvelous works that he has done, his wonders, and the judgments of his mouth,'),
  ('58d37296-400d-5f57-a1b5-375a8158a889', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 13, 13, 'you seed of Israel his servant, you children of Jacob, his chosen ones.'),
  ('0aaa63e3-7aa2-57f1-a2b7-a2f5e9e8fc3e', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 14, 14, 'He is Yahweh our God. His judgments are in all the earth.'),
  ('c1f8f72f-93f7-5194-a88f-3bcf93f16642', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 15, 15, 'Remember his covenant forever, the word which he commanded to a thousand generations,'),
  ('8016a895-31ac-51c3-a445-ce7be66312c9', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 16, 16, '[the covenant] which he made with Abraham, his oath to Isaac.'),
  ('99b918c8-4dd9-5370-a694-9cc56aeb60ac', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 17, 17, 'He confirmed the same to Jacob for a statute, and to Israel for an everlasting covenant,'),
  ('3db24816-108b-51b8-ab55-3614723e754c', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 18, 18, 'saying, "I will give you the land of Canaan, The lot of your inheritance,"'),
  ('06fa428c-9a2f-50e8-a564-ab3a5f836941', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 19, 19, 'when you were but a few men in number, yes, very few, and foreigners were in it.'),
  ('c60891a7-7c16-5d82-a82d-9ba35b5c4f1b', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 20, 20, 'They went about from nation to nation, from one kingdom to another people.'),
  ('cccea9ac-a807-57e4-ac02-aa62c4f0fc60', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 21, 21, 'He allowed no man to do them wrong. Yes, he reproved kings for their sakes,'),
  ('c381e004-4323-52fe-adbf-5a8aef5d834a', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 22, 22, '"Don''t touch my anointed ones! Do my prophets no harm!"'),
  ('8b235d1c-8df4-5038-a8b3-90172603e694', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 23, 23, 'Sing to Yahweh, all the earth! Display his salvation from day to day.'),
  ('118e6d1b-a790-50fc-a905-0281e6522cea', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 24, 24, 'Declare his glory among the nations, and his marvelous works among all the peoples.'),
  ('bafbc6ed-e017-5998-a12c-8ae50a6b90db', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 25, 25, 'For great is Yahweh, and greatly to be praised. He also is to be feared above all gods.'),
  ('540cf707-4fda-5561-ac39-5a6cd7e62dcc', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 26, 26, 'For all the gods of the peoples are idols, but Yahweh made the heavens.'),
  ('021311c9-a516-521a-adc5-f2969f306775', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 27, 27, 'Honor and majesty are before him. Strength and gladness are in his place.'),
  ('8e9a675a-290e-512f-aa2d-4b0abed80a3d', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 28, 28, 'Ascribe to Yahweh, you relatives of the peoples, ascribe to Yahweh glory and strength!'),
  ('031a598e-a4bd-5a40-adb9-73d5222785c8', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 29, 29, 'Ascribe to Yahweh the glory due to his name. Bring an offering, and come before him. Worship Yahweh in holy array.'),
  ('bb54edee-da91-5435-a0af-cfee752eeb4a', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 30, 30, 'Tremble before him, all the earth. The world also is established that it can''t be moved.'),
  ('fb4b77e5-535c-5de8-a428-abd740c7a1a0', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 31, 31, 'Let the heavens be glad, and let the earth rejoice! Let them say among the nations, "Yahweh reigns!"'),
  ('8478342e-8c40-5ec1-a98b-f5c0ff554c37', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 32, 32, 'Let the sea roar, and its fullness! Let the field exult, and all that is therein!'),
  ('a70c86a4-9724-5c5a-aac4-3d8224f03e0c', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 33, 33, 'Then the trees of the forest will sing for joy before Yahweh, for he comes to judge the earth.'),
  ('3a518c07-74b2-5b43-aedf-7794c6eeded7', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 34, 34, 'Oh give thanks to Yahweh, for he is good, for his loving kindness endures forever.'),
  ('3fb6f95a-b2ea-5523-a303-8c252b0cb682', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 35, 35, 'Say, "Save us, God of our salvation! Gather us together and deliver us from the nations, to give thanks to your holy name, to triumph in your praise."'),
  ('73cb64bb-ed41-5e20-a427-af65aa4da4d7', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 36, 36, 'Blessed be Yahweh, the God of Israel, from everlasting even to everlasting. All the people said, "Amen," and praised Yahweh.'),
  ('279e0f6e-0dcd-50c6-a511-300f423e7803', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 37, 37, 'So he left there, before the ark of the covenant of Yahweh, Asaph and his brothers, to minister before the ark continually, as every day''s work required;'),
  ('5fc277b2-ec5d-5652-adce-94fe5ca12928', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 38, 38, 'and Obed-Edom with their brothers, sixty-eight; Obed-Edom also the son of Jeduthun and Hosah to be doorkeepers;'),
  ('4533f66e-b185-51fc-a090-54c94359f119', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 39, 39, 'and Zadok the priest, and his brothers the priests, before the tabernacle of Yahweh in the high place that was at Gibeon,'),
  ('c9928ccc-c517-5fd1-af7f-e5a5d91b26ef', '6f0366b7-7be7-5d16-a1ed-04fc009c0cbe', NULL, 40, 40, 'to offer burnt offerings to Yahweh on the altar of burnt offering continually morning and evening, even according to all that is written in the law of Yahweh, which he commanded to Israel;')
